#!/usr/bin/env python3
"""NPC-team trusted bootstrap gate (schema npc-brand-gate/1).

Purpose: before an official entry point loads a protected module, verify that
the release is intact and that the attribution policy still holds.  A failure
stops the *protected* module; diagnostics, help and trusted restore stay
available, and no user data is ever deleted.

Honest scope (must not be overstated in docs):

*   This can detect removal of the attribution, changes to protected content and
    replacement of files.  It is a detection-and-refusal mechanism bound to a
    release manifest plus (when available) a detached release signature.
*   It cannot stop a party who owns the full source tree and the machine from
    editing this checker or re-deriving a self-consistent package.  "Cannot be
    removed" is never an unconditional guarantee.
*   Authenticity is reported separately from integrity.  With no pinned release
    key the authenticity layer reports ``missing`` and is never upgraded to ok.

Layers reported independently (never collapsed into one boolean):
    integrity / authenticity / attribution / functionality / coverage
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
DEFAULT_ROOT = HERE.parent

POLICY_REL = "references/brand-policy.json"
SIDECAR_REL = "references/attribution-sidecar.json"
MANIFEST_REL = "NPC-team-v6-manifest.json"
STATEMENT_REL = "NPC-team-release-statement.json"
TRUST_REL = "references/trust-root.json"

ERROR_SIGNATURE_INVALID = "SIGNATURE_INVALID"
ERROR_TRUST_ROOT_MISMATCH = "TRUST_ROOT_MISMATCH"
ERROR_CONTENT_CHANGED = "CONTENT_CHANGED"
ERROR_ATTRIBUTION_MISSING = "ATTRIBUTION_MISSING"
ERROR_DEPENDENCY_UNAVAILABLE = "DEPENDENCY_UNAVAILABLE"
ERROR_UNSUPPORTED_PLATFORM = "UNSUPPORTED_PLATFORM"
ERROR_MANIFEST_MISSING = "MANIFEST_MISSING"


def _sha256_bytes(data: bytes) -> str:
    return "sha256:" + hashlib.sha256(data).hexdigest()


def _sha256_file(path: Path) -> str:
    return _sha256_bytes(path.read_bytes())


def _load_json(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))


def policy_digest(policy: dict) -> str:
    core = {k: v for k, v in policy.items() if k != "policy_digest"}
    blob = json.dumps(core, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return _sha256_bytes(blob)


# --------------------------------------------------------------------------- layers

def check_integrity(root: Path) -> dict:
    path = root / MANIFEST_REL
    if not path.is_file():
        return {"ok": False, "status": "missing", "detail": MANIFEST_REL + " not found"}
    try:
        manifest = _load_json(path)
    except (OSError, ValueError) as exc:
        return {"ok": False, "status": "invalid", "detail": type(exc).__name__}
    bad = []
    missing = []
    entries = manifest.get("files") or []
    for e in entries:
        rel = e.get("path")
        target = root / rel
        if not target.is_file():
            missing.append(rel)
            continue
        raw = target.read_bytes()
        if len(raw) != e.get("bytes") or _sha256_bytes(raw) != e.get("sha256"):
            bad.append(rel)
    ok = not bad and not missing and manifest.get("file_count") == len(entries)
    return {
        "ok": ok,
        "status": "ok" if ok else "changed",
        "entries": len(entries),
        "changed": bad[:20],
        "missing": missing[:20],
        "manifest_digest": _sha256_file(path),
    }


def check_attribution(root: Path) -> dict:
    problems = []
    policy_path = root / POLICY_REL
    if not policy_path.is_file():
        return {"ok": False, "status": "missing", "problems": [POLICY_REL]}
    try:
        policy = _load_json(policy_path)
    except (OSError, ValueError) as exc:
        return {"ok": False, "status": "invalid", "problems": [type(exc).__name__]}
    brand = policy.get("brand") or {}
    for key in ("owner_qq", "group_qq", "brand", "motto"):
        if not brand.get(key):
            problems.append("brand_field_missing:" + key)
    try:
        sys.path.insert(0, str(HERE))
        import file_policy as fp  # noqa: PLC0415
        report = fp.scan(root, policy)
        if report["unclassified"]:
            problems.append("unclassified:" + str(len(report["unclassified"])))
        if report["unsafe"]:
            problems.append("unsafe_paths:" + str(len(report["unsafe"])))
        unmarked = [f["path"] for f in report["files"] if f["needs_mark"]]
        if unmarked:
            problems.append("attribution_missing:" + str(len(unmarked)))
        side_ok, side_problems = fp.sidecar_ok(root, policy)
        if not side_ok:
            problems.extend(side_problems[:20])
    except Exception as exc:  # noqa: BLE001
        problems.append("policy_scan_failed:" + type(exc).__name__ + ":" + str(exc)[:120])
    ok = not problems
    return {"ok": ok, "status": "ok" if ok else "failed", "problems": problems[:40],
            "policy_digest": policy_digest(policy)}


def check_authenticity(root: Path) -> dict:
    statement = root / STATEMENT_REL
    if not statement.is_file():
        return {"status": "missing", "ok": False,
                "detail": "no release statement; integrity is unauthenticated"}
    try:
        sys.path.insert(0, str(HERE))
        import release_signing as rs  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        return {"status": "unknown", "ok": False, "detail": "signing module unavailable: " + type(exc).__name__}
    try:
        return rs.verify_release(root)
    except Exception as exc:  # noqa: BLE001
        return {"status": "unknown", "ok": False, "detail": type(exc).__name__ + ":" + str(exc)[:160]}


def check_platform() -> dict:
    if os.name == "nt":
        return {"ok": True, "status": "ok", "platform": "windows"}
    return {"ok": True, "status": "ok", "platform": os.name}


def check_modules(root: Path, modules: list[str] | None) -> dict:
    """Verify the specific modules this invocation is about to load."""
    if not modules:
        return {"ok": True, "status": "skipped", "detail": "no protected modules requested"}
    problems = []
    for rel in modules:
        target = root / rel
        if not target.is_file():
            problems.append("missing:" + rel)
    return {"ok": not problems, "status": "ok" if not problems else "failed", "problems": problems}


# --------------------------------------------------------------------------- gate

def run(root: Path, modules: list[str] | None = None) -> dict:
    root = Path(root).resolve()
    result = {
        "schema": "npc-brand-gate/1",
        "root": str(root),
        "integrity": check_integrity(root),
        "attribution": check_attribution(root),
        "authenticity": check_authenticity(root),
        "platform": check_platform(),
        "modules": check_modules(root, modules),
    }
    errors = []
    if not result["platform"]["ok"]:
        errors.append(ERROR_UNSUPPORTED_PLATFORM)
    if result["integrity"]["status"] == "missing":
        errors.append(ERROR_MANIFEST_MISSING)
    elif not result["integrity"]["ok"]:
        errors.append(ERROR_CONTENT_CHANGED)
    if not result["attribution"]["ok"]:
        problems = " ".join(result["attribution"].get("problems", []))
        errors.append(ERROR_ATTRIBUTION_MISSING if "attribution_missing" in problems
                      else ERROR_CONTENT_CHANGED)
    if result["authenticity"]["status"] == "invalid":
        errors.append(ERROR_SIGNATURE_INVALID)
    elif result["authenticity"]["status"] == "mismatch":
        errors.append(ERROR_TRUST_ROOT_MISMATCH)
    if not result["modules"]["ok"]:
        errors.append(ERROR_DEPENDENCY_UNAVAILABLE)
    result["errors"] = errors
    result["allow_protected_load"] = not errors
    result["authenticity_note"] = (
        "integrity and attribution are enforced; publisher identity is %s"
        % result["authenticity"]["status"]
    )
    return result


DIAGNOSE_HINT = (
    "Diagnostics stay available:\n"
    "  python scripts/brand_gate.py --check --diagnose   # full layered report + this hint\n"
    "  python scripts/file_policy.py --check             # attribution policy scan\n"
    "No user data is deleted and no network call is made by this gate."
)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="NPC-team trusted bootstrap gate")
    ap.add_argument("--root", default=str(DEFAULT_ROOT))
    ap.add_argument("--module", action="append", dest="modules", default=None,
                    help="repo-relative module about to be loaded (repeatable)")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--diagnose", action="store_true")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--quiet", action="store_true")
    args = ap.parse_args(list(sys.argv[1:] if argv is None else argv))

    result = run(Path(args.root), args.modules)

    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2))
    elif not args.quiet:
        for layer in ("integrity", "attribution", "authenticity", "platform", "modules"):
            info = result[layer]
            print("%-14s %s" % (layer, info.get("status", "?")))
        if result["errors"]:
            print("errors: " + ", ".join(result["errors"]))

    if not result["allow_protected_load"] and not args.quiet:
        print("\n受保护模块未加载。这是检测结果，不是故障。", file=sys.stderr)
        print("  " + ", ".join(result["errors"]), file=sys.stderr)
        if args.diagnose:
            print("\n" + DIAGNOSE_HINT, file=sys.stderr)

    return 0 if result["allow_protected_load"] else 3


if __name__ == "__main__":
    raise SystemExit(main())
# NPC团队出品 · 维护者 QQ1027369180 · QQ群2163075152
