#!/usr/bin/env python3
"""Append-only Evidence Ledger — v6 严格 schema + 分段日志，兼容 v5 只读。

存储布局
    旧版 (v5, 只读, 追加前必须显式迁移)
        <ledger>                        单文件 JSONL (旧格式)
    新版 (v6)
        <ledger>.index.json             提交索引 entries/head/segments/phase/未配对执行
        <ledger>.seg-000001.jsonl       分段 JSONL, 段间仍是同一条 prev_record_hash 链
    说明: v6 下 <ledger> 本体不存在; 该文件一旦出现即按 v5 单文件账本读取。

提交协议 (崩溃恢复边界)
    1) 先以 O_APPEND 单次 write 追加一条完整记录并 fsync 段文件;
    2) 再原子替换索引 (tmp -> fsync -> os.replace -> fsync dir)。
    索引是唯一提交点。崩溃只会留下"未提交尾段":
      - 半条记录 (段尾无换行) -> uncommitted_tail(kind=partial)
      - 完整但未提交记录      -> uncommitted_tail(kind=records)
    verify 一律报错, recover_ledger 才可显式提交或截断; 恢复永不接受"变短"。

锚定语义
    链校验只能证明"读到的东西自洽", 不能证明"没有东西被删掉"。
    尾部删除/清空只能通过账本之外的外部锚点检出。
    未传 checkpoint 时结果一律带 anchor.status = unanchored,
    并且 tail_deletion_protected = False — 不得据此宣称防尾删。

复杂度
    v6 追加: state_event / execution_pre / execution_post / unknown_revision /
    counterexample 摊销 O(1) (追加 1 行 + 重写 KB 级索引)。
    带 evidence_refs 的记录 (claim_revision 等) 需解析引用, 为 O(n) 一次 —
    这类记录数量远小于执行/状态事件, 见 reports/w6-evidence.md 基准结论。
"""
from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import re
import sys
import threading
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

SCHEMA_V5 = "evidence-ledger/v5"
SCHEMA_V6 = "evidence-ledger/v6"
SCHEMA = SCHEMA_V6
LEGACY_SCHEMA = SCHEMA_V5
FORMAT_SINGLE = "single-file"
FORMAT_SEGMENTED = "segmented-log"
SEGMENT_FORMAT = "segmented-log/v1"
CHECKPOINT_SCHEMA = "evidence-ledger-checkpoint/v1"
GENESIS = "sha256:" + "0" * 64
INDEX_SUFFIX = ".index.json"
SEGMENT_INFIX = ".seg-"
SEGMENT_SUFFIX = ".jsonl"

_HASH_RE = re.compile(r"^sha256:[0-9a-f]{64}$")
_EVIDENCE_ID_RE = re.compile(r"^ev_[0-9a-f]{64}$")
_EXECUTION_ID_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$")
_ALLOWED = {"state_event", "claim_revision", "unknown_revision", "counterexample"}
EXECUTION_ENTRY_TYPES = {"execution_pre", "execution_post"}
ALLOWED_ENTRY_TYPES = _ALLOWED | EXECUTION_ENTRY_TYPES

AUTHORITIES = ("shipped_artifact", "controlled_replay", "live_observation", "derived", "inferred", "unknown")
CONFIDENCES = ("observed", "derived", "inferred")
CHANNELS = ("static", "local", "browser", "target")
EXECUTION_STATUS = ("started", "completed", "failed", "aborted", "timed_out")
POST_STATUS = ("completed", "failed", "aborted", "timed_out")
CLAIM_STATUS = ("supported", "refuted", "error", "unsupported", "skipped", "not_executed", "pending")
UNKNOWN_STATUS = ("open", "investigating", "blocked", "contradicted", "resolved")
COUNTEREXAMPLE_VERDICT = ("refutes", "inconclusive", "confirms")

FIRST_PHASE = "Observe"
PHASES = ("Intake", "Observe", "Capture", "Execute", "Verify", "Deliver", "QualityGate", "Release", "Closed", "Blocked")
TRANSITIONS = frozenset({
    ("Intake", "Observe"), ("Intake", "Blocked"),
    ("Observe", "Capture"), ("Observe", "Blocked"),
    ("Capture", "Execute"), ("Capture", "Verify"), ("Capture", "Blocked"),
    ("Execute", "Capture"), ("Execute", "Verify"), ("Execute", "Blocked"),
    ("Verify", "Deliver"), ("Verify", "Execute"), ("Verify", "Blocked"),
    ("Deliver", "QualityGate"), ("Deliver", "Blocked"),
    ("QualityGate", "Release"), ("QualityGate", "Deliver"), ("QualityGate", "Blocked"),
    ("Release", "Closed"),
    ("Blocked", "Intake"), ("Blocked", "Observe"), ("Blocked", "Capture"),
})

_TYPE_REQUIRED = {
    "state_event": ("from", "to"),
    "claim_revision": ("claim_id", "status", "evidence_refs"),
    "unknown_revision": ("unknown_id", "status", "revision"),
    "counterexample": ("counterexample_id", "target", "expected", "observed", "verdict"),
    "execution_pre": ("execution_id", "task_id", "owner", "target", "authorization_ref",
                      "channel", "command", "started_at", "status", "expected"),
    "execution_post": ("execution_id", "task_id", "owner", "target", "authorization_ref",
                       "channel", "command", "exit_code", "finished_at", "status",
                       "artifact_digests", "raw_output_digest", "output_excerpt", "state_diff"),
}

FIVE_TUPLE = ("authority", "confidence", "context", "digest", "limitation")
_COMMON_V6 = ("schema", "seq", "entry_type", "occurred_at", "prev_record_hash", "record_hash",
              "evidence_id") + FIVE_TUPLE

_LOCK_TIMEOUT = 30.0
LOCK_TIMEOUT_ENV = "EVIDENCE_LEDGER_LOCK_TIMEOUT"
_SEGMENT_MAX_ENTRIES = 5000
_RECENT_EXECUTIONS_KEPT = 64
_APPEND_LOCK = threading.RLock()
_PLACEHOLDERS = frozenset({"none", "null", "nil", "unknown", "tbd", "todo", "n/a", "na", "-", "无", "未提供"})

STATUS_PASS = "pass"
STATUS_FAIL = "fail"
STATUS_ERROR = "error"
STATUS_EMPTY = "empty"
STATUS_NOT_EXECUTED = "not_executed"


# --------------------------------------------------------------------- 基础工具

def canonical(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha(data: bytes) -> str:
    return "sha256:" + hashlib.sha256(data).hexdigest()


def _now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def evidence_id(identity: dict) -> str:
    """内容身份: 覆盖除 record_hash / evidence_id 自身以外的全部字段。"""
    payload = {k: v for k, v in identity.items() if k not in ("record_hash", "evidence_id")}
    return "ev_" + hashlib.sha256(b"evidence-ledger/v6\0" + canonical(payload)).hexdigest()


def _record_hash(prev: str, entry: dict, schema: str | None = None) -> str:
    schema = schema or entry.get("schema") or SCHEMA_V6
    domain = b"record/v6\0" if schema == SCHEMA_V6 else b"record/v5\0"
    payload = {k: v for k, v in entry.items() if k != "record_hash"}
    return sha(domain + prev.encode("ascii") + canonical(payload))


def record_hash(prev: str, entry: dict) -> str:
    """向后兼容入口: v5 记录继续用 record/v5 域, v6 用 record/v6 域。"""
    return _record_hash(prev, entry)


def _fsync_directory(path: Path):
    if os.name == "nt":
        return
    try:
        fd = os.open(str(path), os.O_RDONLY)
    except OSError:
        return
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _absolute_no_symlink(path: Path) -> Path:
    path = Path(os.path.abspath(str(path)))
    current = path
    if current.is_symlink() or (hasattr(current, "is_junction") and current.is_junction()):
        raise ValueError("symlink_ledger_rejected")
    while current != current.parent:
        if current.exists() and (current.is_symlink() or (hasattr(current, "is_junction") and current.is_junction())):
            raise ValueError("symlink_ledger_parent_rejected:" + str(current))
        current = current.parent
    return path


def _open_nofollow(path: Path, flags: int, mode: int = 0o600) -> int:
    """句柄级防换链: O_NOFOLLOW(可用时) + 打开后比对 dev/ino。"""
    flags |= getattr(os, "O_NOFOLLOW", 0)
    if hasattr(os, "O_BINARY"):
        flags |= os.O_BINARY
    fd = os.open(str(path), flags, mode)
    try:
        st_fd = os.fstat(fd)
        st_path = os.stat(str(path), follow_symlinks=False)
    except OSError:
        os.close(fd)
        raise ValueError("file_identity_unavailable:" + path.name)
    if (st_fd.st_dev, st_fd.st_ino) != (st_path.st_dev, st_path.st_ino):
        os.close(fd)
        raise ValueError("file_identity_swapped:" + path.name)
    return fd


def _atomic_write_bytes(path: Path, data: bytes):
    fd, tmp_name = _mkstemp(path)
    tmp = Path(tmp_name)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp, path)
        _fsync_directory(path.parent)
    finally:
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass


def _mkstemp(path: Path):
    import tempfile
    return tempfile.mkstemp(prefix="." + path.name + ".", suffix=".tmp", dir=str(path.parent))


# --------------------------------------------------------------------------- 锁

class LedgerLockCancelled(RuntimeError):
    """取消等待账本锁。"""


class _FileLock:
    """跨进程排它锁: Windows msvcrt / POSIX flock 统一为非阻塞轮询 + 超时 + 取消。"""

    def __init__(self, path: Path, timeout: float | None = None, cancel=None):
        self.path = path
        self.timeout = _resolve_timeout(timeout)
        self.cancel = cancel
        self.handle = None

    def _check_cancel(self):
        if self.cancel is None:
            return
        if callable(self.cancel):
            stopped = bool(self.cancel())
        else:
            stopped = bool(self.cancel.is_set())
        if stopped:
            raise LedgerLockCancelled("ledger_lock_cancelled")

    def __enter__(self):
        self.path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        if self.path.is_symlink():
            raise ValueError("symlink_lock_rejected")
        fd = _open_nofollow(self.path, os.O_RDWR | os.O_CREAT)
        self.handle = os.fdopen(fd, "r+b", buffering=0)
        if os.name == "nt":
            # 空文件同样可以锁定字节范围(实测 LK_NBLCK 可锁 EOF 之后的字节),
            # 因此绝不写锁文件: 任何写入都会与别人正持有的字节范围锁冲突(PermissionError 13)。
            self.handle.seek(0)
        deadline = time.monotonic() + self.timeout
        while True:
            self._check_cancel()
            try:
                self._try_lock()
                return self
            except OSError as exc:
                if not self._retryable(exc):
                    self._close()
                    raise
                if time.monotonic() >= deadline:
                    self._close()
                    raise TimeoutError("ledger_lock_timeout") from exc
                time.sleep(0.01)

    def _try_lock(self):
        if os.name == "nt":
            import msvcrt
            msvcrt.locking(self.handle.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(self.handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)

    def _retryable(self, exc: OSError) -> bool:
        if os.name == "nt":
            winerror = getattr(exc, "winerror", None)
            return winerror in (None, 33, 36) or getattr(exc, "errno", None) in (None, 11, 13)
        return getattr(exc, "errno", None) in (11, 13, 35)

    def _close(self):
        if self.handle is not None and not self.handle.closed:
            try:
                self.handle.close()
            except OSError:
                pass
        self.handle = None

    def __exit__(self, *exc):
        if self.handle is None or self.handle.closed:
            return False
        try:
            if os.name == "nt":
                import msvcrt
                self.handle.seek(0)
                msvcrt.locking(self.handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(self.handle.fileno(), fcntl.LOCK_UN)
        except OSError:
            pass
        finally:
            self._close()
        return False


def _resolve_timeout(timeout: float | None) -> float:
    if timeout is not None:
        value = float(timeout)
    else:
        raw = os.environ.get(LOCK_TIMEOUT_ENV, "")
        try:
            value = float(raw) if raw.strip() else _LOCK_TIMEOUT
        except ValueError:
            value = _LOCK_TIMEOUT
    if not math.isfinite(value) or value < 0:
        raise ValueError("invalid_lock_timeout")
    return value


def _lock_file(path: Path) -> Path:
    return path.with_name(path.name + ".lock")


# ------------------------------------------------------------------- 行解析/校验

def _reject_pairs(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError("duplicate_json_key:" + key)
        obj[key] = value
    return obj


def _finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError("nonfinite_float")
    return result


def _reject_constant(value):
    raise ValueError("invalid_constant:" + value)


def _parse_json_line(line: bytes):
    return json.loads(line.decode("utf-8"), object_pairs_hook=_reject_pairs,
                      parse_float=_finite_float, parse_constant=_reject_constant)


def _err(code: str, **extra) -> dict:
    item = {"code": code}
    item.update(extra)
    return item


def _parse_timestamp(value, field, line_no):
    if not isinstance(value, str) or not value:
        raise ValueError("invalid_timestamp:%s:%d" % (field, line_no))
    text = value[:-1] + "+00:00" if value.endswith("Z") else value
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as exc:
        raise ValueError("invalid_timestamp:%s:%d" % (field, line_no)) from exc
    if parsed.tzinfo is None:
        raise ValueError("naive_timestamp:%s:%d" % (field, line_no))
    return parsed


def _require_str(entry, key, line_no, placeholder_check=False):
    value = entry.get(key)
    if not isinstance(value, str) or not value:
        raise ValueError("missing_field:%s:%d" % (key, line_no))
    if placeholder_check and value.strip().lower() in _PLACEHOLDERS:
        raise ValueError("placeholder_field:%s:%d" % (key, line_no))
    return value


def _require_enum(entry, key, allowed, line_no):
    value = entry.get(key)
    if value not in allowed:
        raise ValueError("unknown_enumeration:%s:%d" % (key, line_no))
    return value


def _require_hash_field(entry, key, line_no, allow_none=False):
    value = entry.get(key)
    if value is None and allow_none:
        return None
    if not isinstance(value, str) or not _HASH_RE.fullmatch(value):
        raise ValueError("invalid_digest:%s:%d" % (key, line_no))
    return value


def _validate_artifact_digests(entry, key, line_no, required=True):
    if key not in entry:
        if required:
            raise ValueError("missing_field:%s:%d" % (key, line_no))
        return []
    value = entry[key]
    if not isinstance(value, list):
        raise ValueError("invalid_artifacts:%s:%d" % (key, line_no))
    for item in value:
        if not isinstance(item, dict):
            raise ValueError("invalid_artifacts:%s:%d" % (key, line_no))
        if not isinstance(item.get("path"), str) or not item["path"]:
            raise ValueError("invalid_artifacts:path:%d" % line_no)
        if not isinstance(item.get("sha256"), str) or not _HASH_RE.fullmatch(item["sha256"]):
            raise ValueError("invalid_digest:artifact_digests:%d" % line_no)
    return value


def _validate_entry_v5(entry, line_no=0):
    """旧版(v5)结构校验 — 只约束链结构, 保留历史账本可读性。"""
    if not isinstance(entry, dict):
        raise ValueError("entry_not_object:%d" % line_no)
    if entry.get("schema") != SCHEMA_V5:
        raise ValueError("invalid_ledger_schema:%d" % line_no)
    if type(entry.get("seq")) is not int or entry["seq"] < 1:
        raise ValueError("invalid_seq:%d" % line_no)
    entry_type = entry.get("entry_type")
    if entry_type not in ALLOWED_ENTRY_TYPES:
        raise ValueError("unknown_entry_type:%d" % line_no)
    if entry_type == "claim_revision" and (not isinstance(entry.get("claim_id"), str) or not entry["claim_id"]):
        raise ValueError("missing_claim_id:%d" % line_no)
    if entry_type == "unknown_revision" and (not isinstance(entry.get("unknown_id"), str) or not entry["unknown_id"]):
        raise ValueError("missing_unknown_id:%d" % line_no)
    for key in ("prev_record_hash", "record_hash"):
        if not isinstance(entry.get(key), str) or not _HASH_RE.fullmatch(entry[key]):
            raise ValueError("invalid_hash:%s:%d" % (key, line_no))


def _validate_entry_v6(entry, line_no=0):
    """v6 结构校验: 公共字段 + 证据五元组 + 分类型必需字段。任何缺失/越界都抛错。"""
    if not isinstance(entry, dict):
        raise ValueError("entry_not_object:%d" % line_no)
    if entry.get("schema") != SCHEMA_V6:
        raise ValueError("invalid_ledger_schema:%d" % line_no)
    for key in _COMMON_V6:
        if key not in entry:
            raise ValueError("missing_field:%s:%d" % (key, line_no))
    if type(entry.get("seq")) is not int or entry["seq"] < 1:
        raise ValueError("invalid_seq:%d" % line_no)
    entry_type = entry.get("entry_type")
    if entry_type not in ALLOWED_ENTRY_TYPES:
        raise ValueError("unknown_enumeration:entry_type:%d" % line_no)
    _parse_timestamp(entry.get("occurred_at"), "occurred_at", line_no)
    for key in ("prev_record_hash", "record_hash"):
        _require_hash_field(entry, key, line_no)
    if not isinstance(entry.get("evidence_id"), str) or not _EVIDENCE_ID_RE.fullmatch(entry["evidence_id"]):
        raise ValueError("invalid_evidence_id:%d" % line_no)
    # 证据五元组
    _require_enum(entry, "authority", AUTHORITIES, line_no)
    _require_enum(entry, "confidence", CONFIDENCES, line_no)
    context = entry.get("context")
    if not isinstance(context, dict) or not context:
        raise ValueError("invalid_context:%d" % line_no)
    _require_hash_field(entry, "digest", line_no)
    limitation = entry.get("limitation")
    if not isinstance(limitation, list) or not limitation:
        raise ValueError("invalid_limitation:%d" % line_no)
    for item in limitation:
        if not isinstance(item, str) or not item.strip():
            raise ValueError("invalid_limitation:%d" % line_no)
    for key in _TYPE_REQUIRED[entry_type]:
        if key not in entry:
            raise ValueError("missing_field:%s:%d" % (key, line_no))
    validator = _TYPE_VALIDATORS[entry_type]
    validator(entry, line_no)


def _validate_state_event(entry, line_no):
    source = _require_enum(entry, "from", PHASES, line_no)
    target = _require_enum(entry, "to", PHASES, line_no)
    if (source, target) not in TRANSITIONS:
        raise ValueError("illegal_state_transition:%s->%s:%d" % (source, target, line_no))
    _validate_refs(entry, line_no)


def _validate_claim(entry, line_no):
    _require_str(entry, "claim_id", line_no)
    status = _require_enum(entry, "status", CLAIM_STATUS, line_no)
    refs = _validate_refs(entry, line_no)
    if status != "not_executed" and not refs:
        raise ValueError("missing_evidence_ref:%d" % line_no)


def _validate_unknown(entry, line_no):
    _require_str(entry, "unknown_id", line_no)
    _require_enum(entry, "status", UNKNOWN_STATUS, line_no)
    if type(entry.get("revision")) is not int or entry["revision"] < 1:
        raise ValueError("invalid_revision:%d" % line_no)
    _validate_refs(entry, line_no)


def _validate_counterexample(entry, line_no):
    _require_str(entry, "counterexample_id", line_no)
    _require_str(entry, "target", line_no)
    _require_str(entry, "expected", line_no)
    _require_str(entry, "observed", line_no)
    _require_enum(entry, "verdict", COUNTEREXAMPLE_VERDICT, line_no)
    _validate_refs(entry, line_no)


def _validate_refs(entry, line_no):
    value = entry.get("evidence_refs")
    if value is None:
        return []
    if not isinstance(value, list):
        raise ValueError("invalid_evidence_refs:%d" % line_no)
    for item in value:
        if not isinstance(item, str) or not _EVIDENCE_ID_RE.fullmatch(item):
            raise ValueError("invalid_evidence_refs:%d" % line_no)
    return value


def _validate_execution_pre(entry, line_no):
    _validate_execution_identity(entry, line_no)
    _require_str(entry, "command", line_no)
    _parse_timestamp(entry.get("started_at"), "started_at", line_no)
    if entry.get("status") != "started":
        raise ValueError("unknown_enumeration:status:%d" % line_no)
    _require_str(entry, "expected", line_no)
    if "exit_code" in entry:
        raise ValueError("exit_code_on_pre:%d" % line_no)
    _validate_artifact_digests(entry, "artifact_digests", line_no, required=False)
    _validate_refs(entry, line_no)


def _validate_execution_post(entry, line_no):
    _validate_execution_identity(entry, line_no)
    _require_str(entry, "command", line_no)
    status = _require_enum(entry, "status", POST_STATUS, line_no)
    finished = _parse_timestamp(entry.get("finished_at"), "finished_at", line_no)
    if "started_at" in entry:
        started = _parse_timestamp(entry.get("started_at"), "started_at", line_no)
        if finished < started:
            raise ValueError("invalid_time_order:%d" % line_no)
    exit_code = entry.get("exit_code")
    if status in ("completed", "failed"):
        if type(exit_code) is not int:
            raise ValueError("invalid_exit_code:%d" % line_no)
        if status == "completed" and exit_code != 0:
            raise ValueError("exit_code_status_conflict:%d" % line_no)
        if status == "failed" and exit_code == 0:
            raise ValueError("exit_code_status_conflict:%d" % line_no)
    elif exit_code is not None and type(exit_code) is not int:
        raise ValueError("invalid_exit_code:%d" % line_no)
    _validate_artifact_digests(entry, "artifact_digests", line_no, required=True)
    raw_digest = _require_hash_field(entry, "raw_output_digest", line_no, allow_none=True)
    excerpt = entry.get("output_excerpt")
    if not isinstance(excerpt, str):
        raise ValueError("missing_field:output_excerpt:%d" % line_no)
    if raw_digest is None and excerpt != "":
        raise ValueError("raw_output_digest_missing:%d" % line_no)
    if not isinstance(entry.get("state_diff"), dict):
        raise ValueError("missing_field:state_diff:%d" % line_no)
    _validate_refs(entry, line_no)


def _validate_execution_identity(entry, line_no):
    execution_id = _require_str(entry, "execution_id", line_no)
    if not _EXECUTION_ID_RE.fullmatch(execution_id):
        raise ValueError("invalid_execution_id:%d" % line_no)
    _require_str(entry, "task_id", line_no)
    _require_str(entry, "owner", line_no)
    _require_str(entry, "target", line_no)
    _require_str(entry, "authorization_ref", line_no, placeholder_check=True)
    _require_enum(entry, "channel", CHANNELS, line_no)


_TYPE_VALIDATORS = {
    "state_event": _validate_state_event,
    "claim_revision": _validate_claim,
    "unknown_revision": _validate_unknown,
    "counterexample": _validate_counterexample,
    "execution_pre": _validate_execution_pre,
    "execution_post": _validate_execution_post,
}


# ------------------------------------------------------------------ 读取/解析

def _index_path(path: Path) -> Path:
    return path.with_name(path.name + INDEX_SUFFIX)


def _segment_paths(path: Path) -> list[Path]:
    pattern = path.name + SEGMENT_INFIX + "*" + SEGMENT_SUFFIX
    found = []
    for candidate in path.parent.glob(pattern):
        stem = candidate.name[len(path.name + SEGMENT_INFIX):-len(SEGMENT_SUFFIX)]
        if stem.isdigit():
            found.append((int(stem), candidate))
    return [item[1] for item in sorted(found)]


def _segment_name(path: Path, number: int) -> str:
    return path.name + SEGMENT_INFIX + ("%06d" % number) + SEGMENT_SUFFIX


def _parse_segment(raw: bytes, base_line_no: int, strict: bool):
    """返回 (entries, errors, partial_tail_bytes)。partial = 未以换行结尾的尾部字节。"""
    entries, errors = [], []
    partial = b""
    if raw and not raw.endswith(b"\n"):
        cut = raw.rfind(b"\n")
        partial = raw[cut + 1:]
        raw = raw[:cut + 1]
    if not raw:
        return entries, errors, partial
    for offset, line in enumerate(raw[:-1].split(b"\n")):
        line_no = base_line_no + offset
        if not line:
            errors.append(_err("invalid_blank_line", seq=None, line=line_no))
            entries.append(None)
            continue
        if b"\r" in line:
            errors.append(_err("invalid_line_ending", seq=None, line=line_no))
            entries.append(None)
            continue
        try:
            entry = _parse_json_line(line)
        except Exception as exc:
            errors.append(_err("invalid_entry", seq=None, line=line_no,
                               detail=type(exc).__name__ + ":" + str(exc)[:120]))
            entries.append(None)
            continue
        try:
            (_validate_entry_v6 if strict else _validate_entry_v5)(entry, line_no)
        except ValueError as exc:
            head = str(exc).split(":", 1)
            errors.append(_err(head[0], seq=entry.get("seq") if isinstance(entry, dict) else None,
                               line=line_no, detail=str(exc)))
        entries.append(entry)
    return entries, errors, partial


def _read_single_file(path: Path, strict: bool):
    raw = path.read_bytes()
    entries, errors, partial = _parse_segment(raw, 1, strict)
    return {"entries": entries, "errors": errors, "partial": partial, "segments": [], "bytes": len(raw)}


def _detect_format(path: Path) -> str | None:
    if path.exists():
        if path.is_dir():
            raise ValueError("ledger_path_is_directory")
        return FORMAT_SINGLE
    if _index_path(path).exists() or _segment_paths(path):
        return FORMAT_SEGMENTED
    return None


def _load_index(index_path: Path) -> dict | None:
    if not index_path.exists():
        return None
    try:
        data = json.loads(index_path.read_bytes().decode("utf-8"), object_pairs_hook=_reject_pairs,
                          parse_float=_finite_float, parse_constant=_reject_constant)
    except Exception as exc:
        raise ValueError("index_invalid:" + type(exc).__name__) from exc
    if not isinstance(data, dict) or data.get("schema") != SCHEMA_V6 or data.get("format") != SEGMENT_FORMAT:
        raise ValueError("index_invalid_schema")
    if type(data.get("entries")) is not int or data["entries"] < 0:
        raise ValueError("index_invalid_entries")
    if not isinstance(data.get("head"), str) or not _HASH_RE.fullmatch(data["head"]):
        raise ValueError("index_invalid_head")
    for key in ("open_executions", "unknowns", "claims"):
        if not isinstance(data.get(key), dict):
            raise ValueError("index_invalid:" + key)
    if not isinstance(data.get("recent_executions"), list):
        raise ValueError("index_invalid_lists")
    if type(data.get("segment_count")) is not int or data["segment_count"] < 0:
        raise ValueError("index_invalid_segment_count")
    if type(data.get("active_entries")) is not int or data["active_entries"] < 0:
        raise ValueError("index_invalid_active_entries")
    if data.get("active_segment") is not None and not isinstance(data.get("active_segment"), str):
        raise ValueError("index_invalid_active_segment")
    if data.get("active_bytes") is not None and (type(data.get("active_bytes")) is not int or data["active_bytes"] < 0):
        raise ValueError("index_invalid_active_bytes")
    if data.get("phase") not in PHASES:
        raise ValueError("index_invalid_phase")
    return data


def _empty_index(path: Path) -> dict:
    return {
        "schema": SCHEMA_V6,
        "format": SEGMENT_FORMAT,
        "ledger": path.name,
        "entries": 0,
        "head": GENESIS,
        "segment_count": 0,
        "active_segment": None,
        "active_entries": 0,
        "active_bytes": 0,
        "phase": FIRST_PHASE,
        "open_executions": {},
        "recent_executions": [],
        "unknowns": {},
        "claims": {},
        "updated_at": _now(),
    }


def _save_index(index_path: Path, index: dict):
    index = dict(index)
    index["updated_at"] = _now()
    payload = (json.dumps(index, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
    _atomic_write_bytes(index_path, payload)


def _read_segmented(path: Path, index: dict):
    segments = _segment_paths(path)
    entries, errors, partial, total_bytes = [], [], b"", 0
    line_no = 1
    for number, segment in enumerate(segments, 1):
        raw = segment.read_bytes()
        total_bytes += len(raw)
        seg_entries, seg_errors, seg_partial = _parse_segment(raw, line_no, True)
        for item in seg_entries:
            entries.append(item)
        errors.extend(seg_errors)
        line_no += len(seg_entries)
        if number == len(segments):
            partial = seg_partial
    return {"entries": entries, "errors": errors, "partial": partial, "segments": segments,
            "bytes": total_bytes, "index": index}


def _read_ledger(path: Path):
    """读取快照; 账本内容问题放进 errors, 不抛异常 (IO/结构问题才抛)。"""
    fmt = _detect_format(path)
    if fmt is None:
        return {"format": None, "schema": None, "entries": [], "errors": [], "partial": b"",
                "segments": [], "index": None, "exists": False, "commit_errors": []}
    if fmt == FORMAT_SINGLE:
        snapshot = _read_single_file(path, strict=False)
        commit_errors = []
        if snapshot["partial"]:
            commit_errors.append(_err("uncommitted_tail", kind="partial",
                                      observed=len(snapshot["partial"]),
                                      hint="旧版单文件账本尾部无换行: 半条记录, 用 recover_ledger 截断"))
        snapshot.update(format=FORMAT_SINGLE, schema=SCHEMA_V5, index=None, exists=True,
                        commit_errors=commit_errors)
        return snapshot
    index = _load_index(_index_path(path))
    commit_errors = []
    if index is None:
        commit_errors.append(_err("segment_index_missing"))
        index = _empty_index(path)
    snapshot = _read_segmented(path, index)
    snapshot.update(format=FORMAT_SEGMENTED, schema=SCHEMA_V6, exists=True, commit_errors=commit_errors)
    committed = index["entries"] if not commit_errors else None
    actual = len([item for item in snapshot["entries"] if isinstance(item, dict)])
    if committed is not None:
        if actual > committed:
            snapshot["commit_errors"].append(_err(
                "uncommitted_tail", kind="partial" if snapshot["partial"] else "records",
                committed=committed, observed=actual))
        elif actual < committed:
            snapshot["commit_errors"].append(_err("entries_below_index", committed=committed, observed=actual))
        elif snapshot["partial"]:
            # 条数一致但尾部仍有未以换行结束的字节: 半条记录, 一律未提交
            snapshot["commit_errors"].append(_err(
                "uncommitted_tail", kind="partial", committed=committed, observed=actual,
                detail="尾部存在未以换行结束的字节"))
    return snapshot


# ----------------------------------------------------------- 链 / 语义校验

def _chain_errors(entries):
    previous = GENESIS
    errors = []
    chainable = True
    for expected, entry in enumerate(entries, 1):
        if not isinstance(entry, dict):
            chainable = False
            errors.append(_err("chain_unverifiable", seq=None, expected_seq=expected))
            continue
        if entry.get("seq") != expected:
            errors.append(_err("sequence_gap", seq=entry.get("seq"), expected_seq=expected))
        if entry.get("prev_record_hash") != previous:
            errors.append(_err("chain_break", seq=entry.get("seq")))
        if not _HASH_RE.fullmatch(str(entry.get("record_hash"))):
            chainable = False
            errors.append(_err("chain_unverifiable", seq=entry.get("seq")))
            continue
        actual = _record_hash(previous, entry, entry.get("schema"))
        if entry.get("record_hash") != actual:
            errors.append(_err("record_hash_mismatch", seq=entry.get("seq")))
        previous = entry["record_hash"]
    return previous, errors, chainable


def _semantic_errors(entries):
    """v6 跨记录语义: evidence_id、状态转换、pre/post 配对、引用、修订单调。"""
    errors = []
    seen_ids = {}
    phase = FIRST_PHASE
    executions = {}
    seen_execution_ids = set()
    closed_execution_ids = set()
    unknown_revision = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        seq = entry.get("seq")
        entry_type = entry.get("entry_type")
        eid = entry.get("evidence_id")
        if isinstance(eid, str):
            if eid in seen_ids:
                errors.append(_err("duplicate_evidence_id", seq=seq))
            seen_ids[eid] = seq
            if _EVIDENCE_ID_RE.fullmatch(eid) and eid != evidence_id(entry):
                errors.append(_err("evidence_id_mismatch", seq=seq))
        for ref in entry.get("evidence_refs") or []:
            if not isinstance(ref, str) or ref not in seen_ids:
                errors.append(_err("unknown_evidence_ref", seq=seq, ref=ref))
        if entry_type == "state_event":
            source, target = entry.get("from"), entry.get("to")
            if source in PHASES and source != phase:
                errors.append(_err("state_from_mismatch", seq=seq, phase=phase, declared=source))
            if (source, target) not in TRANSITIONS:
                errors.append(_err("illegal_state_transition", seq=seq, **{"from": source, "to": target}))
            else:
                phase = target
        elif entry_type == "execution_pre":
            execution = entry.get("execution_id")
            if execution in seen_execution_ids:
                errors.append(_err("duplicate_execution_id", seq=seq, execution_id=execution))
            elif execution in closed_execution_ids:
                errors.append(_err("reused_execution_id", seq=seq, execution_id=execution))
            seen_execution_ids.add(execution)
            executions[execution] = {"seq": seq, "entry": entry, "post": None}
        elif entry_type == "execution_post":
            execution = entry.get("execution_id")
            record = executions.get(execution)
            if record is None or record.get("post") is not None:
                errors.append(_err("orphan_execution_post", seq=seq, execution_id=execution))
            else:
                record["post"] = entry
                mismatch = _execution_mismatch(record["entry"], entry)
                for field in mismatch:
                    errors.append(_err(field, seq=seq, execution_id=execution))
                closed_execution_ids.add(execution)
        elif entry_type == "unknown_revision":
            key = entry.get("unknown_id")
            expected = unknown_revision.get(key, 0) + 1
            if entry.get("revision") != expected:
                errors.append(_err("unknown_revision_out_of_order", seq=seq,
                                   expected_revision=expected, observed=entry.get("revision")))
            else:
                unknown_revision[key] = expected
    for execution, record in executions.items():
        if record.get("post") is None:
            errors.append(_err("unpaired_execution", seq=record["seq"], execution_id=execution,
                               hint="异常中止也必须写 execution_post(status=aborted), 不能只留 pre"))
    return errors


def _execution_mismatch(pre: dict, post: dict) -> list:
    mismatched = []
    for field in ("task_id", "owner", "target", "authorization_ref", "channel"):
        if pre.get(field) != post.get(field):
            mismatched.append("execution_field_mismatch")
            break
    if pre.get("command") != post.get("command"):
        mismatched.append("execution_command_mismatch")
    post_seq, pre_seq = post.get("seq"), pre.get("seq")
    if type(post_seq) is int and type(pre_seq) is int and post_seq < pre_seq:
        mismatched.append("execution_order_invalid")
    return mismatched


# -------------------------------------------------------------- checkpoint 校验

def _load_checkpoint_value(value):
    if value is None:
        return None, None
    if isinstance(value, dict):
        data = value
    else:
        candidate = Path(str(value))
        if not candidate.is_file():
            raise ValueError("checkpoint_missing:" + str(candidate))
        try:
            data = json.loads(candidate.read_bytes().decode("utf-8"), object_pairs_hook=_reject_pairs,
                              parse_float=_finite_float, parse_constant=_reject_constant)
        except Exception as exc:
            raise ValueError("checkpoint_invalid:" + type(exc).__name__) from exc
    if not isinstance(data, dict) or data.get("schema") != CHECKPOINT_SCHEMA:
        raise ValueError("checkpoint_invalid_schema")
    if type(data.get("entries")) is not int or data["entries"] < 0:
        raise ValueError("checkpoint_invalid_entries")
    if not isinstance(data.get("head"), str) or not _HASH_RE.fullmatch(data["head"]):
        raise ValueError("checkpoint_invalid_head")
    recorded = data.get("checkpoint_digest")
    if recorded is not None:
        expected = sha(canonical({k: v for k, v in data.items() if k != "checkpoint_digest"}))
        if recorded != expected:
            raise ValueError("checkpoint_digest_mismatch")
    return data, data


def _checkpoint_errors(entries, head, checkpoint, mode="strict"):
    """返回 (errors, anchor_status)。strict: 条目数/head 必须完全一致; extends: 允许可信前缀增长。"""
    if checkpoint is None:
        return [], "unanchored"
    count = len(entries)
    expected = checkpoint["entries"]
    if count < expected:
        return [_err("entries_below_checkpoint", checkpoint=expected, observed=count,
                     hint="账本比 checkpoint 短: 尾部删除或清空")], "mismatch"
    if count == expected:
        if head != checkpoint["head"]:
            return [_err("head_mismatch", checkpoint=checkpoint["head"], observed=head)], "mismatch"
        return [], "exact_match"
    if mode != "extends":
        return [_err("entries_above_checkpoint", checkpoint=expected, observed=count,
                     hint="账本已增长; 严格模式下请重建 checkpoint, 或显式使用 mode=extends")], "mismatch"
    prefix_head, _, _ = _chain_errors(entries[:expected])
    if prefix_head != checkpoint["head"]:
        return [_err("prefix_head_mismatch", checkpoint=checkpoint["head"], observed=prefix_head)], "mismatch"
    return [], "matches_prefix_and_extended"


def _artifact_errors(entries, artifacts_root=None, strict_missing=True):
    errors = []
    checked = 0
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        for item in entry.get("artifact_digests") or []:
            if not isinstance(item, dict):
                continue
            checked += 1
            target = Path(item.get("path", ""))
            if not target.is_absolute() and artifacts_root is not None:
                target = Path(artifacts_root) / target
            if not target.is_file():
                if strict_missing:
                    errors.append(_err("artifact_missing", seq=entry.get("seq"), path=str(target)))
                continue
            actual = sha(target.read_bytes())
            if actual != item.get("sha256"):
                errors.append(_err("artifact_digest_mismatch", seq=entry.get("seq"),
                                   path=str(target), expected=item.get("sha256"), observed=actual))
    return errors, checked


# --------------------------------------------------------------- 主校验入口

def _read_and_verify(path: Path, checkpoint=None, checkpoint_mode="strict",
                     artifacts_root=None, verify_artifacts=False):
    try:
        snapshot = _read_ledger(path)
    except Exception as exc:
        result = _result_base(path, SCHEMA, [], GENESIS, STATUS_ERROR)
        result["errors"] = [_err("ledger_io_error", detail=str(exc))]
        result["format"] = None
        return [], result
    entries = [item for item in snapshot["entries"] if isinstance(item, dict)]
    errors = list(snapshot["errors"]) + list(snapshot.get("commit_errors") or [])
    head, chain_errors, _ = _chain_errors(snapshot["entries"])
    errors.extend(chain_errors)
    if snapshot["schema"] == SCHEMA_V6:
        errors.extend(_semantic_errors(entries))
    checkpoint_data = None
    checkpoint_error = None
    try:
        checkpoint_data, _ = _load_checkpoint_value(checkpoint)
    except ValueError as exc:
        checkpoint_error = str(exc)
    anchor_status = "unanchored"
    if checkpoint_error:
        errors.append(_err("checkpoint_invalid", detail=checkpoint_error))
        anchor_status = "invalid"
    elif checkpoint_data is not None:
        cp_errors, anchor_status = _checkpoint_errors(entries, head, checkpoint_data, checkpoint_mode)
        errors.extend(cp_errors)
    artifact_count = 0
    if verify_artifacts:
        art_errors, artifact_count = _artifact_errors(entries, artifacts_root)
        errors.extend(art_errors)
    result = _result_base(path, snapshot["schema"], entries, head, None)
    result["format"] = snapshot["format"]
    result["errors"] = _dedupe_errors(errors)
    result["executed"] = bool(snapshot["exists"])
    result["coverage"] = {"denominator": len(snapshot["entries"]), "numerator": len(entries)}
    result["artifacts_checked"] = artifact_count
    result["anchor"] = _anchor_block(checkpoint_data, anchor_status, checkpoint_mode)
    result["tail_deletion_protected"] = anchor_status in ("exact_match", "matches_prefix_and_extended")
    result["limitations"] = _limitations(snapshot, entries, errors, anchor_status)
    result["status"] = _status(snapshot, entries, errors)
    result["ok"] = result["status"] == STATUS_PASS
    return entries, result


def _dedupe_errors(errors: list) -> list:
    """同一记录同一码只报一次 (结构校验与语义校验可能同时命中)。"""
    seen, unique = set(), []
    for item in errors:
        key = (item.get("code"), item.get("seq"), item.get("line"))
        if key in seen:
            continue
        seen.add(key)
        unique.append(item)
    return unique


def _result_base(path: Path, schema, entries, head, status):
    return {
        "schema": SCHEMA_V6,
        "ledger_schema": schema,
        "path": str(path),
        "entries": len(entries),
        "head": head,
        "ok": False,
        "status": status,
        "errors": [],
        "executed": False,
        "coverage": {"denominator": 0, "numerator": 0},
        "artifacts": [str(path)],
        "limitations": [],
        "anchor": {"status": "unanchored", "checkpoint": None, "mode": None},
        "tail_deletion_protected": False,
    }


def _anchor_block(checkpoint, anchor_status, mode):
    return {
        "status": anchor_status,
        "mode": mode if checkpoint is not None else None,
        "checkpoint": None if checkpoint is None else {
            "entries": checkpoint.get("entries"),
            "head": checkpoint.get("head"),
            "checkpoint_at": checkpoint.get("checkpoint_at"),
            "external_anchor": checkpoint.get("external_anchor"),
            "path": checkpoint.get("ledger_path"),
        },
        "detail": _ANCHOR_DETAIL[anchor_status],
    }


_ANCHOR_DETAIL = {
    "unanchored": "未提供 checkpoint: 链校验只能证明读到内容自洽, 不能检出尾部删除/清空",
    "invalid": "checkpoint 不可用 (缺失/损坏/schema 不符): 按未锚定处理并报错",
    "exact_match": "账本条目数与 head 与 checkpoint 完全一致",
    "matches_prefix_and_extended": "checkpoint 是可验证前缀, 其后为 checkpoint 之后的新增记录",
    "mismatch": "账本与 checkpoint 不一致: 尾部删除/清空/改写",
}


def _status(snapshot, entries, errors):
    if errors:
        # 有错误时一律 fail: 包括"账本已不存在但 checkpoint 说明它曾存在"这类锚定冲突
        return STATUS_FAIL
    if snapshot["format"] is None:
        return STATUS_NOT_EXECUTED
    if not entries:
        return STATUS_EMPTY
    return STATUS_PASS


def _limitations(snapshot, entries, errors, anchor_status):
    limits = []
    if snapshot["format"] is None:
        limits.append("ledger_not_present:未执行或路径错误, 与'已有账本丢失'不同")
    if anchor_status == "unanchored":
        limits.append("unanchored:无外部 checkpoint, 不得宣称防尾部删除")
    if anchor_status == "invalid":
        limits.append("anchor_invalid:checkpoint 无法读取, 未获得锚定保证")
    if anchor_status == "mismatch":
        limits.append("anchor_mismatch:账本与 checkpoint 不一致, 结果不可信")
    if snapshot.get("format") == FORMAT_SINGLE:
        limits.append("legacy_v5:旧版单文件账本仅做链校验, 追加前需显式迁移")
    if snapshot.get("partial"):
        limits.append("uncommitted_tail:存在未提交尾段, 需 recover_ledger 处理")
    if snapshot.get("format") == FORMAT_SEGMENTED:
        limits.append("index_anchor_is_local:索引是本地提交点, 与账本同信任域, 不替代外部 checkpoint")
    if errors:
        limits.append("errors_present:%d 条校验错误" % len(errors))
    if not limits:
        limits.append("none")
    return limits


def verify_ledger(path, checkpoint=None, checkpoint_mode="strict",
                  artifacts_root=None, verify_artifacts=False) -> dict:
    """校验账本。checkpoint 可为 dict 或 checkpoint 文件路径。"""
    resolved = _absolute_no_symlink(Path(path))
    return _read_and_verify(resolved, checkpoint, checkpoint_mode, artifacts_root, verify_artifacts)[1]


# ------------------------------------------------------------------ 追加 (v6)

def _prepare_candidate(entry: dict, seq: int, previous: str, schema: str) -> dict:
    if not isinstance(entry, dict):
        raise ValueError("entry_not_object")
    entry_type = entry.get("entry_type")
    if entry_type not in ALLOWED_ENTRY_TYPES:
        raise ValueError("unknown_entry_type")
    for key in ("prev_record_hash", "record_hash", "evidence_id"):
        if key in entry:
            raise ValueError("caller_derived_fields_rejected:" + key)
    if "schema" in entry and entry["schema"] != schema:
        raise ValueError("invalid_ledger_schema")
    if "seq" in entry and (type(entry["seq"]) is not int or entry["seq"] != seq):
        raise ValueError("seq_must_be_contiguous")
    candidate = dict(entry)
    candidate["schema"] = schema
    candidate["seq"] = seq
    candidate.setdefault("occurred_at", _now())
    candidate["prev_record_hash"] = previous
    if schema == SCHEMA_V6:
        candidate["evidence_id"] = evidence_id(candidate)
    candidate["record_hash"] = _record_hash(previous, candidate, schema)
    (_validate_entry_v6 if schema == SCHEMA_V6 else _validate_entry_v5)(candidate)
    return candidate


def _check_candidate_v6(candidate: dict, index: dict, path: Path):
    entry_type = candidate["entry_type"]
    if entry_type == "state_event":
        phase = index.get("phase", FIRST_PHASE)
        if candidate["from"] != phase:
            raise ValueError("state_from_mismatch:%s!=%s" % (candidate["from"], phase))
    elif entry_type == "execution_pre":
        execution = candidate["execution_id"]
        if execution in index["open_executions"]:
            raise ValueError("duplicate_execution_id:" + execution)
        recent = {item.get("execution_id") for item in index.get("recent_executions") or []}
        if execution in recent:
            raise ValueError("reused_execution_id:" + execution)
    elif entry_type == "execution_post":
        execution = candidate["execution_id"]
        record = index["open_executions"].get(execution)
        if record is None:
            hint = "异常中止也必须写 execution_post(status=aborted)"
            if execution in {item.get("execution_id") for item in index.get("recent_executions") or []}:
                raise ValueError("duplicate_execution_post:%s (%s)" % (execution, hint))
            raise ValueError("orphan_execution_post:" + execution)
        for field in ("owner", "target", "channel", "task_id", "authorization_ref"):
            if record.get(field) != candidate[field]:
                raise ValueError("execution_field_mismatch:%s" % field)
        if record.get("command_sha256") != sha(candidate["command"].encode("utf-8")):
            raise ValueError("execution_command_mismatch")
    elif entry_type == "unknown_revision":
        expected = int(index["unknowns"].get(candidate["unknown_id"], 0)) + 1
        if candidate["revision"] != expected:
            raise ValueError("unknown_revision_out_of_order:%d!=%d" % (candidate["revision"], expected))
    for ref in candidate.get("evidence_refs") or []:
        if ref not in _existing_evidence_ids(path, index):
            raise ValueError("unknown_evidence_ref:" + ref)


def _existing_evidence_ids(path: Path, index: dict) -> set:
    """解析 evidence_id 引用所需的集合; 只对带引用记录付费 (O(n))。"""
    ids = set()
    for segment in _segment_paths(path):
        raw = segment.read_bytes()
        if raw and not raw.endswith(b"\n"):
            raw = raw[:raw.rfind(b"\n") + 1]
        if not raw:
            continue
        for line in raw[:-1].split(b"\n"):
            if not line:
                continue
            try:
                item = _parse_json_line(line)
            except Exception:
                continue
            if isinstance(item, dict) and isinstance(item.get("evidence_id"), str):
                ids.add(item["evidence_id"])
    return ids


def _apply_index_delta(index: dict, candidate: dict):
    entry_type = candidate["entry_type"]
    index["entries"] = candidate["seq"]
    index["head"] = candidate["record_hash"]
    if entry_type == "state_event":
        index["phase"] = candidate["to"]
    elif entry_type == "execution_pre":
        index["open_executions"][candidate["execution_id"]] = {
            "seq": candidate["seq"],
            "owner": candidate["owner"],
            "target": candidate["target"],
            "channel": candidate["channel"],
            "task_id": candidate["task_id"],
            "authorization_ref": candidate["authorization_ref"],
            "command_sha256": sha(candidate["command"].encode("utf-8")),
        }
    elif entry_type == "execution_post":
        index["open_executions"].pop(candidate["execution_id"], None)
        recent = index.setdefault("recent_executions", [])
        recent.append({"execution_id": candidate["execution_id"], "seq": candidate["seq"],
                       "status": candidate["status"], "exit_code": candidate["exit_code"]})
        del recent[:-_RECENT_EXECUTIONS_KEPT]
    elif entry_type == "unknown_revision":
        index["unknowns"][candidate["unknown_id"]] = candidate["revision"]
    elif entry_type == "claim_revision":
        index["claims"][candidate["claim_id"]] = {"seq": candidate["seq"], "status": candidate["status"]}
    return index


def _write_segment_line(path: Path, index: dict, candidate: dict):
    active = index.get("active_segment")
    count = int(index.get("active_entries", 0))
    if not active or count >= _SEGMENT_MAX_ENTRIES:
        number = int(index.get("segment_count", 0)) + 1
        active = _segment_name(path, number)
        index["segment_count"] = number
        count = 0
    segment = path.with_name(active)
    line = (json.dumps(candidate, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
    # O(1) 崩溃一致性守卫: 段文件必须与索引记录的已提交字节数一致。
    # 崩溃只会让磁盘比索引"多"(未提交尾段), 绝不允许在脏尾段之后继续追加。
    actual_bytes = segment.stat().st_size if segment.exists() else 0
    expected_bytes = 0 if count == 0 else index.get("active_bytes")
    if expected_bytes is not None and actual_bytes != expected_bytes:
        raise ValueError("uncommitted_tail_detected:index=%s,disk=%s:run recover_ledger() first"
                         % (expected_bytes, actual_bytes))
    fd = _open_nofollow(segment, os.O_WRONLY | os.O_CREAT | os.O_APPEND)
    try:
        written = os.write(fd, line)
        if written != len(line):
            raise ValueError("segment_short_write")
        os.fsync(fd)
    finally:
        os.close(fd)
    index["active_segment"] = active
    index["active_entries"] = count + 1
    index["active_bytes"] = actual_bytes + len(line)
    _fsync_directory(path.parent)


def _append_v6(path: Path, entry: dict, lock_timeout, cancel):
    index_path = _index_path(path)
    index = _load_index(index_path)
    segments = _segment_paths(path)
    if index is None:
        if segments:
            raise ValueError("segment_index_missing:run recover_ledger to rebuild")
        index = _empty_index(path)
    elif not segments and index["entries"]:
        raise ValueError("segments_missing")
    candidate = _prepare_candidate(entry, index["entries"] + 1, index["head"], SCHEMA_V6)
    _check_candidate_v6(candidate, index, path)
    _write_segment_line(path, index, candidate)
    _apply_index_delta(index, candidate)
    _save_index(index_path, index)
    return candidate


def _append_v5(path: Path, entry: dict):
    entries = [] if not path.exists() or not path.read_bytes() else None
    if entries is None:
        snapshot = _read_single_file(path, strict=False)
        if snapshot["errors"]:
            raise ValueError("existing_ledger_invalid:" + json.dumps(snapshot["errors"][:5], ensure_ascii=False))
        entries = [item for item in snapshot["entries"] if isinstance(item, dict)]
    head, errors, _ = _chain_errors(entries)
    if errors:
        raise ValueError("existing_ledger_invalid:" + json.dumps(errors[:5], ensure_ascii=False))
    candidate = _prepare_candidate(entry, len(entries) + 1, head, SCHEMA_V5)
    line = (json.dumps(candidate, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
    body = b"".join(canonical(item) + b"\n" for item in entries) + line
    _atomic_write_bytes(path, body)
    return candidate


def append_entry(ledger_path, entry: dict, *, schema=None, lock_timeout=None, cancel=None) -> dict:
    """追加一条记录。

    schema=None  -> 新账本用 v6; 已有 v5 账本拒绝并提示显式迁移
    schema=v5    -> 显式旧版模式(仅供迁移期使用, 不做严格校验)
    """
    path = _absolute_no_symlink(Path(ledger_path))
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if schema not in (None, SCHEMA_V5, SCHEMA_V6):
        raise ValueError("invalid_ledger_schema")
    with _APPEND_LOCK, _FileLock(_lock_file(path), lock_timeout, cancel):
        fmt = _detect_format(path)
        if schema == SCHEMA_V5:
            # 旧版模式: 只允许落在单文件布局上(新建或已有 v5), 不得与 v6 段并存
            if fmt == FORMAT_SEGMENTED:
                raise ValueError("legacy_schema_on_v6_ledger")
            return _append_v5(path, entry)
        if fmt == FORMAT_SINGLE:
            raise ValueError("legacy_ledger_requires_migration:run migrate_ledger() first")
        return _append_v6(path, entry, lock_timeout, cancel)


# -------------------------------------------------------- 恢复 / 迁移 / 导出

def recover_ledger(ledger_path, *, commit_tail=False, lock_timeout=None) -> dict:
    """崩溃恢复: 截断(默认)或提交未提交尾段; 拒绝任何"账本变短"的静默修复。"""
    path = _absolute_no_symlink(Path(ledger_path))
    report = {"schema": SCHEMA_V6, "path": str(path), "actions": [], "ok": False, "errors": []}
    with _APPEND_LOCK, _FileLock(_lock_file(path), lock_timeout):
        fmt = _detect_format(path)
        if fmt is None:
            report["errors"].append(_err("ledger_not_present"))
            return report
        if fmt == FORMAT_SINGLE:
            raw = path.read_bytes()
            if raw and not raw.endswith(b"\n"):
                cut = raw.rfind(b"\n")
                keep = raw[:cut + 1] if cut >= 0 else b""
                _atomic_write_bytes(path, keep)
                report["actions"].append({"action": "truncated_partial_tail", "bytes": len(raw) - len(keep)})
            report["ok"] = verify_ledger(path)["ok"]
            return report
        index_path = _index_path(path)
        index = _load_index(index_path)
        segments = _segment_paths(path)
        if index is None:
            if not segments:
                report["errors"].append(_err("ledger_not_present"))
                return report
            snapshot = _read_segmented(path, _empty_index(path))
            head, chain_errors, _ = _chain_errors(snapshot["entries"])
            if chain_errors:
                report["errors"].extend(chain_errors[:5])
                return report
            index = _empty_index(path)
            index["entries"] = len([item for item in snapshot["entries"] if isinstance(item, dict)])
            index["head"] = head
            index["phase"] = _replay_phase(snapshot["entries"])
            _sync_segment_state(index, path)
            if snapshot["partial"]:
                _truncate_partial(segments[-1])
                report["actions"].append({"action": "truncated_partial_tail", "bytes": len(snapshot["partial"])})
            _save_index(index_path, index)
            report["actions"].append({"action": "index_rebuilt", "entries": index["entries"]})
            report["ok"] = verify_ledger(path)["ok"]
            return report
        committed = index["entries"]
        snapshot = _read_segmented(path, index)
        actual = len([item for item in snapshot["entries"] if isinstance(item, dict)])
        if actual < committed:
            report["errors"].append(_err("entries_below_index", committed=committed, observed=actual,
                                         hint="账本变短: 拒绝自动修复"))
            return report
        if actual == committed and not snapshot["partial"]:
            report["actions"].append({"action": "none"})
            report["ok"] = verify_ledger(path)["ok"]
            return report
        trimmed = [item for item in snapshot["entries"] if isinstance(item, dict)][committed:]
        if snapshot["partial"]:
            _truncate_partial(segments[-1])
            report["actions"].append({"action": "truncated_partial_tail", "bytes": len(snapshot["partial"])})
        if commit_tail and trimmed:
            head, chain_errors, _ = _chain_errors(snapshot["entries"])
            if chain_errors:
                report["errors"].extend(chain_errors[:5])
            else:
                for item in trimmed:
                    _apply_index_delta(index, item)
                index["entries"] = committed + len(trimmed)
                index["head"] = trimmed[-1]["record_hash"]
                _sync_segment_state(index, path)
                _save_index(index_path, index)
                report["actions"].append({"action": "committed_tail", "entries": len(trimmed)})
        elif trimmed:
            _truncate_to_committed(path, index, segments, committed)
            report["actions"].append({"action": "truncated_uncommitted_records", "entries": len(trimmed)})
        report["ok"] = verify_ledger(path)["ok"]
        report["errors"].extend(verify_ledger(path)["errors"])
        return report


def _truncate_partial(segment: Path):
    raw = segment.read_bytes()
    if raw and not raw.endswith(b"\n"):
        cut = raw.rfind(b"\n")
        _atomic_write_bytes(segment, raw[:cut + 1] if cut >= 0 else b"")


def _truncate_to_committed(path: Path, index: dict, segments, committed: int):
    remaining = committed
    for number, segment in enumerate(segments, 1):
        raw = segment.read_bytes()
        lines = raw[:-1].split(b"\n") if raw.endswith(b"\n") else raw.split(b"\n")
        lines = [line for line in lines if line]
        if remaining >= len(lines):
            remaining -= len(lines)
            continue
        keep = b"".join(line + b"\n" for line in lines[:remaining])
        _atomic_write_bytes(segment, keep)
        for later in segments[number:]:
            _atomic_write_bytes(later, b"")
        remaining = 0
        break


def _replay_phase(entries):
    phase = FIRST_PHASE
    for entry in entries:
        if isinstance(entry, dict) and entry.get("entry_type") == "state_event" and (entry.get("from"), entry.get("to")) in TRANSITIONS:
            phase = entry["to"]
    return phase


def _sync_segment_state(index: dict, path: Path):
    """恢复索引里的段游标。段清单不入索引: 索引大小必须与账本长度无关。"""
    segments = _segment_paths(path)
    index["segment_count"] = len(segments)
    if not segments:
        index["active_segment"] = None
        index["active_entries"] = 0
        index["active_bytes"] = 0
        return
    raw = segments[-1].read_bytes()
    if raw and not raw.endswith(b"\n"):
        raw = raw[:raw.rfind(b"\n") + 1]
    index["active_segment"] = segments[-1].name
    index["active_entries"] = len([line for line in raw.split(b"\n") if line])
    index["active_bytes"] = len(raw)


def init_ledger(ledger_path) -> dict:
    """显式创建空 v6 账本 (0 条已提交记录)。"""
    path = _absolute_no_symlink(Path(ledger_path))
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    with _APPEND_LOCK, _FileLock(_lock_file(path)):
        fmt = _detect_format(path)
        if fmt == FORMAT_SINGLE:
            raise ValueError("legacy_ledger_requires_migration")
        index_path = _index_path(path)
        if _load_index(index_path) is not None:
            raise ValueError("ledger_already_initialised")
        index = _empty_index(path)
        _save_index(index_path, index)
        return {"schema": SCHEMA_V6, "path": str(path), "entries": 0, "head": GENESIS}


def export_ledger(ledger_path, out_path=None) -> dict:
    """导出为单文件 JSONL(可导出哈希链), 只含已提交记录。"""
    path = _absolute_no_symlink(Path(ledger_path))
    entries, result = _read_and_verify(path)
    if result["status"] in (STATUS_FAIL, STATUS_ERROR):
        return {"ok": False, "errors": result["errors"][:5], "entries": result["entries"]}
    body = b"".join(canonical(entry) + b"\n" for entry in entries)
    if out_path is not None:
        target = Path(out_path)
        target.parent.mkdir(parents=True, exist_ok=True)
        _atomic_write_bytes(target, body)
    return {"ok": True, "entries": len(entries), "head": result["head"],
            "sha256": sha(body), "bytes": len(body), "out": None if out_path is None else str(out_path),
            "content": None if out_path is not None else body.decode("utf-8")}


def migrate_ledger(ledger_path, annotations=None, out_path=None) -> dict:
    """v5 -> v6 显式迁移。

    annotations: {seq: {缺失字段...}} 或 {"entries": {seq: {...}}}。
    未提供时只返回迁移计划(缺哪些字段), 不写任何文件 — 绝不伪造五元组。
    """
    path = _absolute_no_symlink(Path(ledger_path))
    if not path.is_file():
        return {"ok": False, "errors": [_err("ledger_not_present")]}
    snapshot = _read_single_file(path, strict=False)
    if snapshot["errors"]:
        return {"ok": False, "errors": snapshot["errors"][:5], "stage": "read"}
    if snapshot["partial"]:
        return {"ok": False, "stage": "read",
                "errors": [_err("uncommitted_tail", kind="partial",
                                hint="先 recover_ledger 处理未提交尾段再迁移")]}
    _head, chain_errors, _ = _chain_errors(snapshot["entries"])
    if chain_errors:
        return {"ok": False, "errors": chain_errors[:5], "stage": "read",
                "hint": "源账本哈希链已断: 迁移会掩盖篡改, 拒绝"}
    legacy = [item for item in snapshot["entries"] if isinstance(item, dict)]
    if isinstance(annotations, dict) and isinstance(annotations.get("entries"), dict):
        annotations = annotations["entries"]
    annotations = annotations or {}
    plans, missing = [], []
    for entry in legacy:
        seq = entry.get("seq")
        merged = dict(entry)
        merged.update(annotations.get(seq) or annotations.get(str(seq)) or {})
        merged.pop("record_hash", None)
        merged.pop("prev_record_hash", None)
        merged.pop("evidence_id", None)
        merged["schema"] = SCHEMA_V6
        try:
            _validate_entry_v6({**merged, "prev_record_hash": GENESIS, "record_hash": GENESIS,
                                "evidence_id": evidence_id({**merged, "prev_record_hash": GENESIS,
                                                            "record_hash": GENESIS})}, seq)
        except ValueError as exc:
            code = str(exc).split(":", 1)[0]
            missing.append({"seq": seq, "code": code, "detail": str(exc)})
            plans.append({"seq": seq, "needs": code})
    if missing:
        return {"ok": False, "stage": "plan", "legacy_entries": len(legacy),
                "unmappable": missing[:50], "hint": "为每个 seq 补齐五元组与分类型必需字段后重跑", "wrote": False}
    target = Path(out_path) if out_path else path.with_name(path.name + ".v6")
    index_path = _index_path(target)
    if index_path.exists() or _segment_paths(target):
        return {"ok": False, "errors": [_err("target_exists")], "target": str(target)}
    head = GENESIS
    for entry in legacy:
        merged = dict(entry)
        merged.update(annotations.get(entry["seq"]) or annotations.get(str(entry["seq"])) or {})
        for key in ("record_hash", "prev_record_hash", "evidence_id", "seq", "schema"):
            merged.pop(key, None)
        candidate = _append_v6(target, merged, None, None)
        head = candidate["record_hash"]
    return {"ok": True, "target": str(target), "entries": len(legacy),
            "head": head, "legacy_preserved": str(path)}


# ------------------------------------------------------------------- replay

def replay(path, checkpoint=None, checkpoint_mode="strict", artifacts_root=None,
           verify_artifacts=False) -> dict:
    resolved = _absolute_no_symlink(Path(path))
    state = {"phase": FIRST_PHASE, "lifecycle_status": "active", "claims": {}, "unknowns": {},
             "counterexamples": [], "executions": {}, "ledger_head": None, "entries": 0}
    entries, check = _read_and_verify(resolved, checkpoint, checkpoint_mode, artifacts_root, verify_artifacts)
    if check["status"] in (STATUS_FAIL, STATUS_ERROR):
        state["phase"] = _replay_phase(entries)
        state["entries"] = len(entries)
        state["ledger_head"] = entries[-1]["record_hash"] if entries else None
        return {"state": state, "verification": check}
    for item in entries:
        state["ledger_head"] = item["record_hash"]
        entry_type = item.get("entry_type")
        if entry_type == "state_event" and item.get("to"):
            state["phase"] = item["to"]
        elif entry_type == "claim_revision":
            state["claims"][item["claim_id"]] = item
            state["lifecycle_status"] = item.get("status", state["lifecycle_status"])
        elif entry_type == "unknown_revision":
            state["unknowns"][item["unknown_id"]] = item
        elif entry_type == "counterexample":
            state["counterexamples"].append(item)
        elif entry_type in EXECUTION_ENTRY_TYPES:
            record = state["executions"].setdefault(item["execution_id"], {"pre": None, "post": None})
            record["pre" if entry_type == "execution_pre" else "post"] = item
    state["entries"] = len(entries)
    return {"state": state, "verification": check}


# ---------------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="Evidence ledger (v6 strict / v5 legacy)")
    ap.add_argument("--ledger", required=True)
    ap.add_argument("--verify", action="store_true")
    ap.add_argument("--replay", action="store_true")
    ap.add_argument("--init", action="store_true", help="创建空 v6 账本")
    ap.add_argument("--append-json", default=None, help="追加一条 JSON 记录 (@file 亦可)")
    ap.add_argument("--append-file", default=None)
    ap.add_argument("--recover", action="store_true")
    ap.add_argument("--commit-tail", action="store_true", help="恢复时提交(而非截断)完整未提交尾段")
    ap.add_argument("--export", default=None, help="导出单文件 JSONL 到该路径")
    ap.add_argument("--migrate", action="store_true")
    ap.add_argument("--annotations", default=None)
    ap.add_argument("--out", default=None, help="迁移目标账本路径")
    ap.add_argument("--checkpoint", default=None)
    ap.add_argument("--checkpoint-mode", default="strict", choices=("strict", "extends"))
    ap.add_argument("--artifacts-root", default=None)
    ap.add_argument("--verify-artifacts", action="store_true")
    ap.add_argument("--lock-timeout", type=float, default=None)
    args = ap.parse_args(argv)

    action = "verify"
    try:
        if args.init:
            action = "init"
            result = init_ledger(args.ledger)
        elif args.append_json is not None or args.append_file is not None:
            action = "append"
            raw = args.append_json if args.append_json is not None else args.append_file
            if raw.startswith("@"):
                raw = Path(raw[1:]).read_text(encoding="utf-8")
            elif args.append_file is not None:
                raw = Path(raw).read_text(encoding="utf-8")
            result = append_entry(args.ledger, json.loads(raw), lock_timeout=args.lock_timeout)
        elif args.recover:
            action = "recover"
            result = recover_ledger(args.ledger, commit_tail=args.commit_tail,
                                    lock_timeout=args.lock_timeout)
        elif args.export is not None:
            action = "export"
            result = export_ledger(args.ledger, args.export)
        elif args.migrate:
            action = "migrate"
            annotations = None
            if args.annotations:
                annotations = json.loads(Path(args.annotations).read_text(encoding="utf-8"))
            result = migrate_ledger(args.ledger, annotations, args.out)
        elif args.replay:
            action = "replay"
            result = replay(args.ledger, args.checkpoint, args.checkpoint_mode,
                            args.artifacts_root, args.verify_artifacts)
        else:
            result = verify_ledger(args.ledger, args.checkpoint, args.checkpoint_mode,
                                   args.artifacts_root, args.verify_artifacts)
    except (ValueError, TimeoutError) as exc:
        # 校验失败/锁超时是"已执行且断言不满足", 不是崩溃: 给结构化错误 + 退出码 3
        print(json.dumps({"ok": False, "type": type(exc).__name__, "error": str(exc)},
                         ensure_ascii=False, indent=2))
        return 3
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0 if _cli_ok(action, result) else 3


def _cli_ok(action: str, result: dict) -> bool:
    """退出码 0 = 该动作成功; 3 = 已执行但断言不满足(空账本/未锚定失败/未迁移等)。"""
    if not isinstance(result, dict):
        return False
    if action in ("verify", "replay"):
        verdict = result.get("verification", result)
        return bool(verdict.get("ok")) if isinstance(verdict, dict) else False
    if action == "append":
        return isinstance(result.get("seq"), int) and isinstance(result.get("record_hash"), str)
    if action == "init":
        return result.get("entries") == 0 and isinstance(result.get("head"), str)
    return result.get("ok") is True


if __name__ == "__main__":
    raise SystemExit(main())
