#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""fetch_tools.py — 按 references/tool-manifest.json 校验/取回工具包的工具依赖。

设计原则（与工具包铁律 5/8 一致）
--------------------------------
* **默认只检查，不下载**（`--check` 是默认动作）。
* `--fetch` 只把 fetchable 项下载到 `<工作根>/vendor-cache/` 并校验 sha256；
  **不安装**、**不改 PATH**、**不执行**任何下载物。
* `bundled` 项缺失或 hash 不符 = **硬失败**（退出码 1）；这是"包自包含"的核心断言。
* `external` 项缺失 = 正常现象（BYO），只打印**精确获取命令**；不做假探针。
* 下载失败/校验失败一律**显式报错**，绝不静默继续、绝不把错误页当成功。

分类语义
--------
``bundled``   文件应已在包内 -> 校验存在 + sha256（含 `shipped_files[]` 逐文件校验）
``fetchable`` 版本与 URL 已锁定、download_sha256 已实测 -> 可 `--fetch` 到 vendor-cache
``external``  系统级/GUI/商业/MCP/外部快照 -> 只探测 + 打印获取方式
``absent-by-policy`` 策略要求**绝不能出现在发行树里**的路径 -> 断言其不存在

``absent-by-policy`` 的用途
--------------------------
把"已退役的共享身份/私钥不得重新随包发行"这类**阴性要求**变成可运行的断言，
而不是只写在文档里。典型：``skills/NPC-MOB-Delta-0004/debug.keystore``（F30）——
原始归档里存在，本次整改已按身份策略移出发行树并归档到非发行目录；
签名脚本改为在用户私有目录按需自生成 + 拒绝已知共享指纹。
因此正确的断言不是"文件在不在"，而是**"它绝不能回来"**。
路径重新出现 = ``policy-violation`` = 硬失败。

退出码
------
0  全部 bundled 校验通过、且无 absent-by-policy 违规
1  bundled 缺失/hash 不符，或 absent-by-policy 违规
4  `--fetch` 过程中有下载/校验失败
2  用法或环境错误

用法
----
    python -B scripts/fetch_tools.py --check
    python -B scripts/fetch_tools.py --check --json
    python -B scripts/fetch_tools.py --check --id die --id jadx
    python -B scripts/fetch_tools.py --fetch
    python -B scripts/fetch_tools.py --check --manifest <other.json> --cache-dir <dir>
    python -B scripts/fetch_tools.py --check --strict      # fetchable 未缓存也算失败
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

SCHEMA = "npc-tool-fetch-report/1"

# Windows 控制台默认可能是 GBK，直接 print 中文/非 GBK 字符会 UnicodeEncodeError。
# 统一把 stdout/stderr 切到 UTF-8 并用 replace 兜底，保证报告不因终端编码而中断。
for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except (AttributeError, ValueError):
        pass

DEFAULT_MANIFEST = "work/references/tool-manifest.json"

# 下载体积上限（防止把磁盘写满）：单文件 512 MiB
MAX_DOWNLOAD_BYTES = 512 * 1024 * 1024
# 视为"错误页/代理页"而非制品的内容类型
HTML_TYPES = ("text/html", "application/xhtml+xml")


class Finding:
    __slots__ = ("tool_id", "kind", "status", "detail", "extra")

    def __init__(self, tool_id, kind, status, detail, **extra):
        self.tool_id = tool_id
        self.kind = kind
        self.status = status
        self.detail = detail
        self.extra = extra

    def as_dict(self):
        d = {"id": self.tool_id, "kind": self.kind, "status": self.status, "detail": self.detail}
        d.update(self.extra)
        return d


def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def norm_sha(v):
    if not v:
        return None
    v = str(v).strip().lower()
    if v.startswith("sha256:"):
        v = v.split(":", 1)[1]
    return v if re.fullmatch(r"[0-9a-f]{64}", v) else None


# ---------------------------------------------------------------------------
# bundled
# ---------------------------------------------------------------------------
def check_bundled(tool: dict, pkg_root: Path) -> list[Finding]:
    out: list[Finding] = []
    rel = (tool.get("bundled_path") or "").strip("/")
    if not rel:
        out.append(Finding(tool["id"], "bundled", "error", "manifest 缺 bundled_path"))
        return out

    target = (pkg_root / rel).resolve()
    try:
        target.relative_to(pkg_root.resolve())
    except ValueError:
        out.append(Finding(tool["id"], "bundled", "error",
                           f"bundled_path 逃出包根（拒绝越界）: {rel}"))
        return out

    if not target.exists():
        out.append(Finding(tool["id"], "bundled", "missing",
                           f"包内不存在: {rel}",
                           expected_sha256=tool.get("shipped_sha256"),
                           acquire=tool.get("download_url") or tool.get("upstream")))
        return out

    files = tool.get("shipped_files") or []
    if files:
        ok = 0
        for f in files:
            fp = target / f["path"]
            if not fp.is_file():
                out.append(Finding(tool["id"], "bundled", "missing",
                                   f"缺文件: {rel}/{f['path']}",
                                   acquire=tool.get("download_url") or tool.get("upstream")))
                continue
            actual = sha256_file(fp)
            if actual != norm_sha(f.get("sha256")):
                out.append(Finding(tool["id"], "bundled", "hash-mismatch",
                                   f"hash 不符: {rel}/{f['path']}",
                                   expected_sha256=f.get("sha256"), actual_sha256=actual))
            else:
                ok += 1
        if ok == len(files):
            out.append(Finding(tool["id"], "bundled", "ok",
                               f"{ok}/{len(files)} 个随包文件 hash 全部相符（{rel}）"))
        return out

    if target.is_file():
        expected = norm_sha(tool.get("shipped_sha256"))
        actual = sha256_file(target)
        if expected is None:
            out.append(Finding(tool["id"], "bundled", "unverifiable",
                               f"{rel} 存在，但 manifest 未登记 shipped_sha256（无法断言完整性）",
                               actual_sha256=actual))
        elif actual != expected:
            out.append(Finding(tool["id"], "bundled", "hash-mismatch",
                               f"hash 不符: {rel}", expected_sha256=expected, actual_sha256=actual))
        else:
            out.append(Finding(tool["id"], "bundled", "ok", f"hash 相符: {rel}"))
    else:
        out.append(Finding(tool["id"], "bundled", "present-unverified",
                           f"{rel} 目录存在（{len(list(target.iterdir()))} 项）；"
                           f"manifest 未登记逐文件 hash，无法断言完整性"))
    return out


# ---------------------------------------------------------------------------
# fetchable
# ---------------------------------------------------------------------------
def cache_target(tool: dict, cache_dir: Path, root: Path | None = None) -> Path:
    """已落盘的缓存位置。

    优先用 manifest 里的 `vendor_cache_path`（仓库相对路径）——这样别人已经放好的
    厂商缓存会被直接认到，而不是被当成"未缓存"再下一遍。
    """
    vcp = (tool.get("vendor_cache_path") or "").strip()
    if vcp and root is not None:
        p = (root / vcp).resolve()
        try:
            p.relative_to(root.resolve())
        except ValueError:
            pass
        else:
            return p
    url = tool.get("download_url") or ""
    name = tool.get("asset") or tool.get("artifact")
    if not name and url:
        name = urllib.parse.unquote(Path(urllib.parse.urlparse(url).path).name)
    if not name:
        name = f"{tool['id']}.bin"
    return cache_dir / tool["id"] / name


def _open_url(url: str, timeout: int = 60):
    req = urllib.request.Request(url, headers={"User-Agent": "npc-fetch-tools/1.0"})
    return urllib.request.urlopen(req, timeout=timeout)


def _pypi_project_name(tool: dict) -> str:
    """推断 PyPI **发行名**（distribution name）。

    为什么不能直接用 `python_import_name`：那是 **import 名**，两者常常不同 ——
    实测踩过：`elftools`(import) vs `pyelftools`(发行)、`yaml` vs `PyYAML`、
    `Crypto` vs `pycryptodome`、`capa` vs `flare-capa`、`yara` vs `yara-python`。
    用 import 名查 PyPI 会 404，或者更糟 —— 命中**另一个同名项目**
    （`yara`、`Crypto`、`capa` 在 PyPI 上确实存在，但是完全不同的包，
    拿它们的数据去校验会得到"看似成功"的错误结论）。

    优先用清单登记的 `artifact` 文件名反推：`pyelftools-0.33.tar.gz` -> `pyelftools`；
    其次用显式 `pypi_project`；最后退回 id。
    """
    art = tool.get("artifact")
    ver = tool.get("pinned_version")
    if art and ver:
        for suf in (".tar.gz", ".tgz", ".zip", ".whl"):
            if art.endswith(suf):
                stem = art[: -len(suf)]
                marker = "-" + str(ver)
                if stem.endswith(marker):
                    return stem[: -len(marker)]
                break
    proj = tool.get("pypi_project")
    if proj:
        return str(proj)
    return str(tool.get("id") or tool.get("python_import_name"))


def _pypi_resolve_url(tool: dict) -> tuple[str | None, str]:
    """用 PyPI JSON API 把 (包名, 版本) 解析成一个**与清单 sha256 相符**的文件 URL。

    为什么按 sha256 反查而不是按文件名拼 URL：同一版本可能有几十个文件
    （sdist + 各平台/各解释器的 wheel），拼 URL 很容易下到别的东西。
    清单里的 download_sha256 是实测值，用它当**唯一真值**最稳：
    在候选文件里找 digest 相同的那一个；找不到就报错，绝不"下个差不多的"。

    返回 (url, note)；url 为 None 表示解析失败。
    """
    name = _pypi_project_name(tool)
    ver = tool.get("pinned_version")
    want = norm_sha(tool.get("download_sha256"))
    art = tool.get("artifact")
    if not ver:
        return None, "manifest 缺 pinned_version"
    api = f"https://pypi.org/pypi/{urllib.parse.quote(str(name))}/{urllib.parse.quote(str(ver))}/json"
    try:
        with _open_url(api) as resp:
            doc = json.loads(resp.read().decode("utf-8", "replace"))
    except Exception as exc:  # noqa: BLE001
        return None, f"PyPI JSON API 失败: {type(exc).__name__}:{str(exc)[:80]}"

    cands = list(doc.get("urls") or [])
    for f in (doc.get("releases") or {}).get(str(ver), []) or []:
        cands.append(f)
    if not cands:
        return None, f"PyPI 未返回 {name}=={ver} 的文件列表"

    if want:
        for f in cands:
            if norm_sha((f.get("digests") or {}).get("sha256")) == want:
                return f.get("url"), f"按 sha256 命中 {f.get('filename')}"
        return None, (f"PyPI 上没有 digest={want[:16]}… 的文件（清单 artifact={art}）；"
                      f"候选 {len(cands)} 个")

    # 清单没登记 digest 时只接受**唯一同名**文件，避免歧义
    same = [f for f in cands if f.get("filename") == art]
    if len(same) == 1:
        return same[0].get("url"), "按文件名唯一命中（清单未登记 sha256，将记为 fetched-unverified）"
    return None, f"清单未登记 sha256 且文件名不唯一（artifact={art}, 候选 {len(cands)} 个）"


def _pypi_fetch(tool: dict, cached: Path) -> Finding:
    """下载并校验一个 PyPI 制品。**校验不通过绝不落盘到最终路径。**"""
    tid = tool["id"]
    want = norm_sha(tool.get("download_sha256"))
    url, note = _pypi_resolve_url(tool)
    if not url:
        return Finding(tid, "fetchable", "error", f"PyPI 解析失败: {note}",
                       upstream=tool.get("upstream"))
    cached.parent.mkdir(parents=True, exist_ok=True)
    tmp_fd, tmp_name = tempfile.mkstemp(prefix=tid + ".", suffix=".part", dir=str(cached.parent))
    os.close(tmp_fd)
    tmp = Path(tmp_name)
    try:
        with _open_url(url) as resp:
            ctype = (resp.headers.get("Content-Type") or "").split(";")[0].strip().lower()
            if ctype in HTML_TYPES:
                return Finding(tid, "fetchable", "bad-content",
                               f"PyPI 文件 URL 返回 HTML（Content-Type={ctype}）: {url}")
            written = 0
            with tmp.open("wb") as out:
                while True:
                    chunk = resp.read(1 << 20)
                    if not chunk:
                        break
                    written += len(chunk)
                    if written > MAX_DOWNLOAD_BYTES:
                        return Finding(tid, "fetchable", "too-large",
                                       f"超过 {MAX_DOWNLOAD_BYTES} 字节上限: {url}")
                    out.write(chunk)
        if written == 0:
            return Finding(tid, "fetchable", "empty", f"下载得到 0 字节: {url}")
        got = sha256_file(tmp)
        if want and got != want:
            return Finding(tid, "fetchable", "hash-mismatch",
                           f"下载物 hash 不符（已丢弃，未落盘）: {note}",
                           expected_sha256=want, actual_sha256=got)
        os.replace(tmp, cached)
        return Finding(tid, "fetchable", "ok" if want else "fetched-unverified",
                       f"已取回并校验: {cached.name} ({written} 字节) [{note}]",
                       actual_sha256=got, download_url=url)
    except Exception as exc:  # noqa: BLE001
        return Finding(tid, "fetchable", "network-error",
                       f"{type(exc).__name__}:{str(exc)[:120]}", download_url=url)
    finally:
        try:
            if tmp.exists():
                tmp.unlink()
        except OSError:
            pass


def check_or_fetch(tool: dict, cache_dir: Path, do_fetch: bool, root: Path | None = None) -> Finding:
    tid = tool["id"]
    sha_expected = norm_sha(tool.get("download_sha256"))
    url = tool.get("download_url")
    cached = cache_target(tool, cache_dir, root)

    if tool.get("source_type") == "pypi":
        # PyPI 项：按清单登记的 sha256 从 PyPI JSON API 反查**精确文件**并下载（只下载不安装）。
        # 注意同一版本有多种制品（sdist + 多平台 wheel），所以按 sha256 而不是文件名匹配。
        if cached.exists():
            got = sha256_file(cached)
            if sha_expected and got == sha_expected:
                return Finding(tid, "fetchable", "ok", f"vendor-cache 命中且 hash 相符: {cached}")
            if sha_expected:
                return Finding(tid, "fetchable", "hash-mismatch",
                               f"vendor-cache 命中但 hash 不符: {cached}",
                               expected_sha256=sha_expected, actual_sha256=got)
            return Finding(tid, "fetchable", "present-unverified", f"vendor-cache 命中（未登记 hash）: {cached}")
        if not do_fetch:
            return Finding(tid, "fetchable", "not-cached",
                           f"未缓存；pinned={tool.get('pinned_version')} sha256={sha_expected or '未登记'}",
                           install_command=tool.get("install_command"),
                           pinned_version=tool.get("pinned_version"))
        return _pypi_fetch(tool, cached)

    if not url:
        return Finding(tid, "fetchable", "error", "manifest 缺 download_url")

    if cached.exists() and not do_fetch:
        got = sha256_file(cached)
        if sha_expected is None:
            return Finding(tid, "fetchable", "present-unverified",
                           f"vendor-cache 命中但 manifest 未登记 download_sha256: {cached}",
                           actual_sha256=got)
        if got == sha_expected:
            return Finding(tid, "fetchable", "ok", f"vendor-cache 命中且 hash 相符: {cached}")
        return Finding(tid, "fetchable", "hash-mismatch",
                       f"vendor-cache 命中但 hash 不符（缓存已损坏或被替换）: {cached}",
                       expected_sha256=sha_expected, actual_sha256=got)

    if not do_fetch:
        return Finding(tid, "fetchable", "not-cached",
                       f"未缓存；pinned_tag={tool.get('pinned_tag')} sha256={sha_expected or '未登记'}",
                       download_url=url, pinned_version=tool.get("pinned_version"))

    # ---- 真正下载 ----
    cached.parent.mkdir(parents=True, exist_ok=True)
    tmp_fd, tmp_name = tempfile.mkstemp(prefix=tid + ".", suffix=".part", dir=str(cached.parent))
    os.close(tmp_fd)
    tmp = Path(tmp_name)
    try:
        try:
            with _open_url(url) as resp:
                ctype = (resp.headers.get("Content-Type") or "").split(";")[0].strip().lower()
                clen = resp.headers.get("Content-Length")
                if ctype in HTML_TYPES:
                    return Finding(tid, "fetchable", "bad-content",
                                   f"上游返回 HTML（Content-Type={ctype}）而不是制品 —— "
                                   f"多半是错误页/代理页/限流页，判为失败: {url}",
                                   download_url=url)
                written = 0
                with tmp.open("wb") as out:
                    while True:
                        chunk = resp.read(1 << 20)
                        if not chunk:
                            break
                        written += len(chunk)
                        if written > MAX_DOWNLOAD_BYTES:
                            return Finding(tid, "fetchable", "too-large",
                                           f"下载超过 {MAX_DOWNLOAD_BYTES} 字节上限，已中止: {url}")
                        out.write(chunk)
                if clen and clen.isdigit() and int(clen) != written:
                    return Finding(tid, "fetchable", "truncated",
                                   f"Content-Length={clen} 与实际写入 {written} 字节不符（下载被截断）",
                                   download_url=url)
                if written == 0:
                    return Finding(tid, "fetchable", "empty",
                                   f"上游返回 0 字节: {url}", download_url=url)
                got = sha256_file(tmp)
                if sha_expected is None:
                    shutil.move(str(tmp), str(cached))
                    return Finding(tid, "fetchable", "fetched-unverified",
                                   f"已下载 {written} 字节到 {cached}，但 manifest 未登记 download_sha256，"
                                   f"无法断言完整性；实测 sha256={got}",
                                   actual_sha256=got, bytes=written)
                if got != sha_expected:
                    return Finding(tid, "fetchable", "hash-mismatch",
                                   f"下载后 sha256 不符，**制品已丢弃、未落盘到 vendor-cache**",
                                   expected_sha256=sha_expected, actual_sha256=got,
                                   download_url=url, bytes=written)
                shutil.move(str(tmp), str(cached))
                return Finding(tid, "fetchable", "fetched",
                               f"已下载并校验通过: {cached}（{written} 字节）",
                               actual_sha256=got, bytes=written)
        except urllib.error.HTTPError as e:
            return Finding(tid, "fetchable", "http-error",
                           f"HTTP {e.code} {e.reason}: {url}", download_url=url)
        except urllib.error.URLError as e:
            return Finding(tid, "fetchable", "network-error",
                           f"网络不可达: {e.reason}（{url}）；"
                           f"本机出网按主机选择性放行，可试系统代理 http://127.0.0.1:7897",
                           download_url=url)
        except Exception as e:  # noqa: BLE001
            return Finding(tid, "fetchable", "error", f"{type(e).__name__}: {e}", download_url=url)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass


# ---------------------------------------------------------------------------
# external
# ---------------------------------------------------------------------------
def check_external(tool: dict) -> Finding:
    tid = tool["id"]
    probe = tool.get("probe_command")
    acq = tool.get("acquisition") or tool.get("install_command") or "(manifest 未登记获取方式)"
    if not probe:
        return Finding(tid, "external", "manual",
                       tool.get("probe_command_note") or "无可自动探测的探针",
                       acquisition=acq, upstream=tool.get("upstream"),
                       pinned_version=tool.get("pinned_version"))
    found = shutil.which(probe)
    if found:
        return Finding(tid, "external", "present", f"{probe} -> {found}",
                       acquisition=acq, upstream=tool.get("upstream"))
    return Finding(tid, "external", "absent",
                   f"PATH 上找不到 {probe}",
                   acquisition=acq, upstream=tool.get("upstream"), pinned_version=tool.get("pinned_version"))


# ---------------------------------------------------------------------------
# absent-by-policy
# ---------------------------------------------------------------------------
def check_absent_by_policy(tool: dict, pkg_root: Path) -> list[Finding]:
    """断言某路径**必须不存在**（阴性要求）。

    这类条目的价值全在"重新出现即失败"：它把已退役的共享私钥/身份挡在发行树之外。
    因此本函数**不给** exists -> ok 的宽松分支：只要目标在树里出现就是 policy-violation。
    """
    tid = tool["id"]
    out: list[Finding] = []
    rel = (tool.get("forbidden_path") or "").strip("/")
    if not rel:
        out.append(Finding(tid, "absent-by-policy", "error", "manifest 缺 forbidden_path"))
        return out

    target = (pkg_root / rel).resolve()
    try:
        target.relative_to(pkg_root.resolve())
    except ValueError:
        out.append(Finding(tid, "absent-by-policy", "error",
                           f"forbidden_path 逃出包根（拒绝越界断言）: {rel}"))
        return out

    if target.exists():
        out.append(Finding(tid, "absent-by-policy", "policy-violation",
                           f"策略禁止的路径重新出现在发行树里: {rel}",
                           path=rel,
                           retired_sha256=tool.get("retired_sha256"),
                           archived_at=tool.get("archived_at"),
                           policy=(tool.get("note") or "")[:400]))
        return out

    out.append(Finding(tid, "absent-by-policy", "ok",
                       f"策略要求缺失，实测不存在: {rel}",
                       path=rel, retired_sha256=tool.get("retired_sha256")))
    return out


# ---------------------------------------------------------------------------
# main
# ---------------------------------------------------------------------------
def run(manifest_path: Path, pkg_root: Path, cache_dir: Path, ids, kinds, do_fetch: bool,
        root: Path | None = None) -> dict:
    data = json.loads(manifest_path.read_text(encoding="utf-8"))
    tools = data.get("tools") or []
    findings: list[Finding] = []
    for t in tools:
        if ids and t["id"] not in ids:
            continue
        if kinds and t["kind"] not in kinds:
            continue
        if t["kind"] == "bundled":
            findings.extend(check_bundled(t, pkg_root))
        elif t["kind"] == "fetchable":
            findings.append(check_or_fetch(t, cache_dir, do_fetch, root))
        elif t["kind"] == "external":
            findings.append(check_external(t))
        elif t["kind"] == "absent-by-policy":
            findings.extend(check_absent_by_policy(t, pkg_root))
        else:
            findings.append(Finding(t["id"], t.get("kind", "?"), "error", "未知 kind"))

    by_status: dict[str, int] = {}
    for f in findings:
        by_status[f.status] = by_status.get(f.status, 0) + 1

    bundled_bad = [f for f in findings if f.kind == "bundled" and f.status in
                   ("missing", "hash-mismatch", "error", "unverifiable")]
    fetch_bad = [f for f in findings if f.kind == "fetchable" and f.status in
                 ("hash-mismatch", "http-error", "network-error", "bad-content",
                  "truncated", "empty", "too-large", "error")]
    policy_bad = [f for f in findings if f.kind == "absent-by-policy" and f.status in
                  ("policy-violation", "error")]

    return {
        "schema": SCHEMA,
        "manifest": str(manifest_path),
        "package_root": str(pkg_root),
        "cache_dir": str(cache_dir),
        "mode": "fetch" if do_fetch else "check",
        "counts_by_kind": {k: sum(1 for t in tools if t["kind"] == k) for k in
                           ("bundled", "fetchable", "external", "absent-by-policy")},
        "counts_by_status": by_status,
        "bundled_failures": [f.as_dict() for f in bundled_bad],
        "fetch_failures": [f.as_dict() for f in fetch_bad],
        "policy_failures": [f.as_dict() for f in policy_bad],
        "findings": [f.as_dict() for f in findings],
    }


def main(argv=None) -> int:
    here = Path(__file__).resolve()
    # Two supported layouts, because this script ships inside the archive and is
    # also run from the build tree:
    #   build tree  <root>/work/scripts/fetch_tools.py  -> package root <root>/work
    #   delivered   <root>/scripts/fetch_tools.py       -> package root <root>
    # The old default assumed the build tree unconditionally, so inside a
    # delivered archive it resolved "<archive>/work" and exited 2 -- even though
    # README.md tells the reader to run this script from the package.
    script_dir = here.parent
    if (script_dir.parent / "references" / "tool-manifest.json").is_file():
        default_pkg = script_dir.parent
    elif (script_dir.parent / "work" / "references" / "tool-manifest.json").is_file():
        default_pkg = script_dir.parent / "work"
    else:
        default_pkg = script_dir.parent
    workroot = default_pkg.parent if default_pkg.name == "work" else default_pkg
    ap = argparse.ArgumentParser(description="按 tool-manifest 校验/取回工具包工具依赖")
    g = ap.add_mutually_exclusive_group()
    g.add_argument("--check", action="store_true", help="只检查（默认动作，不下载）")
    g.add_argument("--fetch", action="store_true", help="下载缺失的 fetchable 项到 vendor-cache/")
    ap.add_argument("--manifest", default=None, help=f"清单路径（默认 <工作根>/{DEFAULT_MANIFEST}）")
    ap.add_argument("--root", default=str(workroot), help="工作根（含 work/ 与 vendor-cache/）")
    ap.add_argument("--cache-dir", default=None, help="下载缓存目录（默认 <工作根>/vendor-cache）")
    ap.add_argument("--id", action="append", default=[], help="只处理指定 id（可重复）")
    ap.add_argument("--kind", action="append", default=[],
                    choices=["bundled", "fetchable", "external", "absent-by-policy"],
                    help="只处理指定 kind（可重复）")
    ap.add_argument("--strict", action="store_true",
                    help="fetchable 未缓存也算失败（退出码 1）")
    ap.add_argument("--json", action="store_true", help="输出 JSON")
    args = ap.parse_args(list(sys.argv[1:] if argv is None else argv))

    root = Path(args.root).resolve()
    pkg = root / "work"
    if not (pkg / "references" / "tool-manifest.json").is_file():
        pkg = root
    if not (pkg / "references" / "tool-manifest.json").is_file():
        print(f"[fetch_tools] 包根不存在（未找到 references/tool-manifest.json）: {pkg}",
              file=sys.stderr)
        return 2
    manifest_path = Path(args.manifest).resolve() if args.manifest else (pkg / "references" / "tool-manifest.json")
    if not manifest_path.is_file():
        print(f"[fetch_tools] 清单不存在: {manifest_path}", file=sys.stderr)
        return 2
    # A delivered archive has no sibling vendor-cache/; keep the cache next to the
    # package root in that case so --fetch still has a writable, in-tree location.
    cache_dir = Path(args.cache_dir).resolve() if args.cache_dir else (root / "vendor-cache")

    do_fetch = bool(args.fetch)
    report = run(manifest_path, pkg, cache_dir, set(args.id), set(args.kind), do_fetch, root)

    if args.json:
        print(json.dumps(report, ensure_ascii=False, indent=2))
    else:
        print(f"=== fetch_tools ({report['mode']}) ===")
        print(f"manifest    = {report['manifest']}")
        print(f"package_root= {report['package_root']}")
        print(f"cache_dir   = {report['cache_dir']}")
        print(f"kinds       = {report['counts_by_kind']}")
        print(f"status      = {report['counts_by_status']}")

        def dump(kind, statuses, title):
            rows = [f for f in report["findings"] if f["kind"] == kind and f["status"] in statuses]
            if not rows:
                return
            print(f"\n--- {title} ---")
            for f in rows:
                print(f"  [{f['status']:>18}] {f['id']:<26} {f['detail']}")
                for key, label in (("acquire", "ACQUIRE"), ("install_command", "INSTALL"),
                                   ("download_url", "URL"), ("acquisition", "ACQUIRE"),
                                   ("upstream", "UPSTREAM"),
                                   ("expected_sha256", "EXPECTED"), ("actual_sha256", "ACTUAL")):
                    if f.get(key):
                        print(f"      {label:<9}: {f[key]}")

        dump("bundled", {"ok", "present-unverified"}, "bundled 校验通过")
        dump("bundled", {"missing", "hash-mismatch", "error", "unverifiable"}, "bundled 失败（硬缺口）")
        dump("fetchable", {"ok", "fetched", "fetched-unverified", "present-unverified"},
             "fetchable 已就位")
        dump("fetchable", {"not-cached"}, "fetchable 未缓存（可 --fetch 取回）")
        dump("fetchable", {"hash-mismatch", "http-error", "network-error", "bad-content",
                           "truncated", "empty", "too-large", "error"},
             "fetchable 失败（已显式报错，未静默继续）")
        dump("external", {"present"}, "external 已在本机 PATH")
        dump("external", {"absent", "manual"}, "external 缺失/BYO（按 ACQUIRE 自行获取）")
        dump("absent-by-policy", {"ok"}, "absent-by-policy 阴性断言成立（策略禁止的路径确实不在树里）")
        dump("absent-by-policy", {"policy-violation", "error"},
             "absent-by-policy 违规（策略禁止的路径重新出现在发行树里）")

    if report["fetch_failures"]:
        return 4
    if report["bundled_failures"] or report["policy_failures"]:
        return 1
    if args.strict:
        not_cached = [f for f in report["findings"]
                      if f["kind"] == "fetchable" and f["status"] in ("not-cached",)]
        if not_cached:
            return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
