#!/usr/bin/env python3
"""Detached release signing with Ed25519 (schema npc-release-signature/1).

Uses the mature ``cryptography`` implementation; no home-grown cryptography.

Trust model (must be stated honestly in every report):

*   The private key never leaves the release workspace.  It is never written
    into the ZIP, a report, a log or a normal test fixture.
*   A locally generated key that verifies successfully proves the *package*
    was signed by *that* key.  It does NOT establish the NPC publisher identity
    until the matching public-key fingerprint is pinned through an independent
    channel (release announcement, signed installer, ...).  Until then the
    authenticity layer reports ``missing`` / ``untested`` and the release is a
    candidate, not an authenticated official release.
*   A key shipped inside the archive cannot protect against an attacker who
    replaces both the archive and the key; the pinned trust root must come from
    outside the archive.

Bound fields (all must match or verification fails):
    version, release_id, archive_sha256, manifest_digest, policy_digest,
    parent_release, key_id
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import json
import os
import stat
import sys
from pathlib import Path

SCHEMA_SIG = "npc-release-signature/1"
SCHEMA_TRUST = "npc-trust-root/1"
SIG_REL = "NPC-team-release-statement.json.sig"
STATEMENT_REL = "NPC-team-release-statement.json"
TRUST_REL = "references/trust-root.json"
KEYS_DIR = "keys"

BOUND_FIELDS = (
    "version",
    "release_id",
    "archive_sha256",
    "manifest_digest",
    "policy_digest",
    "parent_release",
    "key_id",
)


def _require_crypto():
    try:
        from cryptography.hazmat.primitives.asymmetric.ed25519 import (  # noqa: PLC0415
            Ed25519PrivateKey,
            Ed25519PublicKey,
        )
        from cryptography.hazmat.primitives import serialization  # noqa: PLC0415
    except ImportError as exc:  # pragma: no cover
        raise SystemExit("cryptography is required for release signing: " + str(exc))
    return Ed25519PrivateKey, Ed25519PublicKey, serialization


def canonical_payload(statement: dict) -> bytes:
    missing = [f for f in BOUND_FIELDS if f not in statement]
    if missing:
        raise ValueError("statement missing bound fields: " + ", ".join(missing))
    core = {f: statement.get(f) for f in BOUND_FIELDS}
    return json.dumps(core, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def key_id_of(public_bytes: bytes) -> str:
    return "ed25519:" + hashlib.sha256(public_bytes).hexdigest()[:32]


def fingerprint_of(public_bytes: bytes) -> str:
    return "sha256:" + hashlib.sha256(public_bytes).hexdigest()


# --------------------------------------------------------------------------- keys

def generate_key(workspace: Path, label: str = "release") -> dict:
    Ed25519PrivateKey, _, serialization = _require_crypto()
    keys = Path(workspace) / KEYS_DIR
    keys.mkdir(parents=True, exist_ok=True)
    os.chmod(keys, stat.S_IRWXU)
    priv_path = keys / f"{label}_ed25519.key"
    pub_path = keys / f"{label}_ed25519.pub"
    if priv_path.exists() or pub_path.exists():
        raise SystemExit("refusing to overwrite existing key material")
    private = Ed25519PrivateKey.generate()
    priv_bytes = private.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    )
    pub_bytes = private.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    priv_path.write_bytes(priv_bytes)
    pub_path.write_bytes(pub_bytes)
    try:
        os.chmod(priv_path, stat.S_IRUSR | stat.S_IWUSR)
    except OSError:
        pass
    raw_pub = private.public_key().public_bytes(
        encoding=serialization.Encoding.Raw, format=serialization.PublicFormat.Raw)
    return {
        "private_key": str(priv_path),
        "public_key": str(pub_path),
        "key_id": key_id_of(raw_pub),
        "fingerprint": fingerprint_of(raw_pub),
        "note": "test/local key. Publisher identity is NOT established until this fingerprint is pinned externally.",
    }


def _load_private(path: Path):
    Ed25519PrivateKey, _, serialization = _require_crypto()
    return serialization.load_pem_private_key(path.read_bytes(), password=None)


def _load_public_raw(path: Path) -> bytes:
    _, _, serialization = _require_crypto()
    pub = serialization.load_pem_public_key(path.read_bytes())
    return pub.public_bytes(encoding=serialization.Encoding.Raw, format=serialization.PublicFormat.Raw)


# --------------------------------------------------------------------------- sign / verify

def sign_statement(statement_path: Path, private_key_path: Path, out_path: Path | None = None) -> dict:
    _, Ed25519PublicKey, serialization = _require_crypto()
    statement = json.loads(Path(statement_path).read_text(encoding="utf-8"))
    payload = canonical_payload(statement)
    private = _load_private(Path(private_key_path))
    signature = private.sign(payload)
    raw_pub = private.public_key().public_bytes(
        encoding=serialization.Encoding.Raw, format=serialization.PublicFormat.Raw)
    doc = {
        "schema": SCHEMA_SIG,
        "key_id": statement.get("key_id") or key_id_of(raw_pub),
        "fingerprint": fingerprint_of(raw_pub),
        "signed_fields": list(BOUND_FIELDS),
        "payload_sha256": "sha256:" + hashlib.sha256(payload).hexdigest(),
        "algorithm": "ed25519",
        "signature_b64": base64.b64encode(signature).decode("ascii"),
    }
    out = Path(out_path) if out_path else Path(str(statement_path) + ".sig")
    out.write_text(json.dumps(doc, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return doc


def load_trust_root(root: Path) -> dict | None:
    path = root / TRUST_REL
    if not path.is_file():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    if data.get("schema") != SCHEMA_TRUST:
        return None
    return data


def verify_release(root: Path) -> dict:
    """Return the authenticity layer.

    status: ok | missing | invalid | mismatch | revoked | untrusted_key
    """
    root = Path(root)
    statement_path = root / STATEMENT_REL
    sig_path = root / SIG_REL
    if not statement_path.is_file():
        return {"status": "missing", "ok": False, "detail": "release statement absent"}
    if not sig_path.is_file():
        return {"status": "missing", "ok": False,
                "detail": "no detached signature present; integrity is unauthenticated"}
    try:
        statement = json.loads(statement_path.read_text(encoding="utf-8"))
        sig = json.loads(sig_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        return {"status": "invalid", "ok": False, "detail": type(exc).__name__}
    if sig.get("schema") != SCHEMA_SIG:
        return {"status": "invalid", "ok": False, "detail": "signature schema"}
    if sig.get("algorithm") != "ed25519":
        return {"status": "invalid", "ok": False, "detail": "unsupported algorithm"}
    try:
        payload = canonical_payload(statement)
    except ValueError as exc:
        return {"status": "invalid", "ok": False, "detail": str(exc)}
    if sig.get("payload_sha256") != "sha256:" + hashlib.sha256(payload).hexdigest():
        return {"status": "invalid", "ok": False, "detail": "signed payload does not match statement"}

    trust = load_trust_root(root)
    if trust is None:
        return {"status": "untrusted_key", "ok": False, "key_id": sig.get("key_id"),
                "detail": "no pinned trust root in this release; a shipped key cannot establish identity "
                          "against an attacker who replaces the whole archive"}

    revoked = set(trust.get("revoked_key_ids") or [])
    if sig.get("key_id") in revoked:
        return {"status": "revoked", "ok": False, "key_id": sig.get("key_id")}

    pinned = {k.get("key_id"): k for k in (trust.get("keys") or []) if isinstance(k, dict)}
    entry = pinned.get(sig.get("key_id"))
    if entry is None:
        return {"status": "untrusted_key", "ok": False, "key_id": sig.get("key_id"),
                "detail": "signature key id is not in the pinned trust root"}
    if entry.get("fingerprint") != sig.get("fingerprint"):
        return {"status": "mismatch", "ok": False, "key_id": sig.get("key_id"),
                "detail": "pinned fingerprint differs from signature fingerprint"}

    pub_path = root / (entry.get("public_key_path") or "")
    if not pub_path.is_file():
        return {"status": "untrusted_key", "ok": False, "detail": "pinned public key file missing"}
    try:
        _, Ed25519PublicKey, _ = _require_crypto()
        raw_pub = _load_public_raw(pub_path)
        if fingerprint_of(raw_pub) != entry.get("fingerprint"):
            return {"status": "mismatch", "ok": False, "detail": "public key file does not match pinned fingerprint"}
        public = Ed25519PublicKey.from_public_bytes(raw_pub)
        public.verify(base64.b64decode(sig["signature_b64"]), payload)
    except Exception as exc:  # noqa: BLE001
        return {"status": "invalid", "ok": False, "detail": "signature verification failed: " + type(exc).__name__}

    trusted = bool(entry.get("trusted"))
    return {
        "status": "ok" if trusted else "untested_key",
        "ok": trusted,
        "key_id": sig.get("key_id"),
        "fingerprint": entry.get("fingerprint"),
        "detail": "signature valid" + ("" if trusted else
                  "; key is pinned but not marked trusted (local/test key only)"),
    }


def write_trust_root(root: Path, public_key_path: Path, trusted: bool, label: str = "local-test") -> Path:
    _, _, _ = _require_crypto()
    root = Path(root).resolve()
    src = Path(public_key_path).resolve()
    raw = _load_public_raw(src)
    # The pinned key must live inside the release so its path is resolvable there.
    try:
        rel_pub = src.relative_to(root)
    except ValueError:
        dest_dir = root / KEYS_DIR
        dest_dir.mkdir(parents=True, exist_ok=True)
        rel_pub = Path(KEYS_DIR) / src.name
        dest = root / rel_pub
        if not dest.exists() or dest.read_bytes() != src.read_bytes():
            dest.write_bytes(src.read_bytes())
    doc = {
        "schema": SCHEMA_TRUST,
        "note": "Pinned release keys. This file must be distributed/confirmed through an independent "
                "channel; a trust root inside the archive alone cannot prove publisher identity.",
        "keys": [{
            "key_id": key_id_of(raw),
            "fingerprint": fingerprint_of(raw),
            "public_key_path": rel_pub.as_posix(),
            "label": label,
            "trusted": trusted,
        }],
        "revoked_key_ids": [],
    }
    path = root / TRUST_REL
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(doc, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return path


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="NPC-team Ed25519 release signing")
    sub = ap.add_subparsers(dest="cmd", required=True)
    g = sub.add_parser("keygen", help="generate a local release key")
    g.add_argument("--workspace", required=True)
    g.add_argument("--label", default="release")
    s = sub.add_parser("sign", help="sign a release statement")
    s.add_argument("--root", required=True)
    s.add_argument("--key", required=True)
    t = sub.add_parser("trust", help="pin a public key into the trust root")
    t.add_argument("--root", required=True)
    t.add_argument("--public-key", required=True)
    t.add_argument("--trusted", action="store_true")
    t.add_argument("--label", default="local-test")
    v = sub.add_parser("verify", help="verify a signed release")
    v.add_argument("--root", required=True)
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args(list(sys.argv[1:] if argv is None else argv))

    if args.cmd == "keygen":
        out = generate_key(Path(args.workspace), args.label)
    elif args.cmd == "sign":
        root = Path(args.root)
        out = sign_statement(root / STATEMENT_REL, Path(args.key))
    elif args.cmd == "trust":
        out = {"trust_root": str(write_trust_root(Path(args.root), Path(args.public_key),
                                                  args.trusted, args.label))}
    else:
        out = verify_release(Path(args.root))
    print(json.dumps(out, ensure_ascii=False, indent=2))
    if args.cmd == "verify":
        return 0 if out.get("ok") else 3
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
