def _sha256_bytes(data: bytes) -> str:
    return "sha256:" + hashlib.sha256(data).hexdigest()


def _read_json(path: Path):
    """返回 (obj, error)；缺失与坏 JSON 必须可区分。"""
    if not path.is_file():
        return None, "missing"
    try:
        raw = path.read_bytes()
    except OSError as exc:
        return None, "unreadable:%s" % type(exc).__name__
    try:
        return json.loads(raw.decode("utf-8")), None
    except (UnicodeDecodeError, ValueError):
        return None, "invalid_json"


def load_registry(path: Path, expect_sha256: str | None = None):
    """读取并校验注册表。返回结构不抛异常，状态显式。"""
    out = {
        "status": "ok",
        "path": str(path),
        "sha256": None,
        "data": None,
        "defects": [],
        "errors": [],
    }
    if not path.is_file():
        out["status"] = "missing"
        out["errors"].append("registry_missing: %s" % path)
        return out
    try:
        raw = path.read_bytes()
    except OSError as exc:
        out["status"] = "unreadable"
        out["errors"].append("registry_unreadable: %s: %s" % (path, exc))
        return out
    out["sha256"] = _sha256_bytes(raw)
    if expect_sha256 and out["sha256"] != expect_sha256:
        out["status"] = "baseline_mismatch"
        out["errors"].append(
            "registry_baseline_mismatch: expected %s got %s" % (expect_sha256, out["sha256"])
        )
        return out
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        out["status"] = "invalid_json"
        out["errors"].append("registry_invalid_json: %s: %s" % (path, type(exc).__name__))
        return out
    if not isinstance(data, dict) or not isinstance(data.get("directions"), list):
        out["status"] = "invalid_schema"
        out["errors"].append("registry_invalid_schema: directions[] required in %s" % path)
        return out
    usable = 0
    for item in data["directions"]:
        if not isinstance(item, dict) or not isinstance(item.get("id"), str) or not item["id"]:
            out["defects"].append({"kind": "direction_without_id", "detail": repr(item)[:120]})
            continue
        did = item["id"]
        triggers = [t for t in (item.get("triggers") or []) if isinstance(t, str) and t.strip()]
        if not triggers:
            out["defects"].append({"kind": "direction_missing_triggers", "direction": did})
        else:
            usable += 1
        skills = item.get("primary_skills")
        if skills is not None and not isinstance(skills, list):
            out["defects"].append({"kind": "primary_skills_not_list", "direction": did})
    if usable == 0:
        out["status"] = "invalid_schema"
        out["errors"].append("registry_no_usable_directions: %s" % path)
        return out
    out["data"] = data
    return out


def _catalog_names(data):
    """从 canonical catalog 抽取身份集合与「外部条目」集合。

    支持 W4 的 `NPC-team-skill-catalog/6`（`by_id` / `entries` / `external_ids` / `skills`）
    与旧的按域索引（`{domain: {"skills": [...]}}`）；alias 也纳入，便于解析历史名。
    """
    names, external = set(), set()

    def add(value):
        if isinstance(value, str) and value.strip() and value.strip() != ".":
            names.add(value.strip())

    if isinstance(data, dict):
        by_id = data.get("by_id")
        if isinstance(by_id, dict):
            for key, meta in by_id.items():
                add(key)
                if isinstance(meta, dict) and meta.get("status") == "external":
                    external.add(key)
        for key in ("entries", "external_ids"):
            pool = data.get(key)
            if not isinstance(pool, list):
                continue
            for item in pool:
                if isinstance(item, dict):
                    stable = item.get("stable_id")
                    add(stable)
                    add(item.get("canonical_name"))
                    for alias in item.get("aliases") or []:
                        add(alias)
                    if key == "external_ids" or item.get("status") == "external":
                        if stable:
                            external.add(stable)
                else:
                    add(item)
        pool = data.get("skills")
        if isinstance(pool, list):
            for item in pool:
                if isinstance(item, dict):
                    for field in ("stable_id", "canonical_name", "name", "id", "skill", "skill_id"):
                        if isinstance(item.get(field), str):
                            add(item[field])
                            break
                else:
                    add(item)
        elif isinstance(pool, dict):
            names.update(k for k in pool if isinstance(k, str))
        for value in data.values():  # 旧索引：{domain: {"skills": [...]}}
            if isinstance(value, dict) and isinstance(value.get("skills"), list):
                for item in value["skills"]:
                    add(item)
    elif isinstance(data, list):
        for item in data:
            add(item)
    drop_suffix = (".py", ".md", ".json", ".ps1", ".sh")
    names = {
        n for n in names
        if not n.endswith(drop_suffix) and "\\" not in n and not n.startswith("./")
    }
    return names, (external & names)


def load_catalog(root: Path):
    """canonical 目录：W4 的 skill-catalog.v6.json → _generated 索引 → skills/ 目录。"""
    info = {"source": None, "path": None, "names": set(), "external": set(),
            "retired": set(), "defect": None}
    for rel in CATALOG_RELS:
        path = root / rel
        if not path.is_file():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            info["defect"] = "catalog_invalid_json:%s" % rel
            continue
        names, external = _catalog_names(data)
        if names:
            # 退役 ID 集随目录一起装载：退役 = 已登记移除、随包无实体，
            # 既不能作为 owner 候选（死指针），也不是未解析缺陷（是知情移除）。
            info.update(source=rel, path=str(path), names=names, external=external,
                        retired=set(data.get("retired_ids") or ()))
            return info
        info["defect"] = "catalog_no_names:%s" % rel
    skills_dir = root / "skills"
    if skills_dir.is_dir():
        names = {
            p.name
            for p in skills_dir.iterdir()
            if p.is_dir() and (p / "SKILL.md").is_file()
        }
        if names:
            info.update(source="skills/", path=str(skills_dir), names=names)
            return info
    return info


