def _is_cjk(text: str) -> bool:
    return bool(_CJK_RE.search(text))


def _specificity(trigger: str) -> float:
    """词的区分度：中文按字数，拉丁短语最高，拉丁单词按长度。"""
    cjk = sum(1 for ch in trigger if _CJK_RE.match(ch))
    if cjk:
        return round(1.0 + 0.15 * min(cjk, 4), 4)
    if re.search(r"[^0-9a-z]", trigger.casefold()):
        return 1.5
    return round(1.0 + 0.08 * min(len(trigger), 8), 4)


def _slug(text: str) -> str:
    return text.strip().casefold()


def _exact_pattern(trigger: str):
    return re.compile(r"(?<![0-9a-z])" + re.escape(_slug(trigger)) + r"(?![0-9a-z])")


def _stem_pattern(trigger: str):
    alt = "|".join(re.escape(s) for s in _LATIN_SUFFIXES)
    return re.compile(
        r"(?<![0-9a-z])" + re.escape(_slug(trigger)) + r"(?:" + alt + r")(?![0-9a-z])"
    )


def match_trigger(task_low: str, trigger: str):
    """返回命中模式 'exact' / 'stem' / None。

    - 含中日韩字符：按子串（中文无词边界，现有关键词基本安全）；
    - 拉丁词/短语：词边界匹配，绝不匹配更长单词的内部（read 不含 ad、script 不含 ip）；
    - 拉丁词干（长度 >= 4）：允许闭集屈折后缀（injection / persistence），权重打折。
    """
    t = _slug(trigger)
    if not t:
        return None
    if _is_cjk(t):
        return "exact" if t in task_low else None
    if _exact_pattern(t).search(task_low):
        return "exact"
    if len(t) >= 4 and t.isalpha() and _stem_pattern(t).search(task_low):
        return "stem"
    return None


def _split_doc_terms(text: str):
    """切分方向文档里的关键词列表。

    只按顿号/逗号/分号与**两侧带空白的斜杠**切分；`EtherNet/IP` 这类紧凑复合词
    保持完整（否则会漏出 `ip` 这种短词污染路由）。
    """
    parts = re.split(r"[、,，;；]|\s+[/／]\s+", text)
    return parts


def _clean_doc_terms(block: str):
    """从方向文档 §1.3 提取关键词：支持 markdown 表格与顿号/逗号列表。"""
    terms = []
    lines = block.splitlines()
    header_kw_col = None
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith("|"):
            cells = [c.strip() for c in stripped.strip("|").split("|")]
            if header_kw_col is None:
                for idx, cell in enumerate(cells):
                    if re.search(r"关键词|keyword|trigger", cell, re.I):
                        header_kw_col = idx
                        break
                if header_kw_col is not None:
                    continue
                if all(re.fullmatch(r"[-: ]*", c) for c in cells):
                    continue
                continue
            if header_kw_col < len(cells):
                terms.extend(re.split(r"[、,，;；]", cells[header_kw_col]))
            continue
        body = re.sub(r"^\s*[-*+]\s*", "", stripped)
        body = re.sub(r"^[^：:]{0,12}[：:]", "", body)
        terms.extend(_split_doc_terms(body))
    cleaned = []
    for term in terms:
        item = term.strip().strip("`*`\"'“”《》()（）[]。.")
        item = re.sub(r"\s+", " ", item)
        if not item or len(item) > MAX_DOC_TERM_LEN:
            continue
        if not _is_cjk(item) and len(item) < MIN_DOC_LATIN_LEN and re.fullmatch(r"[0-9a-z]+", item):
            continue
        if item not in cleaned:
            cleaned.append(item)
    return cleaned


def collect_triggers(registry: dict, root: Path, use_doc: bool = True):
    """返回 (specs, trigger_sources, suggestions)。specs 元素：

    {"direction","trigger","tier"}；同一 (direction, trigger) 只保留最高层。
    """
    specs: dict[tuple, dict] = {}
    suggestions = []
    sources = {"registry": 0, "domain-doc": 0, "bridge": 0}
    direction_ids = set()

    for item in registry["directions"]:
        if not isinstance(item, dict) or not isinstance(item.get("id"), str):
            continue
        did = item["id"]
        direction_ids.add(did)
        for trigger in item.get("triggers") or []:
            if isinstance(trigger, str) and trigger.strip():
                specs[(did, _slug(trigger))] = {
                    "direction": did,
                    "trigger": trigger.strip(),
                    "tier": "registry",
                }

    if use_doc:
        for did in sorted(direction_ids):
            doc = root / "references" / "domains" / ("%s.md" % did)
            if not doc.is_file():
                continue
            try:
                text = doc.read_text(encoding="utf-8")
            except OSError:
                continue
            block = DOC_BLOCK_RE.search(text)
            if not block:
                continue
            for term in _clean_doc_terms(block.group(1)):
                key = (did, _slug(term))
                if key not in specs:
                    specs[key] = {"direction": did, "trigger": term, "tier": "domain-doc"}

    for did, terms in BRIDGE_LEXICON.items():
        if did not in direction_ids:
            suggestions.append(
                {
                    "kind": "bridge_dropped",
                    "direction": did,
                    "terms": list(terms),
                    "reason": "direction_not_in_loaded_registry",
                }
            )
            continue
        for term in terms:
            key = (did, _slug(term))
            if key not in specs:
                specs[key] = {"direction": did, "trigger": term, "tier": "bridge"}

    for spec in specs.values():
        sources[spec["tier"]] = sources.get(spec["tier"], 0) + 1
    if sources.get("bridge"):
        suggestions.append(
            {
                "kind": "registry_gap",
                "target": DEFAULT_REGISTRY_REL,
                "add_triggers": {
                    d: list(t)
                    for d, t in BRIDGE_LEXICON.items()
                    if d in direction_ids
                },
                "reason": "canonical 源缺少这些目标形态词；补齐后可删除 scripts/route.py 的 BRIDGE_LEXICON",
            }
        )
    for defect in registry.get("_defects", []):
        suggestions.append({"kind": "registry_defect", **defect})
    return specs, sources, suggestions


def score_task(task_low: str, specs: dict):
    """返回 {direction: {"score","matches":[{"trigger","tier","mode","weight"}]}}。"""
    per_direction: dict[str, dict] = {}
    for spec in specs.values():
        mode = match_trigger(task_low, spec["trigger"])
        if not mode:
            continue
        weight = TIER_WEIGHT.get(spec["tier"], 0.5) * _specificity(spec["trigger"])
        if mode == "stem":
            weight *= 0.6
        row = per_direction.setdefault(spec["direction"], {"score": 0.0, "matches": []})
        row["score"] = round(row["score"] + weight, 4)
        row["matches"].append(
            {
                "trigger": spec["trigger"],
                "tier": spec["tier"],
                "mode": mode,
                "weight": round(weight, 4),
            }
        )
    for row in per_direction.values():
        row["matches"].sort(key=lambda m: (-m["weight"], m["trigger"]))
    return per_direction


def decide(per_direction: dict, registry: dict):
    """判定 resolved / ambiguous / undetermined，并给出候选顺序与理由。"""
    handoff = {}
    for item in registry["directions"]:
        if isinstance(item, dict) and isinstance(item.get("id"), str):
            handoff[item["id"]] = [h for h in (item.get("handoff") or []) if isinstance(h, str)]
    ranked = sorted(per_direction.items(), key=lambda kv: (-kv[1]["score"], kv[0]))
    decision = {
        "routing_status": "undetermined",
        "direction": None,
        "reason": "no_trigger_matched",
        "candidates": [],
        "handoff_order": [],
    }
    if not ranked:
        return decision
    candidates = [
        {"direction": did, "score": row["score"], "matched": row["matches"]}
        for did, row in ranked
    ]
    decision["candidates"] = candidates
    top = candidates[0]
    if top["score"] <= 0:
        return decision
    if len(candidates) > 1:
        second = candidates[1]
        if second["score"] > 0 and top["score"] < second["score"] * RESOLVE_MARGIN:
            decision.update(
                routing_status="ambiguous",
                direction=None,
                reason="top_two_within_margin",
                margin=RESOLVE_MARGIN,
            )
            if second["direction"] in handoff.get(top["direction"], []):
                decision["handoff_order"] = [top["direction"], second["direction"]]
            elif top["direction"] in handoff.get(second["direction"], []):
                decision["handoff_order"] = [second["direction"], top["direction"]]
            return decision
    decision.update(
        routing_status="resolved",
        direction=top["direction"],
        reason="top_score_dominant",
        runner_up=candidates[1]["direction"] if len(candidates) > 1 else None,
        runner_up_score=candidates[1]["score"] if len(candidates) > 1 else 0.0,
    )
    if len(candidates) > 1 and candidates[1]["direction"] in handoff.get(top["direction"], []):
        decision["handoff_order"] = [top["direction"], candidates[1]["direction"]]
    return decision


def resolve_owners(owners, catalog, session_skills, skills_dir: Path):
    """返回 (resolved, defects)。

    分档语义（与 tests/route A6/A18 契约一致）：
    * ``shipped_skill_file``        随包 SKILL.md 真实存在 —— 唯一可进入 owner_candidates 的档；
    * ``retired_id``                已登记退役（catalog 的 retired_ids 字段），
      知情移除：不进候选（随包无实体，返回它等于交出死指针），也不算缺陷；
    * ``catalog_external_declared`` / ``catalog_only`` / ``session_declared_external``
      仅作解析说明（owner_resolution），不进候选；
    * 其余（完全不可解析）→ ``owner_defects``，不生成伪可调用 ID。
    """
    resolved, defects = [], []
    session = {s.strip() for s in session_skills if s and s.strip()}
    retired = catalog.get("retired", ()) or ()
    for owner in owners:
        if not isinstance(owner, str) or not owner.strip():
            continue
        name = owner.strip()
        if (skills_dir / name / "SKILL.md").is_file():
            resolved.append({"name": name, "resolution": "shipped_skill_file"})
        elif name in retired:
            resolved.append({"name": name, "resolution": "retired_id", "retired": True})
        elif name in catalog.get("external", ()):
            resolved.append(
                {"name": name, "resolution": "catalog_external_declared", "catalog": catalog["source"]}
            )
        elif catalog["names"] and name in catalog["names"]:
            resolved.append(
                {"name": name, "resolution": "catalog_only", "catalog": catalog["source"]}
            )
        elif name in session:
            resolved.append({"name": name, "resolution": "session_declared_external"})
        else:
            defects.append(
                {
                    "owner": name,
                    "reason": "unresolved",
                    "checked": ["skills/<name>/SKILL.md", catalog["source"] or "catalog:none"],
                }
            )
    return resolved, defects


