# 授权与通道
# --------------------------------------------------------------------------
def load_authorization(scope_record: Path | None, authorized_flag: bool, authority_ref: str | None):
    """授权状态。target 通道的前置：必须已记录 scope + effect。"""
    auth = {
        "recorded": False,
        "authorized": False,
        "authority_ref": None,
        "source": "none",
        "targets": [],
        "errors": [],
    }
    if scope_record is not None:
        data, err = _read_json(scope_record)
        if err:
            auth["errors"].append("scope_record_%s: %s" % (err, scope_record))
            auth["source"] = "scope_record"
            return auth
        auth["source"] = "scope_record"
        if isinstance(data, dict):
            auth["authorized"] = bool(data.get("authorized"))
            ref = data.get("authority_ref") or data.get("authorization_ref")
            auth["authority_ref"] = ref if isinstance(ref, str) and ref.strip() else None
            targets = data.get("targets")
            if isinstance(targets, list):
                auth["targets"] = [t for t in targets if isinstance(t, str)]
        else:
            auth["errors"].append("scope_record_not_object: %s" % scope_record)
            return auth
    elif authorized_flag:
        auth["source"] = "cli_flag"
        auth["authorized"] = True
        auth["authority_ref"] = authority_ref
    if authorized_flag and authority_ref:
        auth["authorized"] = True
        auth["authority_ref"] = authority_ref
    if auth["authorized"] and not auth["authority_ref"]:
        auth["authorized"] = False
        auth["errors"].append("authority_ref_missing: authorized=true 但没有授权引用，按未授权处理")
    auth["recorded"] = bool(auth["authorized"] and auth["authority_ref"])
    return auth


def _has_any(task_low: str, forms) -> list:
    return [f for f in forms if _slug(f) in task_low]


def decide_channel(direction, per_direction, task_low, auth, override=None):
    """按 (动作, 目标形态, 授权状态) 选通道。返回 dict（不含业务结论）。"""
    decided = {
        "channel_key": None,
        "channel": None,
        "execution_lane": None,
        "channel_status": "not_determined",
        "channel_basis": {"evidence": [], "rule": None},
        "required_authorization": [],
        "alternate_channels": [],
    }
    basis = decided["channel_basis"]

    if override:
        basis.update(rule="user_override", evidence=["--channel %s" % override])
        decided["channel_key"] = override
    else:
        doc_evidence = []
        if direction == "09-general":
            doc_evidence.append("direction=09-general")
        for did, row in per_direction.items():
            if did != "09-general":
                continue
            doc_evidence.extend("09 trigger: %s" % m["trigger"] for m in row["matches"][:3])
        local_evidence = _has_any(task_low, LOCAL_EXEC_FORMS)
        interactive = _has_any(task_low, INTERACTIVE_FORMS)
        if doc_evidence:
            decided["channel_key"] = "static"
            basis.update(rule="document_action", evidence=doc_evidence[:4])
        elif interactive and direction in ("02-mobile", "06-protocol-capture", None):
            decided["channel_key"] = "browser"
            basis.update(rule="interactive_runtime", evidence=interactive[:4])
        elif local_evidence:
            decided["channel_key"] = "local"
            basis.update(rule="local_execution", evidence=local_evidence[:4])
        elif direction == "03-pentest" or (
            direction is None and "03-pentest" in per_direction
        ):
            decided["channel_key"] = "target"
            basis.update(rule="target_contact", evidence=["direction=03-pentest"])
        elif direction in DEFAULT_CHANNEL:
            decided["channel_key"] = DEFAULT_CHANNEL[direction]
            basis.update(rule="direction_default", evidence=["direction=%s" % direction])

    key = decided["channel_key"]
    if key is None:
        decided["channel_status"] = "not_determined"
        return decided
    decided["channel"] = CHANNELS[key]
    decided["execution_lane"] = LANE_ALIAS.get(key)

    mutate = _has_any(task_low, MUTATE_FORMS)
    if key == "target":
        decided["required_authorization"] = [
            "scope_record{authorized:true, authority_ref}",
            "effect_grant:mutate-target" if mutate else "effect_grant:read",
        ]
        if auth["recorded"]:
            decided["channel_status"] = "ready"
        else:
            decided["channel_status"] = "requires_authorization"
            decided["channel_key"] = None
            decided["channel"] = None
            decided["execution_lane"] = None
            basis["blocked_channel"] = "target"
            basis["rule"] = (basis.get("rule") or "") + "+auth_gate"
    else:
        if override and key == "browser":
            decided["channel_status"] = "ready_user_override"
        else:
            decided["channel_status"] = "ready"
        if auth["recorded"]:
            basis["authorization"] = "recorded(no target contact required)"
    if key != "target":
        decided["alternate_channels"] = [
            k for k in ("browser", "local", "target") if k != key
        ][:2]
    return decided


# --------------------------------------------------------------------------
# 主流程
# --------------------------------------------------------------------------
def build_parser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(description="NPC-team v6 direction router")
    ap.add_argument("--task", required=True, help="任务文本")
    ap.add_argument("--json", action="store_true")
    ap.add_argument(
        "--registry",
        help="注册表**文件路径**（默认 <root>/%s）；缺失/损坏显式 degraded，不回落默认文件"
        % DEFAULT_REGISTRY_REL,
    )
    ap.add_argument("--root", help="包根（默认脚本所在包根）；文档与 skills/ 相对它解析")
    ap.add_argument("--catalog", help="canonical 目录文件（默认自动发现）")
    ap.add_argument("--session-skills", default="", help="本会话已确认可用的外部 skill 名，逗号分隔")
    ap.add_argument("--scope-record", help="授权记录 JSON：{authorized, authority_ref, targets}")
    ap.add_argument("--authorized", action="store_true", help="授权已在别处记录（需配 --authority-ref）")
    ap.add_argument("--authority-ref", help="授权引用（PH:authorization-record / SRC 编号等）")
    ap.add_argument("--effect-class", choices=["read", "mutate-target", "mutate-local", "destroy"])
    ap.add_argument("--channel", choices=sorted(CHANNELS), help="显式覆盖通道（记录为 user_override）")
    ap.add_argument("--confirmed-direction", help="用户/宿主已确认的方向 ID（只有它才让 confidence=observed）")
    ap.add_argument("--no-doc-triggers", action="store_true", help="不使用方向文档 §1.3 关键词层")
    ap.add_argument("--expect-registry-sha256", help="可选 trusted baseline：注册表字节摘要必须匹配")
    ap.add_argument("--max-owners", type=int, default=8)
    ap.add_argument("--exit-zero", action="store_true", help="无视状态一律返回 0（旧调用方兼容）")
    return ap


def main(argv=None) -> int:
    args = build_parser().parse_args(list(sys.argv[1:] if argv is None else argv))

    root = Path(args.root).resolve() if args.root else Path(__file__).resolve().parents[1]
    registry_path = Path(args.registry).expanduser() if args.registry else root / DEFAULT_REGISTRY_REL
    registry_path = registry_path if registry_path.is_absolute() else (Path.cwd() / registry_path)
    registry_path = registry_path.resolve()

    reg = load_registry(registry_path, args.expect_registry_sha256)
    catalog_path = Path(args.catalog).resolve() if args.catalog else None
    catalog = load_catalog(root)
    if catalog_path is not None:
        data, err = _read_json(catalog_path)
        if err:
            catalog = dict(catalog, defect="explicit_catalog_%s" % err)
        else:
            names = set()
            if isinstance(data, dict):
                pool = data.get("skills")
                if isinstance(pool, list):
                    for item in pool:
                        if isinstance(item, str):
                            names.add(item)
                        elif isinstance(item, dict):
                            for key in ("name", "id", "skill", "skill_id"):
                                if isinstance(item.get(key), str):
                                    names.add(item[key])
                                    break
                elif isinstance(pool, dict):
                    names.update(k for k in pool if isinstance(k, str))
            elif isinstance(data, list):
                names.update(s for s in data if isinstance(s, str))
            catalog = {"source": str(catalog_path), "path": str(catalog_path), "names": names, "defect": None}

    auth = load_authorization(
        Path(args.scope_record).resolve() if args.scope_record else None,
        args.authorized,
        args.authority_ref,
    )

    errors = list(reg["errors"])
    limitations = []
    task_low = args.task.casefold()
    skills_dir = root / "skills"
    registry_ok = reg["status"] == "ok"

    specs, trigger_sources, suggestions = ({}, {"registry": 0, "domain-doc": 0, "bridge": 0}, [])
    if registry_ok:
        reg["data"]["_defects"] = reg["defects"]
        specs, trigger_sources, suggestions = collect_triggers(
            reg["data"], root, use_doc=not args.no_doc_triggers
        )
        per_direction = score_task(task_low, specs)
        decision = decide(per_direction, reg["data"])
    else:
        per_direction = {}
        decision = {
            "routing_status": "degraded",
            "direction": None,
            "reason": "registry_%s" % reg["status"],
            "candidates": [],
            "handoff_order": [],
        }
        errors.append(
            "registry_unusable(%s): 需要 <root>/%s 或显式 --registry <file>；"
            "本脚本不再持有备用方向表，不做无源判定。" % (reg["status"], DEFAULT_REGISTRY_REL)
        )

    direction = decision["direction"]
    if args.confirmed_direction:
        known = {
            item.get("id")
            for item in (reg["data"] or {}).get("directions", [])
            if isinstance(item, dict)
        }
        if args.confirmed_direction not in known:
            errors.append("confirmed_direction_unknown: %s" % args.confirmed_direction)
        else:
            direction = args.confirmed_direction
            decision.update(
                routing_status="resolved",
                direction=direction,
                reason="user_confirmed",
            )

    owners_raw, owner_defects, resolved = ([], [], [])
    if direction and registry_ok:
        for item in reg["data"]["directions"]:
            if isinstance(item, dict) and item.get("id") == direction:
                owners_raw = [s for s in (item.get("primary_skills") or []) if isinstance(s, str)]
                break
        resolved, owner_defects = resolve_owners(
            owners_raw, catalog, args.session_skills.split(","), skills_dir
        )
        if owner_defects:
            limitations.append(
                "owner_defects=%d：注册表里的这些 owner 解析不到随包技能，已剔除（不返回伪 ID）"
                % len(owner_defects)
            )
            suggestions.append(
                {
                    "kind": "registry_defect",
                    "target": "references/routing-registry.json",
                    "direction": direction,
                    "unresolved_owners": [d["owner"] for d in owner_defects],
                    "reason": "primary_skills 必须解析到 skills/<name>/SKILL.md 或 catalog 条目",
                }
            )
        if catalog["source"] is None:
            limitations.append("catalog 不可用：owner 只能按 skills/ 目录名解析，未经索引交叉验证")
        elif any(o["resolution"] == "catalog_only" for o in resolved):
            limitations.append("部分 owner 只在 catalog 索引里存在，无随包 SKILL.md（catalog_only）")
        if any(o["resolution"] == "catalog_external_declared" for o in resolved):
            limitations.append(
                "部分 owner 是 catalog 登记的外部条目（host 提供）：可用性以当前会话工具列表为准，本脚本不认证"
            )
        if any(o["resolution"] == "session_declared_external" for o in resolved):
            limitations.append(
                "部分 owner 是会话声明的外部 skill：可用性以当前会话工具列表为准，本脚本不认证"
            )
    elif direction and not registry_ok:
        limitations.append("注册表不可用，方向为 --confirmed-direction 提供，未做注册表校验")

    channel = decide_channel(direction, per_direction, task_low, auth, args.channel)
    for err in auth["errors"]:
        errors.append(err)
    if channel["channel_status"] == "requires_authorization":
        limitations.append(
            "target 通道需要已记录 scope+effect 授权（--scope-record 或 --authorized+--authority-ref）；"
            "缺授权时本脚本只给出方向与 owner，不派发任何动作（越界零动作）"
        )
    if not registry_ok:
        limitations.append(
            "degraded：注册表 %s（%s）；方向/owner 未判定，仅给出修复路径" % (reg["status"], reg["path"])
        )
    if decision["routing_status"] == "undetermined":
