#!/usr/bin/env python3
"""Raw-byte v5 EOF trailer primitives and deterministic integrity helpers.

Trailer placement is checked against physical EOF. Payload bytes are never
normalized. JSON trailers use only JSON whitespace (LF, SP, HT), preserving
json.loads compatibility; other text uses a format-specific trailing comment.
The module does not rebaseline semantic content and never treats a hash as a
publisher identity signature.
"""
from __future__ import annotations

import sys as _sys
if hasattr(_sys.stdout, "reconfigure"):
    _sys.stdout.reconfigure(encoding="utf-8", errors="replace")


import base64
import binascii
import hashlib
import math
import json
import struct
import unicodedata
import zipfile
from pathlib import Path, PurePosixPath
from typing import Any

MAGIC = b"V03EOF5\x00"
END_MAGIC = b"\x00V03END5"
# 该字面量刻意拆开拼接。本文件自身也在 v5 完整性扫描范围内，若源码里出现完整的 marker 文本，
# 这一行会被"按行找 marker"的逻辑当成物理帧剥掉（历史事故：按行剥帧删掉了本行的定义 ->
# 模块级 NameError -> verify_all 全线崩溃；复盘见 reports/remediation/R9-marker-strip.md）。
# 拼接后运行时取值与未拆分的原字面量逐字节相同，但源码层面不自指，对 marker 扫描器免疫。
B64_MARK = b"V03EOF5" + b"-B64:"
VERSION = 5
KIND_TEXT = 1
KIND_JSON = 2
MAX_FRAME = 2 * 1024 * 1024
OWNER = "QQ1027369180"
SCHEMA = "NPC-team-watermark/5"
RAW_DATA_PATHS = {'skills/NPC-GEN-Umbra-0546/tools/die/info/html/Intel IPP.html'}
TEXT_SUFFIXES = {".md", ".py", ".json", ".yaml", ".yml", ".txt", ".csv", ".ps1", ".sh", ".js", ".ts", ".mjs", ".html", ".xml"}
COMMENT = {
    ".py": (b"# ", b""), ".ps1": (b"# ", b""), ".sh": (b"# ", b""),
    ".yaml": (b"# ", b""), ".yml": (b"# ", b""), ".txt": (b"# ", b""),
    ".csv": (b"# ", b""), ".js": (b"// ", b""), ".ts": (b"// ", b""),
    ".mjs": (b"// ", b""), ".md": (b"<!-- ", b" -->"),
    ".html": (b"<!-- ", b" -->"), ".xml": (b"<!-- ", b" -->"),
}


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def _reject_duplicate_pairs(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError("duplicate_json_key:" + key)
        obj[key] = value
    return obj


def _finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError("nonfinite_float:" + value)
    return result


def strict_json_loads(data: bytes) -> Any:
    return json.loads(data.decode("utf-8-sig"), object_pairs_hook=_reject_duplicate_pairs,
                      parse_float=_finite_float,
                      parse_constant=lambda value: (_ for _ in ()).throw(ValueError("invalid_constant:" + value)))


def _logical_frame(body: bytes, kind: int) -> bytes:
    payload = canonical_json({
        "schema": SCHEMA,
        "owner": OWNER,
        "kind": "json" if kind == KIND_JSON else "text",
        "body_len": len(body),
        "body_sha256": "sha256:" + sha256(body),
    })
    # Header: magic, version, kind, flags, body length, body digest, payload length.
    header = MAGIC + bytes((VERSION, kind)) + struct.pack(">H", 0) + struct.pack(">Q", len(body)) + bytes.fromhex(sha256(body)) + struct.pack(">I", len(payload)) + payload
    crc = struct.pack(">I", binascii.crc32(header) & 0xffffffff)
    frame_len = len(header) + len(crc) + len(END_MAGIC) + 8
    frame = header + crc + END_MAGIC + struct.pack(">Q", frame_len)
    if frame_len > MAX_FRAME:
        raise ValueError("trailer_too_large")
    return frame


def _parse_frame(frame: bytes) -> dict:
    min_len = len(MAGIC) + 1 + 1 + 2 + 8 + 32 + 4 + 4 + len(END_MAGIC) + 8
    if len(frame) > MAX_FRAME:
        raise ValueError("trailer_too_large")
    if len(frame) < min_len:
        raise ValueError("trailer_truncated")
    if not frame.startswith(MAGIC):
        raise ValueError("trailer_bad_magic")
    if frame[-16:-8] != END_MAGIC:
        raise ValueError("trailer_bad_end_magic")
    declared_frame_len = struct.unpack(">Q", frame[-8:])[0]
    if declared_frame_len != len(frame):
        raise ValueError("trailer_length_mismatch")
    version, kind = frame[len(MAGIC)], frame[len(MAGIC) + 1]
    if version != VERSION:
        raise ValueError("trailer_bad_version")
    if kind not in {KIND_TEXT, KIND_JSON}:
        raise ValueError("trailer_bad_kind")
    pos = len(MAGIC) + 1 + 1
    flags = struct.unpack(">H", frame[pos:pos + 2])[0]
    if flags != 0:
        raise ValueError("trailer_unknown_flags")
    pos += 2
    body_len = struct.unpack(">Q", frame[pos:pos + 8])[0]
    pos += 8
    body_digest = frame[pos:pos + 32]
    pos += 32
    payload_len = struct.unpack(">I", frame[pos:pos + 4])[0]
    pos += 4
    payload_end = pos + payload_len
    crc_end = payload_end + 4
    if crc_end + len(END_MAGIC) + 8 != len(frame):
        raise ValueError("trailer_length_mismatch")
    payload_bytes = frame[pos:payload_end]
    stored_crc = struct.unpack(">I", frame[payload_end:crc_end])[0]
    if stored_crc != (binascii.crc32(frame[:payload_end]) & 0xffffffff):
        raise ValueError("trailer_crc_mismatch")
    try:
        payload = strict_json_loads(payload_bytes)
    except (ValueError, UnicodeDecodeError) as exc:
        raise ValueError("trailer_payload_invalid") from exc
    if not isinstance(payload, dict) or canonical_json(payload) != payload_bytes:
        raise ValueError("trailer_payload_noncanonical")
    if payload.get("schema") != SCHEMA or payload.get("owner") != OWNER:
        raise ValueError("trailer_payload_identity_mismatch")
    if payload.get("kind") != ("json" if kind == KIND_JSON else "text"):
        raise ValueError("trailer_payload_kind_mismatch")
    if payload.get("body_len") != body_len or payload.get("body_sha256") != "sha256:" + body_digest.hex():
        raise ValueError("trailer_header_payload_mismatch")
    return {"kind": kind, "body_len": body_len, "body_sha256": body_digest.hex(), "payload": payload,
            "frame_sha256": sha256(frame), "frame_len": len(frame)}


def _encode_whitespace(frame: bytes) -> bytes:
    # Each logical byte is emitted MSB first; SP=0 and TAB=1.
    out = bytearray()
    for byte in frame:
        for shift in range(7, -1, -1):
            out.append(9 if ((byte >> shift) & 1) else 32)
    return bytes(out)


def _decode_whitespace(encoded: bytes) -> bytes:
    if len(encoded) % 8 or any(byte not in (9, 32) for byte in encoded):
        raise ValueError("trailer_whitespace_encoding_invalid")
    logical = bytearray()
    for offset in range(0, len(encoded), 8):
        value = 0
        for bit in encoded[offset:offset + 8]:
            value = (value << 1) | (1 if bit == 9 else 0)
        logical.append(value)
    return bytes(logical)


def _json_physical_frame(data: bytes) -> tuple[int, bytes, dict]:
    # Trailer physical form is LF + whitespace(frame) + LF. Footer gives the
    # logical frame byte count, so no newline/body normalization is necessary.
    if not data.endswith(b"\n"):
        raise ValueError("trailer_missing")
    end_line = len(data) - 1
    start_line = data.rfind(b"\n", 0, end_line)
    if start_line < 0:
        raise ValueError("trailer_missing")
    encoded = data[start_line + 1:end_line]
    # A normal JSON body often ends in LF/CRLF. An empty, non-whitespace, or
    # non-byte-aligned final line is simply an unstamped body; only a line that
    # decodes to the v5 magic is treated as a malformed v5 frame.
    if not encoded or any(byte not in (9, 32) for byte in encoded) or len(encoded) % 8:
        raise ValueError("trailer_missing")
    logical = _decode_whitespace(encoded)
    if not logical.startswith(MAGIC):
        raise ValueError("trailer_missing")
    parsed = _parse_frame(logical)
    if parsed["kind"] != KIND_JSON:
        raise ValueError("trailer_kind_mismatch")
    start = start_line
    if start != parsed["body_len"]:
        raise ValueError("trailer_body_length_mismatch")
    body = data[:start]
    if sha256(body) != parsed["body_sha256"]:
        raise ValueError("trailer_body_hash_mismatch")
    return start, logical, parsed


def _text_physical_frame(data: bytes, path: Path) -> tuple[int, bytes, dict]:
    if not data.endswith(b"\n"):
        raise ValueError("trailer_missing")
    prefix, suffix = COMMENT.get(path.suffix.lower(), (b"# ", b""))
    marker = prefix + B64_MARK
    marker_pos = data.rfind(marker)
    if marker_pos < 0:
        raise ValueError("trailer_missing")
    # A marker without a complete terminal line is corruption, not an
    # unstamped body. This distinguishes truncation from a clean body.
    line_end = len(data) - 1
    line = data[marker_pos:line_end]
    # CRLF 行尾：末行是 ``...APs=\r\n``，上面的 line 会带上尾随 ``\r``。
    # 把它留在 base64 里会让 validate=True 直接报 trailer_base64_invalid，
    # 于是「以 CRLF 保存过的文件」被误判成篡改（Windows 上任何一次
    # CRLF 往返都会命中）。剥掉行尾的 CR 再解码；LF 文件不受影响。
    if line.endswith(b"\r"):
        line = line[:-1]
    if not line.startswith(marker) or (suffix and not line.endswith(suffix)):
        raise ValueError("trailer_missing")
    b64_end = len(line) - len(suffix) if suffix else len(line)
    try:
        frame = base64.b64decode(line[len(marker):b64_end], validate=True)
    except (ValueError, binascii.Error) as exc:
        raise ValueError("trailer_base64_invalid") from exc
    parsed = _parse_frame(frame)
    if parsed["kind"] != KIND_TEXT:
        raise ValueError("trailer_kind_mismatch")
    body_len = parsed["body_len"]
    if body_len > marker_pos:
        raise ValueError("trailer_body_length_mismatch")
    body = data[:body_len]
    separator = data[body_len:marker_pos]
    expected_separator = b"" if body.endswith((b"\n", b"\r")) else b"\n"
    if separator != expected_separator:
        raise ValueError("trailer_separator_mismatch")
    if data.count(marker) != 1:
        raise ValueError("trailer_duplicate_or_embedded_marker")
    if sha256(body) != parsed["body_sha256"]:
        raise ValueError("trailer_body_hash_mismatch")
    return body_len, frame, parsed


def split_trailer(data: bytes, path: str | Path) -> tuple[bytes, bytes, dict]:
    path = Path(path)
    if path.suffix.lower() == ".json":
        start, frame, parsed = _json_physical_frame(data)
        body = data[:start]
        trailer = data[start:]
    else:
        start, frame, parsed = _text_physical_frame(data, path)
        body = data[:start]
        trailer = data[start:]
    # Reject duplicate full frames in the payload. For text markers, also
    # reject a second marker line even if the inner frame is damaged.
    if path.suffix.lower() == ".json":
        for line in body.splitlines():
            if line and all(byte in (9, 32) for byte in line) and len(line) % 8 == 0:
                try:
                    inner = _decode_whitespace(line)
                    if inner.startswith(MAGIC):
                        _parse_frame(inner)
                        raise ValueError("trailer_duplicate")
                except ValueError as exc:
                    if str(exc) == "trailer_duplicate":
                        raise
    else:
        prefix, suffix = COMMENT.get(path.suffix.lower(), (b"# ", b""))
        marker = prefix + B64_MARK
        if marker in body:
            raise ValueError("trailer_duplicate_or_embedded_marker")
    return body, trailer, parsed


def append_trailer(data: bytes, path: str | Path) -> bytes:
    path = Path(path)
    try:
        body, trailer, parsed = split_trailer(data, path)
        if body == data[:len(body)]:
            return data  # valid existing v5 trailer: idempotent
    except ValueError as exc:
        if str(exc) not in {"trailer_missing"}:
            raise
    kind = KIND_JSON if path.suffix.lower() == ".json" else KIND_TEXT
    frame = _logical_frame(data, kind)
    if kind == KIND_JSON:
        # The two LFs are trailer transport. The body is byte-for-byte intact.
        return data + b"\n" + _encode_whitespace(frame) + b"\n"
    prefix, suffix = COMMENT.get(path.suffix.lower(), (b"# ", b""))
    separator = b"" if data.endswith((b"\n", b"\r")) else b"\n"
    line = prefix + B64_MARK + base64.b64encode(frame) + suffix + b"\n"
    return data + separator + line


def _has_terminal_marker(data: bytes, path: Path) -> bool:
    """True when the bytes look like a v5 trailer is present but broken.

    Checks the terminal marker for this file class, not a bare substring, so
    source files that merely mention the marker constant are not mislabeled.
    """
    if path.suffix.lower() == ".json":
        for line in data.splitlines():
            if line and len(line) % 8 == 0 and all(c in (9, 32) for c in line):
                try:
                    if _decode_whitespace(line).startswith(MAGIC):
                        return True
                except ValueError:
                    continue
        return False
    prefix, _ = COMMENT.get(path.suffix.lower(), (b"# ", b""))
    return (prefix + B64_MARK) in data


def verify_file(path: str | Path) -> dict:
    path = Path(path)
    data = path.read_bytes()
    result = {"path": str(path), "bytes": len(data), "raw_sha256": sha256(data), "status": "error", "errors": []}
    try:
        body, trailer, meta = split_trailer(data, path)
    except ValueError as exc:
        reason = str(exc)
        if _has_terminal_marker(data, path):
            result.update(status="tampered", errors=[reason])
        else:
            result.update(status="missing", errors=["trailer_missing"])
        return result
    result.update(status="ok", body_bytes=len(body), body_sha256=sha256(body), trailer_sha256=sha256(trailer), meta=meta)
    return result


def _no_frame_paths(root: Path) -> set[str]:
    """按载体策略取"不得带帧"的路径集合（单一事实源在 file_policy）。

    延迟导入：file_policy 与本模块互相引用，模块级导入会成环；且本模块要能在
    file_policy 缺席（例如把 v5_integrity.py 单独拷出去做验签）时照常工作 —— 那时
    退化为"只认本模块内置的固定豁免"，绝不因此崩溃或误报。
    """
    try:
        import importlib.util
        here = Path(__file__).resolve().parent
        spec = importlib.util.spec_from_file_location("_fp_for_v5", here / "file_policy.py")
        if spec is None or spec.loader is None:
