def managed_files(root: str | Path):
    root = Path(root)
    no_frame = _no_frame_paths(root)
    for path in sorted(root.rglob("*")):
        if not path.is_file() or path.is_symlink() or (hasattr(path,"is_junction") and path.is_junction()) or "__pycache__" in path.parts or path.suffix.lower() not in TEXT_SUFFIXES:
            continue
