        if rel in RAW_DATA_PATHS:
            continue
        # 载体策略的单一事实源：逐字节保留类与生成物**按设计不得带帧**，
        # 不能把它们算成 missing（历史上这里漏判，报出 258 条假阳性）。
        if rel in no_frame:
            continue
        # Release metadata is regenerated last and covered by the ZIP chain;
        # it must not reference itself through a body-bound trailer.
        if path.relative_to(root).as_posix() in {"references/integrity-manifest.json", "integrity-manifest.json", "references/semantic-seals.json", "NPC-team-v6-manifest.json"}:
            continue
