def verify_tree(root: str | Path) -> dict:
    root = Path(root)
    items = [verify_file(path) for path in managed_files(root)] if root.is_dir() else []
    links = [str(p) for p in root.rglob("*") if p.is_symlink() or (hasattr(p, "is_junction") and p.is_junction())] if root.is_dir() else []
    return {"schema": SCHEMA, "files": len(items), "ok": bool(items) and not links and all(x["status"] == "ok" for x in items),
            "missing": [x["path"] for x in items if x["status"] == "missing"] + ([str(root)] if not items else []),
