def heal_tree(root: str | Path, trusted_body_hashes: dict[str, str] | None = None) -> dict:
    """Only append a missing trailer when the body matches an external manifest.

    Existing malformed/legacy trailers and unanchored files are never silently
    repaired or re-sealed. The caller must supply trusted_body_hashes.
    """
    root = Path(root)
    trusted_body_hashes = trusted_body_hashes or {}
    repaired, refused = [], []
    for path in managed_files(root):
        check = verify_file(path)
        if check["status"] == "ok":
            continue
        rel = path.relative_to(root).as_posix()
        if check["status"] != "missing":
            refused.append({"path": rel, "reason": check["errors"]})
            continue
        body = path.read_bytes()
        expected = trusted_body_hashes.get(rel)
        if expected is None or expected != "sha256:" + sha256(body):
            refused.append({"path": rel, "reason": ["trusted_baseline_missing_or_mismatch"]})
            continue
        path.write_bytes(append_trailer(body, path))
        repaired.append(rel)
    report = verify_tree(root)
    report.update(repaired=repaired, refused=refused, rebaseline_required=bool(refused), baseline_unchanged=True)
    return report


def validate_archive_paths(names: list[str]) -> None:
    seen = set()
    reserved = {"con", "prn", "aux", "nul"} | {"com%d" % i for i in range(1, 10)} | {"lpt%d" % i for i in range(1, 10)}
