        catalog in ToolDiscovery.ps1 (single source of truth, no duplicated
        install strings);
      * after every attempt the capability is RE-RESOLVED and the observed
        state is reported - this script never prints 'ready' for something it
        could not verify;
      * capabilities without a declared, non-interactive installer are refused
        with a structured error instead of a silent no-op;
      * exit 0 only when every requested capability is available afterwards;
      * -WhatIf / -DryRun performs classification and prints the plan without
        installing anything (used by the W12 tests, which must not touch the
        host).

    -StartServices is accepted and recorded. The current package declares no
    service-start step for any capability, so requesting it is reported as
    'unsupported' rather than being silently ignored.

    Pure ASCII on purpose: Windows PowerShell 5.1 reads BOM-less .ps1 files with
    the ANSI code page.
#>
[CmdletBinding(SupportsShouldProcess = $true)]
param(
    [Parameter(Mandatory = $true)]
    [string[]]$Capability,

    [switch]$SkipRefresh,

    [switch]$StartServices,

    [switch]$DryRun,

    [string]$LibraryPath,

    [string]$Requester = 'bootstrap-reverse.ps1'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$OutputEncoding = [System.Text.UTF8Encoding]::new($false)

# ---------------------------------------------------------------------------
# Load the shared library. Resolution is by package marker, never by counting
# '..' segments; the library is tried at the root-relative location first and
# only then next to this file (which keeps a relocated copy working).
# ---------------------------------------------------------------------------

$script:LibraryPath = $null
$candidates = New-Object System.Collections.Generic.List[string]

# A caller that already resolved the shared library passes it in explicitly;
# this is the relocation-proof path and is tried first.
if (-not [string]::IsNullOrWhiteSpace($LibraryPath)) {
    $candidates.Add($LibraryPath)
}

$libDirCandidate = Join-Path $PSScriptRoot 'lib\ToolDiscovery.ps1'
$candidates.Add($libDirCandidate)
$rootCandidate = $null
$probe = $PSScriptRoot
while (-not [string]::IsNullOrWhiteSpace($probe)) {
    if (Test-Path -LiteralPath (Join-Path $probe 'NPC-team-v6-manifest.json') -PathType Leaf) {
        $rootCandidate = $probe
        break
    }
    $parent = Split-Path -Path $probe -Parent
    if ($parent -eq $probe) { break }
    $probe = $parent
}
if (-not [string]::IsNullOrWhiteSpace($rootCandidate)) {
    $candidates.Add((Join-Path $rootCandidate 'skills\scripts\lib\ToolDiscovery.ps1'))
}

foreach ($candidate in $candidates) {
    if (Test-Path -LiteralPath $candidate -PathType Leaf) {
        $script:LibraryPath = $candidate
        break
    }
}

if ($null -eq $script:LibraryPath) {
    $message = @(
        'STRUCTURED_ERROR kind=missing-internal-library',
        ('requester=' + $Requester),
        ('searched=' + ($candidates -join '; ')),
        'expected=skills\scripts\lib\ToolDiscovery.ps1 inside the package root',
        'fetch=re-extract the official NPC-team archive; the shared library must ship with skills\scripts\lib\ToolDiscovery.ps1',
        'next=restore the library, then re-run this bootstrap'
    ) -join [Environment]::NewLine
    [Console]::Error.WriteLine($message)
    exit 4
}

. $script:LibraryPath

# ---------------------------------------------------------------------------
# Install primitives (only called for declared, non-interactive kinds)
# ---------------------------------------------------------------------------

function Invoke-PipInstall {
    <#
    .SYNOPSIS
        'pip install --user <requirement>' for a declared python capability.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$CapabilityName,
        [Parameter(Mandatory = $true)]$Row
    )

    $python = Get-Command python -ErrorAction SilentlyContinue
    if ($null -eq $python) {
        $python = Get-Command py -ErrorAction SilentlyContinue
    }
    if ($null -eq $python) {
        return [pscustomobject]@{ Ok = $false; Detail = 'python interpreter not found on PATH' }
    }

    $requirement = $CapabilityName
    if ($CapabilityName -eq 'frida') {
        $requirement = 'frida-tools'
    }
    if ([string]::IsNullOrWhiteSpace($Row.MinimumVersion) -or $Row.MinimumVersion -eq 'unspecified') {
        $spec = $requirement
    }
    else {
        $spec = $requirement + '>=' + $Row.MinimumVersion
    }

    Write-Host ('INFO: running {0} -m pip install --user {1}' -f $python.Source, $spec)
    & $python.Source -m pip install --user $spec
    $code = $LASTEXITCODE
    return [pscustomobject]@{
        Ok     = ($code -eq 0)
        Detail = ('pip exit code ' + $code + ' for ' + $spec)
    }
}

function Invoke-SdkComponentInstall {
    <#
    .SYNOPSIS
        'sdkmanager <component>' for an Android SDK capability.

    .DESCRIPTION
        sdkmanager needs the build-tools package name, not the tool name. The
        package id is derived from the catalog row's install command so there is
        still exactly one place that declares it.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$CapabilityName,
        [Parameter(Mandatory = $true)]$Row
    )

    $sdkmanager = Get-Command sdkmanager -ErrorAction SilentlyContinue
    if ($null -eq $sdkmanager) {
        $sdkRoot = Join-Path $env:LOCALAPPDATA 'Android\Sdk'
        foreach ($relative in @('cmdline-tools\latest\bin\sdkmanager.bat', 'tools\bin\sdkmanager.bat')) {
            $probe = Join-Path $sdkRoot $relative
            if (Test-Path -LiteralPath $probe -PathType Leaf) {
                $sdkmanager = Get-Item -LiteralPath $probe
                break
            }
        }
    }
    if ($null -eq $sdkmanager) {
        return [pscustomobject]@{ Ok = $false; Detail = 'sdkmanager not found; install Android command-line tools' }
    }

    $packageMatch = [regex]::Match([string]$Row.InstallCommand, '"([^"]+)"')
    if (-not $packageMatch.Success) {
        return [pscustomobject]@{ Ok = $false; Detail = 'no sdkmanager package id declared for ' + $CapabilityName }
    }
    $packageId = $packageMatch.Groups[1].Value

    $sdkmanagerPath = $sdkmanager.Source
    if ([string]::IsNullOrWhiteSpace($sdkmanagerPath)) { $sdkmanagerPath = $sdkmanager.FullName }
    Write-Host ('INFO: running sdkmanager "{0}"' -f $packageId)
    & $sdkmanagerPath $packageId
    $code = $LASTEXITCODE
    return [pscustomobject]@{
        Ok     = ($code -eq 0)
        Detail = ('sdkmanager exit code ' + $code + ' for ' + $packageId)
    }
}


# ---------------------------------------------------------------------------
# Classification
# ---------------------------------------------------------------------------

$catalog = @{}
foreach ($row in (Get-ReverseToolCatalog)) {
    $catalog[$row.Name.ToLowerInvariant()] = $row
}

$requested = New-Object System.Collections.Generic.List[string]
foreach ($item in $Capability) {
    foreach ($piece in ($item -split ',')) {
        $trimmed = $piece.Trim()
        if (-not [string]::IsNullOrWhiteSpace($trimmed)) {
            $requested.Add($trimmed.ToLowerInvariant())
        }
    }
}
if ($requested.Count -eq 0) {
    [Console]::Error.WriteLine('STRUCTURED_ERROR kind=no-capability-requested')
    [Console]::Error.WriteLine('usage=bootstrap-reverse.ps1 -Capability @(''jadx'') [-SkipRefresh] [-DryRun]')
    exit 2
}

$hadFailure = $false
$reports = New-Object System.Collections.Generic.List[string]

foreach ($name in $requested) {
    $spec = Resolve-ReverseToolSpec -Name $name

    if ($spec.Available) {
        $reports.Add(('capability={0} state=already-present command={1} version={2}' -f $name, $spec.Command, $spec.Version))
        continue
    }

    $row = $null
    if ($catalog.ContainsKey($name)) {
        $row = $catalog[$name]
    }
    if ($null -eq $row) {
        $hadFailure = $true
        $reports.Add((Format-MissingDependency -Name $name -Requester $Requester `
            -ExtraHint 'capability is not declared in the tool catalog'))
        continue
    }

    $installKindText = [string]$row.InstallKind
    $installCommandText = [string]$row.InstallCommand

    # Guard: the post-install probe must not mistake another executable for the
    # requested capability, so only declared kinds are accepted.
    $installable = @('pip', 'package-manager', 'sdk-component', 'jdk', 'manual-release')
    $nonInteractive = @('pip', 'sdk-component')

    $preflight = @(
        ('STRUCTURED_INFO kind=bootstrap-plan'),
        ('capability=' + $name),
        ('kind=' + $installKindText),
        ('minimum_version=' + $spec.MinimumVersion),
        ('install=' + $installCommandText),
        ('target=' + $(if ([string]::IsNullOrWhiteSpace($row.InstallTarget)) { 'PATH' } else { $row.InstallTarget })),
        ('mode=' + $(if ($DryRun) { 'dry-run' } else { 'apply' }))
    ) -join [Environment]::NewLine
    Write-Host $preflight

    if ($DryRun) {
        $reports.Add(('capability={0} state=not-installed action=planned install={1}' -f $name, $installCommandText))
        $hadFailure = $true
        continue
    }

    if ($nonInteractive -notcontains $installKindText) {
        # Refuse to invent an install. Report exactly what a human must do.
        $hadFailure = $true
        $hint = 'automatic install is not available for install kind ''' + $installKindText + '''; run the install command above'
        if ($installKindText -eq 'manual-release') {
            $hint = 'vendor release must be unpacked manually into the declared target; this script does not download or unpack vendor archives'
        }
        $reports.Add((Format-MissingDependency -Name $name -Requester $Requester -ExtraHint $hint))
        continue
    }

    if (-not $PSCmdlet.ShouldProcess($name, $installCommandText)) {
        $reports.Add(('capability={0} state=not-installed action=skipped-whatif' -f $name))
        $hadFailure = $true
        continue
    }

    $attempt = $null
    try {
        if ($installKindText -eq 'pip') {
            $attempt = Invoke-PipInstall -CapabilityName $name -Row $row
        }
        elseif ($installKindText -eq 'sdk-component') {
            $attempt = Invoke-SdkComponentInstall -CapabilityName $name -Row $row
        }
        else {
            $attempt = [pscustomobject]@{ Ok = $false; Detail = 'unsupported install kind ' + $installKindText }
        }
    }
    catch {
        $attempt = [pscustomobject]@{ Ok = $false; Detail = $_.Exception.Message }
    }

    # Always re-resolve: the probe, not the installer's exit code, decides.
    $after = Resolve-ReverseToolSpec -Name $name
    if ($after.Available) {
        $reports.Add(('capability={0} state=installed command={1} version={2} detail={3}' -f $name, $after.Command, $after.Version, $attempt.Detail))
    }
    else {
        $hadFailure = $true
        $reports.Add((Format-MissingDependency -Name $name -Requester $Requester `
            -ExtraHint ('install attempt failed or was ineffective: ' + $attempt.Detail)))
    }
}

# ---------------------------------------------------------------------------
# Report
# ---------------------------------------------------------------------------

Write-Host '--- bootstrap report ---'
foreach ($line in $reports) {
    Write-Host $line
}

if ($StartServices) {
    Write-Host 'STRUCTURED_ERROR kind=unsupported-option option=-StartServices detail=no capability in this package declares a service start step'
    $hadFailure = $true
}

if ($hadFailure) {
    Write-Host ('SUMMARY requested={0} result=incomplete' -f ($requested -join ','))
    exit 1
}

Write-Host ('SUMMARY requested={0} result=available' -f ($requested -join ','))
exit 0
