﻿#requires -Version 5
<#
.SYNOPSIS
    Shared internal run library for NPC-team reverse/mobile/general skill entries.

.DESCRIPTION
    Single packaged dependency for every entry script that used to dot-source a
    non-existent '..\..\scripts\lib\ToolDiscovery.ps1'. Provides:

      * Resolve-PackageRoot        - locate the package root by marker file, never
                                     by counting '..' levels;
      * Get-InternalLibraryPaths   - resolve internal libraries under the root;
      * Resolve-ReverseToolSpec    - resolve a reverse-engineering CLI tool to a
                                     spec object (Available/Command/PrefixArgs);
      * Get-ReverseToolCatalog     - the machine-readable tool catalog;
      * Format-MissingDependency   - structured 'cannot continue' error text;
      * Assert-ReverseTool         - throw a structured error when unavailable;
      * Resolve-ReverseToolCommand - spec or throw.

    Design rules (F09):
      1. No caller may guess a relative depth. Everything is derived from
         Resolve-PackageRoot, which walks UP from $PSScriptRoot looking for the
         package marker that the packager writes at the package root.
      2. A marker match must also prove it is the real root: either the
         'skills/' directory exists, or the resolver was already inside a
         directory whose name is 'skills'. This stops a relocated script from
         binding to an unrelated parent directory that happens to hold a
         manifest copy.
      3. Every resolved path must stay inside the resolved root. Escaping paths
         are rejected instead of silently loaded.
      4. A missing capability produces a structured error (name + install
         command + minimum version + fetch location). Nothing in this library
         ever reports 'ready' for a missing dependency.

    The library is pure ASCII on purpose: Windows PowerShell 5.1 reads .ps1
    files without a BOM using the ANSI code page, so non-ASCII text would be
    mangled on a non-UTF8 host.
#>

Set-StrictMode -Version Latest

$script:ToolDiscoveryVersion = '1.0.0'
$script:ToolDiscoverySchema = 'npc-tool-discovery/1'

# Suffixes that hold the JSON catalog for one internal library.
$script:ToolCatalogSuffix = '.tools.json'

# Cache for the resolved package root, keyed by the starting path.
$script:PackageRootCache = @{}


# ---------------------------------------------------------------------------
# Section 1: package root resolution
# ---------------------------------------------------------------------------

function Get-InternalLibraryManifestNames {
    <#
    .SYNOPSIS
        Names of the generated package markers that identify a package root.
    #>
    [CmdletBinding()]
    param()

    return @(
        'NPC-team-v6-manifest.json',
        'references/brand-policy.json'
    )
}

function Find-PackageRootCandidate {
    <#
    .SYNOPSIS
        Walk up from StartPath and return the first directory that looks like the
        real package root, or $null.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$StartPath
    )

    $current = $StartPath
    if (-not (Test-Path -LiteralPath $current)) {
        return $null
    }
    $item = Get-Item -LiteralPath $current -ErrorAction SilentlyContinue
    if ($null -eq $item) {
        return $null
    }
    if (-not $item.PSIsContainer) {
        $current = $item.DirectoryName
    }

    $markers = Get-InternalLibraryManifestNames
    $previous = $null

    while (-not [string]::IsNullOrWhiteSpace($current) -and $current -ne $previous) {
        $manifestHit = $null
        foreach ($marker in $markers) {
            $candidate = Join-Path $current $marker
            if (Test-Path -LiteralPath $candidate -PathType Leaf) {
                $manifestHit = $marker
                break
            }
        }
        if ($null -ne $manifestHit) {
            $skillsDir = Join-Path $current 'skills'
            $insideSkills = ((Split-Path -Path $current -Leaf) -eq 'skills')
            # Require independent evidence, not just a stray manifest copy.
            if ((Test-Path -LiteralPath $skillsDir -PathType Container) -or $insideSkills) {
                return $current
            }
        }
        $previous = $current
        $parent = Split-Path -Path $current -Parent
        if ([string]::IsNullOrWhiteSpace($parent)) {
            break
        }
        $current = $parent
    }

    return $null
}

function Resolve-PackageRoot {
    <#
    .SYNOPSIS
        Resolve the NPC-team package root for a script or directory.

    .DESCRIPTION
        Resolution order:
          1. an explicit -StartPath (or the supplied path), walking upward;
          2. $env:NPC_TEAM_ROOT when it names a directory;
          3. a remembered root (see the note below);
          4. the ancestors of the library file itself.

        Note: this function deliberately does NOT persist the answer outside the
        process. The package is documented as portable and relocatable, and a
        global registry key (for example HKCU:\Software\NPC-team) would let a
        relocated copy of a skill bind to a stale root from an older
        installation. A not-found result is returned as $null so callers can
        decide whether to fail (Assert-PackageRoot) or continue.

    .OUTPUTS
        [string] absolute package root, or $null when the marker is absent.
    #>
    [CmdletBinding()]
    param(
        [string]$StartPath
    )

    $candidateStarts = New-Object System.Collections.Generic.List[string]

    if (-not [string]::IsNullOrWhiteSpace($StartPath)) {
        $candidateStarts.Add($StartPath)
    }
    if (-not [string]::IsNullOrWhiteSpace($env:NPC_TEAM_ROOT)) {
        $candidateStarts.Add($env:NPC_TEAM_ROOT)
    }
    if (-not [string]::IsNullOrWhiteSpace($PSScriptRoot)) {
        $candidateStarts.Add($PSScriptRoot)
    }

    foreach ($start in $candidateStarts) {
        $resolved = $null
        try {
            $resolved = (Resolve-Path -LiteralPath $start -ErrorAction Stop).ProviderPath
        }
        catch {
            $resolved = $null
        }
        if ([string]::IsNullOrWhiteSpace($resolved)) {
            continue
        }
        if ($script:PackageRootCache.ContainsKey($resolved)) {
            $cached = $script:PackageRootCache[$resolved]
            if ($null -ne $cached) {
                return $cached
            }
            continue
        }
        $found = Find-PackageRootCandidate -StartPath $resolved
        $script:PackageRootCache[$resolved] = $found
        if ($null -ne $found) {
            return $found
        }
    }

    return $null
}

function Assert-PackageRoot {
    <#
    .SYNOPSIS
        Resolve the package root or stop with a structured, actionable error.
    #>
    [CmdletBinding()]
    param(
        [string]$StartPath,
        [string]$Requester = 'this script'
    )

    $root = Resolve-PackageRoot -StartPath $StartPath
    if ($null -ne $root) {
        return $root
    }

    $manifestName = (Get-InternalLibraryManifestNames)[0]
    $message = @(
        'STRUCTURED_ERROR kind=internal-library-root-not-found',
        ('requester=' + $Requester),
        ('searched_from=' + $(if ([string]::IsNullOrWhiteSpace($StartPath)) { $PSScriptRoot } else { $StartPath })),
        ('marker=' + $manifestName + ' (plus a sibling ''skills'' directory)'),
        'fetch=re-extract the official NPC-team archive so the marker and skills/ are present',
        'fix=set $env:NPC_TEAM_ROOT to the extracted package root and re-run',
        'note=if the package was moved, keep .\skills\ and .\' + $manifestName + ' together in the same directory'
    ) -join [Environment]::NewLine

    throw $message
}

function Test-PathInsideRoot {
    <#
    .SYNOPSIS
        True when CandidatePath is the root itself or lies underneath it.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$Root,
        [Parameter(Mandatory = $true)][string]$CandidatePath
    )

    $rootFull = [System.IO.Path]::GetFullPath($Root).TrimEnd('\', '/')
    $candidateFull = [System.IO.Path]::GetFullPath($CandidatePath)
    if ($candidateFull -eq $rootFull) {
        return $true
    }
    $prefix = $rootFull + [System.IO.Path]::DirectorySeparatorChar
    return $candidateFull.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
}

function Get-InternalLibraryPaths {
    <#
    .SYNOPSIS
        Absolute paths of the internal libraries shipped under <root>\skills\scripts.

    .DESCRIPTION
        Returns an ordered hashtable with ToolDiscovery, BootstrapReverse,
        BootstrapReverseSh, KaliBootstrapSh and LibDir. Missing files are
        reported through 'Missing', never silently substituted with a
        parent-directory or legacy copy.
    #>
    [CmdletBinding()]
    param(
        [string]$Root
    )

    if ([string]::IsNullOrWhiteSpace($Root)) {
        $Root = Resolve-PackageRoot
    }
    if ([string]::IsNullOrWhiteSpace($Root)) {
        $Root = $null
    }

    $result = [ordered]@{
        Root              = $Root
        ScriptsDir        = $null
        LibDir            = $null
        ToolDiscovery     = $null
        BootstrapReverse  = $null
        BootstrapReverseSh = $null
        KaliBootstrapSh   = $null
        Missing           = @()
    }
    if ($null -eq $Root) {
        $result.Missing = @('package-root')
        return [pscustomobject]$result
    }

    $scriptsDir = Join-Path $Root 'skills\scripts'
    $libDir = Join-Path $scriptsDir 'lib'
    $result.ScriptsDir = $scriptsDir
    $result.LibDir = $libDir
    $result.ToolDiscovery = Join-Path $libDir 'ToolDiscovery.ps1'
    $result.BootstrapReverse = Join-Path $scriptsDir 'bootstrap-reverse.ps1'
    $result.BootstrapReverseSh = Join-Path $scriptsDir 'bootstrap-reverse.sh'
    $result.KaliBootstrapSh = Join-Path $Root 'kali\scripts\bootstrap-reverse.sh'

    $missing = New-Object System.Collections.Generic.List[string]
    foreach ($name in @('ToolDiscovery', 'BootstrapReverse')) {
        $probe = $result[$name]
        if (-not (Test-PathInsideRoot -Root $Root -CandidatePath $probe)) {
            $missing.Add($name + ':escapes-package-root')
            continue
        }
        if (-not (Test-Path -LiteralPath $probe -PathType Leaf)) {
            $missing.Add($name)
        }
    }
    $result.Missing = $missing.ToArray()
    return [pscustomobject]$result
}

function Resolve-InternalLibraryPath {
    <#
    .SYNOPSIS
        Resolve one named internal library, or return $null with a reason.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [ValidateSet('ToolDiscovery', 'BootstrapReverse', 'BootstrapReverseSh')]
        [string]$Name,
        [string]$Root
    )

    $paths = Get-InternalLibraryPaths -Root $Root
    $value = $paths.$Name
    if ([string]::IsNullOrWhiteSpace($value) -or -not (Test-Path -LiteralPath $value -PathType Leaf)) {
        return $null
    }
    if ($null -ne $paths.Root -and -not (Test-PathInsideRoot -Root $paths.Root -CandidatePath $value)) {
        return $null
    }
    return $value
}


# ---------------------------------------------------------------------------
# Section 2: tool catalog
# ---------------------------------------------------------------------------

function Get-ReverseToolCatalog {
    <#
    .SYNOPSIS
        The declared reverse-engineering tool catalog.

    .DESCRIPTION
        One row per capability that the packaged entries resolve through
        Resolve-ReverseToolSpec. 'MinimumVersion' documents the version floor
        the skill was tested against; it is reported in errors and never
        invented at runtime - when a probe cannot read a version the spec
        reports 'unknown'.

        Provenance note: this table is authored data. Every row records the
        repository or package it comes from so a reviewer can check it without
        re-deriving it from vendor bytes.
    #>
    [CmdletBinding()]
    param()

    $catalog = @(
        [pscustomobject]@{
            Name           = 'jadx'
