            MinimumVersion = '17'
            VersionCommand = @('-help')
            InstallKind    = 'jdk'
            InstallCommand = 'install a JDK 17+ (winget install EclipseAdoptium.Temurin.17.JDK) and put keytool on PATH'
            InstallTarget  = $null
        },
        [pscustomobject]@{
            Name           = 'frida'
            Kind           = 'python-entrypoint'
            MinimumVersion = '16.0.0'
            VersionCommand = @('--version')
            InstallKind    = 'pip'
            InstallCommand = 'pip install --user frida-tools'
            InstallTarget  = '%APPDATA%\Python'
        }
    )
    return $catalog
}

function Get-PythonScriptCandidates {
    <#
    .SYNOPSIS
        Candidate paths for a pip 'Scripts' entry point (per-user installs).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$ExecutableName
    )

    $candidates = New-Object System.Collections.Generic.List[string]
    $roots = @(
        (Join-Path $env:APPDATA 'Python'),
        (Join-Path $env:LOCALAPPDATA 'Programs\Python')
    )
    foreach ($root in $roots) {
        if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root -PathType Container)) {
            continue
        }
        $dirs = Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue |
            Sort-Object -Property Name -Descending
        foreach ($dir in $dirs) {
            $candidates.Add((Join-Path $dir.FullName $ExecutableName))
            $candidates.Add((Join-Path (Join-Path $dir.FullName 'Scripts') $ExecutableName))
        }
    }
    return $candidates.ToArray()
}

function Resolve-CommandSpec {
    <#
    .SYNOPSIS
        Resolve a command name (or absolute path) into a runnable spec.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name
    )

    $command = Get-Command -Name $Name -ErrorAction SilentlyContinue
    if ($null -ne $command) {
        return [pscustomobject]@{
            Available      = $true
            Command        = $command.Source
            PrefixArgs     = @()
            Source         = 'path'
            ResolvedVia    = $command.CommandType.ToString()
        }
    }

    foreach ($candidate in (Get-PythonScriptCandidates -ExecutableName ($Name + '.exe'))) {
        if (Test-Path -LiteralPath $candidate -PathType Leaf) {
            return [pscustomobject]@{
                Available   = $true
                Command     = $candidate
                PrefixArgs  = @()
                Source      = 'python-user-scripts'
                ResolvedVia = 'file'
            }
        }
    }

    return $null
}

function Get-CommandBaseName {
    <#
    .SYNOPSIS
        Lower-case executable base name of a resolved command path.
    #>
    [CmdletBinding()]
    param([string]$CommandPath)

    if ([string]::IsNullOrWhiteSpace($CommandPath)) {
        return ''
    }
    $leaf = Split-Path -Path $CommandPath -Leaf
    if ([string]::IsNullOrWhiteSpace($leaf)) {
        $leaf = $CommandPath
    }
    foreach ($suffix in @('.exe', '.bat', '.cmd', '.ps1', '.sh')) {
        if ($leaf.ToLowerInvariant().EndsWith($suffix)) {
            $leaf = $leaf.Substring(0, $leaf.Length - $suffix.Length)
            break
        }
    }
    return $leaf.ToLowerInvariant()
}

function Resolve-DeclaredToolPath {
    <#
    .SYNOPSIS
        Look for a tool inside the declared install target of a catalog row.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,
        [string]$InstallTarget
    )

    if ([string]::IsNullOrWhiteSpace($InstallTarget)) {
        return $null
    }
    $expanded = [System.Environment]::ExpandEnvironmentVariables($InstallTarget)
    if (-not (Test-Path -LiteralPath $expanded -PathType Container)) {
        return $null
    }

    $leafNames = @($Name, $Name + '.exe', $Name + '.bat', $Name + '.cmd')
    foreach ($leaf in $leafNames) {
        $direct = Join-Path $expanded $leaf
        if (Test-Path -LiteralPath $direct -PathType Leaf) {
            return $direct
        }
    }
    # apktool ships as apktool.bat next to apktool.jar; accept a one-level shim dir.
    $found = Get-ChildItem -LiteralPath $expanded -Recurse -File -Depth 2 -ErrorAction SilentlyContinue |
        Where-Object { (Get-CommandBaseName -CommandPath $_.Name) -eq $Name.ToLowerInvariant() } |
        Select-Object -First 1
    if ($null -ne $found) {
        return $found.FullName
    }
    return $null
}

function Get-ToolVersionString {
    <#
    .SYNOPSIS
        Best-effort version probe. Returns 'unknown' rather than a guess.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$CommandPath,
        [string[]]$VersionArguments = @()
    )

    if ($null -eq $VersionArguments -or $VersionArguments.Count -eq 0) {
        return 'unknown'
    }
    try {
        $output = & $CommandPath @VersionArguments 2>&1
        $text = ($output | Out-String).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) {
            return 'unknown'
        }
        $match = [regex]::Match($text, '\d+\.\d+(\.\d+)?([-.\w]+)?')
        if ($match.Success) {
            return $match.Value
        }
        return 'unknown'
    }
    catch {
        return 'unknown'
    }
}

function Resolve-ReverseToolSpec {
    <#
    .SYNOPSIS
        Resolve one reverse-engineering capability to a spec object.

    .OUTPUTS
        [pscustomobject] with Available, Name, Command, PrefixArgs, Source,
        Version, MinimumVersion, InstallCommand, InstallTarget, Kind.

        Available=$false is a normal answer: Command is $null and the caller
        decides whether to bootstrap or fail. Use Format-MissingDependency or
        Assert-ReverseTool to turn it into an actionable error.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,
        [switch]$NoVersionProbe
    )

    $catalogRow = Get-ReverseToolCatalog | Where-Object { $_.Name -eq $Name } | Select-Object -First 1

    $spec = [pscustomobject]@{
        Available       = $false
        Name            = $Name
        Command         = $null
        PrefixArgs      = @()
        Source          = 'unresolved'
        ResolvedVia     = 'none'
        Version         = 'unknown'
        MinimumVersion  = $(if ($null -ne $catalogRow) { $catalogRow.MinimumVersion } else { 'unspecified' })
        InstallCommand  = $(if ($null -ne $catalogRow) { $catalogRow.InstallCommand } else { 'no installer declared for ' + $Name })
        InstallTarget   = $(if ($null -ne $catalogRow) { $catalogRow.InstallTarget } else { $null })
        Kind            = $(if ($null -ne $catalogRow) { $catalogRow.Kind } else { 'undeclared' })
    }

    $resolved = Resolve-CommandSpec -Name $Name
    if ($null -ne $resolved) {
        $commandName = Get-CommandBaseName -CommandPath $resolved.Command
        if ($commandName -eq $Name.ToLowerInvariant() -or $resolved.ResolvedVia -eq 'Application') {
            $spec.Available = $true
            $spec.Command = $resolved.Command
            $spec.PrefixArgs = $resolved.PrefixArgs
            $spec.Source = $resolved.Source
            $spec.ResolvedVia = $resolved.ResolvedVia
        }
    }

    if (-not $spec.Available -and $null -ne $catalogRow) {
        $declared = Resolve-DeclaredToolPath -Name $Name -InstallTarget $catalogRow.InstallTarget
        if ($null -ne $declared) {
            $spec.Available = $true
            $spec.Command = $declared
            $spec.PrefixArgs = @()
            $spec.Source = 'declared-install-target'
            $spec.ResolvedVia = 'file'
        }
    }

    if ($spec.Available -and -not $NoVersionProbe -and $null -ne $catalogRow) {
        $spec.Version = Get-ToolVersionString -CommandPath $spec.Command -VersionArguments $catalogRow.VersionCommand
    }

    return $spec
}

function Format-MissingDependency {
    <#
    .SYNOPSIS
        Structured, copy-pasteable error text for a missing capability.

    .DESCRIPTION
        Every line is 'key=value' so a caller or a log parser can read it
        without guessing. It carries the tool name, the install command, the
        minimum version and where to fetch it - and never asserts readiness.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,
        [string]$Requester = 'this script',
        [string]$ExtraHint
    )

    $spec = Resolve-ReverseToolSpec -Name $Name
    $lines = @(
        'STRUCTURED_ERROR kind=missing-dependency',
        ('tool=' + $Name),
        ('requester=' + $Requester),
        ('minimum_version=' + $spec.MinimumVersion),
        ('observed_version=' + $spec.Version),
        ('install=' + $spec.InstallCommand),
        ('fetch=' + $(if ([string]::IsNullOrWhiteSpace($spec.InstallTarget)) { 'see install= above' } else { $spec.InstallTarget })),
        'next=install the tool, then re-run; this script will not continue without it'
    )
    if (-not [string]::IsNullOrWhiteSpace($ExtraHint)) {
        $lines += ('hint=' + $ExtraHint)
    }
    return ($lines -join [Environment]::NewLine)
}

function Assert-ReverseTool {
    <#
    .SYNOPSIS
        Return the spec for a capability or throw a structured error.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,
        [string]$Requester = 'this script',
        [string]$ExtraHint
    )

    $spec = Resolve-ReverseToolSpec -Name $Name
    if ($spec.Available) {
        return $spec
    }
    throw (Format-MissingDependency -Name $Name -Requester $Requester -ExtraHint $ExtraHint)
}

function Resolve-ReverseToolCommand {
    <#
    .SYNOPSIS
        Convenience wrapper: the command path for a capability, or a throw.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,
        [string]$Requester = 'this script'
    )

    return (Assert-ReverseTool -Name $Name -Requester $Requester).Command
}

function Write-StructuredError {
    <#
    .SYNOPSIS
        Emit a structured error block on stderr and return it as a string.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Message
    )

    [Console]::Error.WriteLine($Message)
    return $Message
}

