# Section 3: keystore identity helpers
# ---------------------------------------------------------------------------

function Get-KeystoreCertificateFingerprint {
    <#
    .SYNOPSIS
        SHA-256 certificate fingerprint of the signing identity in a keystore.

    .DESCRIPTION
        Resolution order, and why:

          1. -ExpectedFingerprint, when the caller supplies one. A value the
             operator verified out of band (openssl / keytool / the APK signer
             report) is authoritative.
          2. apksigner list --print-certs. Android's own tool; authoritative for
             exactly the question being asked (which certificate would sign this
             APK).
          3. keytool -list -v. The JDK's authoritative view.
          4. Read-DerCertificateFromPkcs12. LAST RESORT, and reported as
             low-confidence, see below.

        Confidence is part of the answer: the function returns Source and
        Confidence so a caller can require 'authoritative' where it matters.

        Why step 4 is only a fallback: a PKCS#12 certBag may be encoded as an
        encrypted or shrouded OCTET STRING rather than as a bare DER Certificate.
        This was verified on the retired
        skills/NPC-MOB-Delta-0004/debug.keystore: the DER certificate is NOT
        present as a contiguous byte string anywhere in the file, so a structural
        walk returns 'unavailable' and this function reports low confidence
        rather than a plausible-looking wrong fingerprint. Earlier during W12 a
        hand written walk DID return a wrong value (it hashed the inner
        Certificate SEQUENCE), which is exactly the failure mode this design
        avoids: never invent a fingerprint, report that it is unavailable.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Alias,
        [Parameter(Mandatory = $true)][string]$Password,
        [string]$Apksigner,
        [string]$Keytool,
        [string]$ExpectedFingerprint
    )

    $unavailable = [pscustomobject]@{
        Sha256     = $null
        Source     = 'unavailable'
        Confidence = 'none'
        Detail     = 'no tool and no supplied value produced a fingerprint'
    }

    if (-not [string]::IsNullOrWhiteSpace($ExpectedFingerprint)) {
        return [pscustomobject]@{
            Sha256     = $ExpectedFingerprint.ToUpperInvariant()
            Source     = 'caller-supplied'
            Confidence = 'authoritative'
            Detail     = 'value supplied by the operator'
        }
    }

    if (-not [string]::IsNullOrWhiteSpace($Apksigner) -and (Test-Path -LiteralPath $Apksigner -PathType Leaf)) {
        try {
            $output = & $Apksigner list --print-certs --ks $Path --ks-key-alias $Alias --ks-pass ('pass:' + $Password) 2>&1
            $text = ($output | Out-String)
            foreach ($pattern in @('SHA-256\s+digest:\s*([0-9A-Fa-f:]{40,})', 'SHA-256\s*:\s*([0-9A-Fa-f:]{40,})')) {
                $match = [regex]::Match($text, $pattern)
                if ($match.Success) {
                    return [pscustomobject]@{
                        Sha256     = $match.Groups[1].Value.ToUpperInvariant()
                        Source     = 'apksigner'
                        Confidence = 'authoritative'
                        Detail     = 'apksigner list --print-certs'
                    }
                }
            }
        }
        catch {
            $unavailable.Detail = 'apksigner probe failed: ' + $_.Exception.Message
        }
    }

    if (-not [string]::IsNullOrWhiteSpace($Keytool) -and (Test-Path -LiteralPath $Keytool -PathType Leaf)) {
        try {
            $output = & $Keytool -list -v -keystore $Path -storepass $Password -alias $Alias 2>&1
            $text = ($output | Out-String)
            $match = [regex]::Match($text, 'SHA256:\s*([0-9A-Fa-f:]{40,})')
            if ($match.Success) {
                return [pscustomobject]@{
                    Sha256     = $match.Groups[1].Value.ToUpperInvariant()
                    Source     = 'keytool'
                    Confidence = 'authoritative'
                    Detail     = 'keytool -list -v'
                }
            }
        }
        catch {
            $unavailable.Detail = 'keytool probe failed: ' + $_.Exception.Message
        }
    }

    $derived = Read-DerCertificateFromPkcs12 -Path $Path
    if (-not [string]::IsNullOrWhiteSpace($derived)) {
        return [pscustomobject]@{
            Sha256     = $derived
            Source     = 'pkcs12-der-walk'
            Confidence = 'low'
            Detail     = 'structural PKCS#12 walk; verify with apksigner or keytool before relying on it'
        }
    }

    return $unavailable
}

function Read-DerCertificateFromPkcs12 {
    <#
    .SYNOPSIS
        Attempt to read the DER certificate out of a PKCS#12 file structurally.

    .DESCRIPTION
        Walks PFX -> authSafe -> AuthenticatedSafe -> SafeContents ->
        SafeBag(certBag) and, when the bag value is a bare OCTET STRING holding a
        DER Certificate, returns its SHA-256 fingerprint as
        AA:BB:... uppercase hex.

        Returns $null when the container does not expose a bare certificate. It
        never returns a partially parsed or guessed value: an unfixable
        narrative of "probably this fingerprint" is worse than no fingerprint,
        because the caller would then trust a blacklist comparison that never
        ran on real bytes.
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][string]$Path)

    function Read-DerTlv {
        param([byte[]]$Buffer, [int]$Offset)
        if ($Offset + 2 -gt $Buffer.Length) { throw 'truncated DER header' }
        $tag = $Buffer[$Offset]
        $index = $Offset + 1
        $length = [int]$Buffer[$index]
        $index++
        if (($length -band 0x80) -ne 0) {
            $count = $length -band 0x7F
            if ($count -lt 1 -or $count -gt 4) { throw 'unsupported DER length form' }
            if ($index + $count -gt $Buffer.Length) { throw 'truncated DER length' }
            $length = 0
            for ($i = 0; $i -lt $count; $i++) {
                $length = ($length * 256) + [int]$Buffer[$index + $i]
            }
            $index += $count
        }
        return @{ Tag = $tag; Length = $length; RawStart = $Offset; HeaderEnd = $index; ValueStart = $index; ValueEnd = $index + $length }
    }

    function Test-DerCertificate {
        param([byte[]]$Candidate)
        # A DER Certificate is a SEQUENCE whose first element is another
        # SEQUENCE (the tbsCertificate). Accept only that shape.
        if ($Candidate.Length -lt 64) { return $false }
        if ($Candidate[0] -ne 0x30) { return $false }
        $inner = $Candidate[2]
        if (($inner -band 0x80) -ne 0) {
            $count = $inner -band 0x7F
            if ($count -lt 1 -or $count -gt 3) { return $false }
            $offset = 2 + $count
        }
        else {
            $offset = 2
        }
        if ($offset -ge $Candidate.Length) { return $false }
        return ($Candidate[$offset] -eq 0x30)
    }

    try {
        $bytes = [System.IO.File]::ReadAllBytes($Path)
        $top = Read-DerTlv -Buffer $bytes -Offset 0
        $cursor = $top.ValueStart
        $version = Read-DerTlv -Buffer $bytes -Offset $cursor
        $cursor = $version.ValueEnd
        $authSafe = Read-DerTlv -Buffer $bytes -Offset $cursor
        $oid = Read-DerTlv -Buffer $bytes -Offset $authSafe.ValueStart
        $explicit = Read-DerTlv -Buffer $bytes -Offset $oid.ValueEnd
        $octet = Read-DerTlv -Buffer $bytes -Offset $explicit.ValueStart
        $authSafeSeq = Read-DerTlv -Buffer $bytes -Offset $octet.ValueStart

        $walk = $authSafeSeq.ValueStart
        $seqEnd = $authSafeSeq.ValueEnd
        while ($walk -lt $seqEnd) {
            $contentInfo = Read-DerTlv -Buffer $bytes -Offset $walk
            $segEnd = $contentInfo.ValueEnd
            $ciOid = Read-DerTlv -Buffer $bytes -Offset $contentInfo.ValueStart
            $ciExplicit = Read-DerTlv -Buffer $bytes -Offset $ciOid.ValueEnd
            $ciOctet = Read-DerTlv -Buffer $bytes -Offset $ciExplicit.ValueStart
            $safeSeq = Read-DerTlv -Buffer $bytes -Offset $ciOctet.ValueStart
            if ($safeSeq.Tag -eq 0x30) {
                $bagCursor = $safeSeq.ValueStart
                $bagEnd = $safeSeq.ValueEnd
                while ($bagCursor -lt $bagEnd) {
                    $bag = Read-DerTlv -Buffer $bytes -Offset $bagCursor
                    $bagCursor = $bag.ValueEnd
                    $bagOid = Read-DerTlv -Buffer $bytes -Offset $bag.ValueStart
                    $bagValue = Read-DerTlv -Buffer $bytes -Offset $bagOid.ValueEnd
                    if ($bagValue.Tag -eq 0xA0) {
                        $probe = Read-DerTlv -Buffer $bytes -Offset $bagValue.ValueStart
                        if ($probe.Tag -eq 0x04) {
                            # Bare certificate inside the OCTET STRING.
                            $len = $probe.ValueEnd - $probe.ValueStart
                            $candidate = New-Object byte[] $len
                            [System.Array]::Copy($bytes, $probe.ValueStart, $candidate, 0, $len)
                            if (Test-DerCertificate -Candidate $candidate) {
                                $sha = [System.Security.Cryptography.SHA256]::Create()
                                try { $digest = $sha.ComputeHash($candidate) }
                                finally { $sha.Dispose() }
                                return (($digest | ForEach-Object { $_.ToString('X2') }) -join ':')
                            }
                        }
                    }
                }
            }
            $walk = $segEnd
        }
        [Console]::Error.WriteLine('info: ' + $Path + ' does not expose a bare DER certificate; fingerprint requires apksigner or keytool')
        return $null
    }
    catch {
        [Console]::Error.WriteLine('info: PKCS#12 structural walk failed for ' + $Path + ': ' + $_.Exception.Message)
        return $null
    }
}

