      "description": "Stable identifier of the finding. Producers emit '<SKILL_NAME with - replaced by _>-NNN', e.g. 'NPC_PEN_Cipher_0178-001' (all 22 build_finding implementations).",
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9_.:\\-]*$",
      "minLength": 1
    },
    "skill": {
      "description": "Owning skill identity that produced the finding, e.g. 'NPC-PEN-Cipher-0178'. Present in all 22 producers.",
      "type": "string",
      "minLength": 1
    },
    "timestamp": {
      "description": "Creation time. Producers emit UTC ISO-8601 via datetime.now(timezone.utc).isoformat(), e.g. '2026-10-14T04:12:34.567890+00:00'. The pattern admits the RFC3339 forms used across the package, including the 'Z' form shown in references/domains/03-pentest.md section 5.1.",
      "type": "string",
      "pattern": "^\\d{4}-\\d{2}-\\d{2}[Tt]\\d{2}:\\d{2}:\\d{2}(\\.\\d+)?([Zz]|[+-]\\d{2}:\\d{2})$"
    },
    "target": {
      "description": "Tested target. Must be inside the declared scope: references/scope-and-gates.md sections 3 and 7.",
      "type": "string",
      "minLength": 1
    },
    "title": {
      "description": "Short human-readable finding title.",
      "type": "string",
      "minLength": 1
    },
    "cve": {
      "description": "CVE identifier. Producers use the literal 'N/A' when no CVE applies (22/22 emit this field).",
      "type": "string",
      "minLength": 1
    },
    "cwe": {
      "description": "CWE identifier, e.g. 'CWE-693'. Present in all 22 producers.",
      "type": "string",
      "minLength": 1
    },
    "cvss_score": {
      "description": "CVSS base score. Numeric in all 22 producers (e.g. 8.0). Bounded by the CVSS base-score range; ordering by severity is required by references/domains/03-pentest.md section 4.7 (line 340).",
      "type": "number",
      "minimum": 0,
      "maximum": 10
    },
    "cvss_vector": {
      "description": "CVSS vector string, e.g. 'CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:L/A:L'. Present in all 22 producers.",
      "type": "string",
      "minLength": 1
    },
    "owasp_category": {
      "description": "OWASP category, e.g. 'A05:2021 - Security Misconfiguration'. Present in all 22 producers.",
      "type": "string",
      "minLength": 1
    },
    "mitre_attack": {
      "description": "MITRE ATT&CK technique identifier(s). Emitted as a single comma-separated string, e.g. 'T1610, T1611' (all 22 producers) - deliberately not an array, because that is the attested producer shape.",
      "type": "string",
      "minLength": 1
    },
    "severity": {
      "description": "Risk level. The accepted tokens are the union of the spellings attested in this package, because the package itself uses more than one casing. Lowercase 'critical|high|medium|low' is the machine vocabulary published in scripts/identity_policy.py:29 and emitted by the lowercase producers (e.g. skills/NPC-EDR-Ion-0009/scripts/agent.py:99). Title case is emitted by all 22 pentest producers, e.g. 'High' (skills/NPC-PEN-Cipher-0178/scripts/container_k8s.py, build_finding) and used in templates such as skills/NPC-EDR-Quartz-0092/assets/template.md:56. Uppercase appears in templates such as skills/NPC-EDR-Quartz-0092/assets/template.md:39. 'Informational' is attested at skills/NPC-EDR-Kite-0036/references/workflows.md:57. The localized four-level scale 严重/高危/中危/低危 is attested as a risk-level enumeration at skills/NPC-GEN-Umbra-0496/skills/报告编写-PentestReport.md:72. Not accepted: 'info' and 'none', which occur only as single loose prose variants without a level enumeration.",
      "type": "string",
      "enum": [
        "critical",
        "high",
        "medium",
        "low",
        "Critical",
        "High",
        "Medium",
        "Low",
        "Informational",
        "CRITICAL",
        "HIGH",
        "MEDIUM",
        "LOW",
        "严重",
        "高危",
        "中危",
        "低危"
      ]
    },
    "description": {
      "description": "What was found and why it matters.",
      "type": "string",
      "minLength": 1
    },
