      "type": "object"
    },
    "digest": {
      "description": "Payload digest, 'sha256:<64 hex>' (references/evidence-and-gates.md section 1).",
      "type": "string",
      "pattern": "^sha256:[0-9a-f]{64}$"
    },
    "evidence_id": {
      "description": "Back-reference to the evidence record, e.g. 'ev-0007'. Gate G7 requires every report conclusion to point back to an evidence_id (references/domains/03-pentest.md sections 4.7 and 5.4).",
      "type": "string",
      "minLength": 1
    },
    "claim": {
      "description": "The falsifiable claim this finding asserts, e.g. 'A 角色可读取 B 租户订单详情（BOLA）' (references/domains/03-pentest.md section 5.1).",
      "type": "string",
      "minLength": 1
    },
    "control": {
      "description": "Negative/positive control results. Section 4.4 rule 1 requires role A on own object, role A on another's object, role B on that object, and unauthenticated access; a 'success' without a control must be recorded as unverified. Gate G4 requires at least one success plus one negative control plus one repeat.",
      "type": "object",
      "properties": {
        "negative": {
          "description": "Expected-negative observation.",
          "type": "string"
        },
        "positive": {
          "description": "Expected-positive observation.",
          "type": "string"
        },
        "unauthenticated": {
          "description": "Unauthenticated observation.",
          "type": "string"
        }
      },
      "additionalProperties": true
